    [65] = { "Прискорення", "Збільшує вашу швидкість атаки на {1}% протягом {2} с.#speed by {1}% for {2} sec", en="Haste" },
    [66] = { "Мала невидимість", "Робить заклинача невидимим на {1} хв, проте це закляття вкрай нестабільне та може припинити свою дію завчасно.#for {1} min", "Мала невидимість.", en="Lesser Invisibility" },
    [67] = { "Відплата", nil, "Силу та спритність зменшено на {1}%.#by {1}", en="Vindication" },
    [71] = { "Захисна стійка", "Захисна стійка. Зменшує отриману шкоду на {1}%, а заподіяну на {2}%. Збільшує загрозу.#taken by {1}#caused by {2}", en="Defensive Stance" },
    [72] = { "Удар щитом", "Удар цілі щитом, що завдає {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Shield Bash" },
    [75] = { "Автоматична стрільба", "Автоматична стрільба по цілі, що діє до скасування.", "Стрільба по цілі.", en="Auto Shot" },
    [78] = { "Героїчний удар", "Сильна атака, що збільшує шкоду ближнього бою на {1} і спричиняє високий рівень загрози.#damage by {1}", en="Heroic Strike" },
    [81] = { "Ухилення", "Надає шанс ухилитися від атак ближнього бою.", en="Dodge" },
    [89] = { "Каліцтво", "Калічить ціль, знижуючи її швидкість руху на {1}%, а також збільшуючи інтервал між атаками ближнього бою на {2}% та інтервал між атаками дальнього бою на {3}%. Триває {4} с.#movement speed by {1}%#melee attacks by {2}%#ranged attacks by {3}%#Lasts {4} sec", "Швидкість руху зменшено на {1}%. Інтервал між атаками ближнього бою збільшено на {2}%. Інтервал між атаками дальнього бою збільшено на {3}%.#speed reduced by {1}%#melee attacks increased by {2}%#ranged attacks increased by {3}%", en="Cripple" },
    [96] = { "Розчленування", "Збільшує шкоду вашого наступного удару в ближньому бою на 100 та спричиняє кровотечу.", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Dismember" },
    [99] = { "Деморалізуючий рев", "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", "Силу атаки ближнього бою зменшено на {1}.#power by {1}", en="Demoralizing Roar" },
    [100] = { "Ривок", "Ривок у ворога, що збільшує лють на {1} і приголомшує його на {2} с. Не можна використовувати в бою.#generate {1} rage#for {2} sec", en="Charge" },
    [107] = { "Блок", "Надає шанс заблокувати ворожі атаки ближнього та дальнього бою.", en="Block" },
    [113] = { "Льодяні ланцюги", "Створює навколо ворога льодяні ланцюги, знерухомлюючи його на {1} с.#place for {1} sec", "Знерухомлено.", en="Chains of Ice" },
    [116] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [118] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [120] = { "Конус холоду", "Завдає цілям у конусі перед заклиначем [{1}#take {1} Frost][від {1} до {2}#take {1} to {2} Frost] шкоди кригою та сповільнює їх на {1}% протягом {2} с.#slowed by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Cone of Cold" },
    [122] = { "Крижаний спалах", "Вражає ворогів поруч із заклиначем, завдаючи [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди кригою, та приморожує їх на місці на {1} с. Подальше завдання шкоди може перервати дію цього ефекту.#up to {1} sec", "Приморожено.", en="Frost Nova" },
    [126] = { "Око Кілроґґа", "Викликає око Кілроґґа, яке заміняє ваш зір. Око швидко рухається, але є дуже вразливим.", "Керування оком Кілроґґа.", en="Eye of Kilrogg" },
    [128] = { "Камінь чарів", "Усуває всі магічні ефекти з заклинача та поглинає {1} магічної шкоди протягом {2} хв.#absorb {1} magic damage for {2} min", "Поглинає магічну шкоду.", en="Spellstone" },
    [130] = { "Повільне падіння", "Сповільнює падіння на {1} с.#for {1} sec", "Падіння сповільнено.", en="Slow Fall" },
    [131] = { "Водне дихання", "Дозволяє цілі дихати під водою протягом {1} хв.#for {1} min", "Водне дихання.", en="Water Breathing" },
    [133] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [136] = { "Зцілення вихованця", "Відновлює вашому вихованцю {1} здоров'я щосекунди поки ви зосереджуєтеся на зціленні. Триває {2} с.#pet {1} health#Lasts {2} sec", "Відновлює {1} здоров'я щосекунди.#Heals {1}", en="Mend Pet" },
    [139] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [143] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [145] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [168] = { "Крижаний обладунок", "Збільшує броню на {1}. Якщо ворог завдає удару заклиначеві, його рух може сповільнитися на {2}%, а інтервал між атаками збільшитися на {3}% протягом {4} с. Одночасно може бути активним лише один обладунок. Триває {5} хв.#Armor by {1}#slowed by {2}%#increased by {3}% for {4} sec#Lasts {5} min", "Збільшує броню на {1} та може сповільнити нападників.#Armor by {1}", en="Frost Armor" },
    [172] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Corruption" },
