    [439] = { "Зілля лікування", "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", en="Healing Potion" },
    [440] = { "Зілля лікування", "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", en="Healing Potion" },
