    [453] = { "Заспокоєння розуму", "Заспокоює ціль, зменшуючи відстань, на якій вона атакуватиме вас, на {1} м. Діє лише на гуманоїдів рівня {2} або нижче. Триває {3} с.#by {1} y#level {2} or lower#Lasts {3} sec", "Зменшено відстань, з якої ціль атакуватиме.", en="Mind Soothe" },
    [458] = { "Гнідий кінь", "Викликає та відпускає верхового гнідого коня.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Brown Horse" },
    [459] = { "Сірий вовк", "Викликає та відпускає верхового сірого вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Gray Wolf" },
    [465] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [467] = { "Шипи", "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", "Завдає {1} шкоди від природи нападникам.#Causes {1}", en="Thorns" },
    [468] = { "Білий жеребець", "Викликає та відпускає верхового білого жеребця.", "Швидкість руху збільшено на {1}%.#by {1}%", en="White Stallion" },
    [470] = { "Вороний жеребець", "Викликає та відпускає верхового вороного жеребця.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black Stallion" },
    [471] = { "Соловий кінь", "Викликає та відпускає верхового солового коня.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Palamino Stallion" },
    [472] = { "Рябий кінь", "Викликає та відпускає верхового рябого коня.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Pinto Horse" },
    [475] = { "Зняття малого прокляття", "Знімає {1} прокляття з дружньої цілі.#Removes {1}", en="Remove Lesser Curse" },
    [498] = { "Божественний захист", "Ви захищені від усіх фізичних атак і заклять на {1} с, але протягом цього часу не можете атакувати чи використовувати фізичні здібності. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", "Невразливість до всіх атак і заклять. Не може атакувати чи використовувати фізичні здібності.", en="Divine Protection" },
    [526] = { "Лікування отрути", "Виліковує {1} ефект отрути з цілі.#Cures {1} poison", en="Cure Poison" },
    [527] = { "Розвіювання магії", "Розвіює магію з цілі, знімаючи 1 негативний ефект з союзника або 1 сприятливий ефект з ворога.", en="Dispel Magic" },
    [528] = { "Лікування хвороби", "Знімає 1 хворобу з дружньої цілі.", en="Cure Disease" },
    [529] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [543] = { "Вогняний оберіг", "Поглинає {1} шкоди від вогню. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від вогню.", en="Fire Ward" },
    [546] = { "Ходіння по воді", "Дозволяє вибраному союзнику ходити по воді протягом {1} хв. Будь-яка шкода скасує ефект.#for {1} min", "Дозволяє ходити по воді.", en="Water Walking" },
    [547] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [548] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [552] = { "Усунення хвороби", "Намагається вилікувати 1 хворобу на цілі та ще 1 ефект хвороби кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Намагається усунути 1 ефект хвороби кожні {1} с.#every {1} sec", en="Abolish Disease" },
    [556] = { "Астральне повернення", "Повертає заклинача крізь Підсвітню Крутоверть додому. Поговоріть з корчмарем в іншому місці, щоб змінити домівку.", en="Astral Recall" },
    [568] = { "Арканічний сплеск", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Arcane Burst" },
    [578] = { "Чорний вовк", "Викликає та відпускає верхового чорного вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black Wolf" },
    [579] = { "Рудий вовк", "Викликає та відпускає верхового рудого вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Red Wolf" },
    [580] = { "Великий лісовий вовк", "Викликає та відпускає верхового лісового вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Large Timber Wolf" },
    [581] = { "Сніжний вовк", "Викликає та відпускає верхового сніжного вовка.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Winter Wolf" },
    [585] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [586] = { "Розтанення", "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с.#for {1} sec", "Рівень загрози зменшено.", en="Fade" },
    [587] = { "Начаклування їжі", "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min", en="Conjure Food" },
    [588] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [589] = { "Слово тіні: Біль", "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Shadow Word: Pain" },
    [591] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [592] = { "Слово сили: Щит", "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", "Поглинає шкоду.", en="Power Word: Shield" },
    [594] = { "Слово тіні: Біль", "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Shadow Word: Pain" },
    [596] = { "Молитва зцілення", "Потужна молитва, що зцілює всім учасникам групи в межах {1} м від {2} до {3} здоров'я.#within {1} yards for {2} to {3}", en="Prayer of Healing" },
    [597] = { "Начаклування їжі", "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min", en="Conjure Food" },
    [598] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [600] = { "Слово сили: Щит", "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", "Поглинає шкоду.", en="Power Word: Shield" },
    [602] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [604] = { "Пом'якшення магії", "Послаблює магію на обраному учаснику групи, зменшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", "Зменшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}", en="Dampen Magic" },
    [605] = { "Контроль розуму", "Бере під контроль розум гуманоїда не вище {1} рівня, але збільшує інтервал між його атаками на {2}%. Триває до {3} хв.#up to level {1}#attacks by {2}%#Lasts up to {3} min", "Причаровано. Інтервал між атаками збільшено на {1}%.#by {1}%", en="Mind Control" },
    [633] = { "Покладання рук", "Зцілює дружню ціль на значення, що дорівнює максимальному запасу здоров'я паладина. Витрачає весь залишок мани паладина при використанні.", en="Lay on Hands" },
    [635] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [639] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [642] = { "Божественний щит", "Захищає паладина від будь-якої шкоди та заклять на {1} с, але [збільшує інтервал між вашими атаками на {1}%#time between your attacks by {1}%][зменшує всю вашу шкоду на {1}%#reduces all damage you deal by {1}%]. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", "Невразливість до всіх атак і заклять, але [інтервал між атаками збільшено на {1}%#time between your attacks by {1}%][всю завдану шкоду зменшено на {1}%#all damage you deal by {1}%].", en="Divine Shield" },
    [643] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [647] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [674] = { "Бій з двох рук", "Дозволяє брати в ліву руку одноручну зброю або зброю для лівої руки.", en="Dual Wield" },
    [676] = { "Роззброєння", "Роззброює ворога на {1} с.#for {1} sec", "Роззброєно!", en="Disarm" },
    [686] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [687] = { "Демонічна шкіра", "Захищає заклинача, збільшуючи броню на {1} та відновлюючи {2} здоров'я кожні {3} с протягом {4} хв.#armor by {1} and restores {2} Health per {3} sec. for {4} min", "Збільшує броню на {1} та відновлює {2} здоров'я кожні {3} с.#armor by {1} and restores {2} Health per {3} sec", en="Demon Skin" },
    [688] = { "Виклик біса", "Викликає біса, підкореного чорнокнижникові.", en="Summon Imp" },
    [689] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [690] = { "Вогняна стріла II", "Завдає цілі від {1} до {2} шкоди вогнем.#for {1} to {2} Fire", en="Firebolt II" },
    [691] = { "Виклик скверногончої", "Викликає скверногончу, підкорену чорнокнижникові.", en="Summon Felhunter" },
    [694] = { "Глумливий удар", "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", "Спровоковано.", en="Mocking Blow" },
    [695] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [696] = { "Демонічна шкіра", "Захищає заклинача, збільшуючи броню на {1} та відновлюючи {2} здоров'я кожні {3} с протягом {4} хв.#armor by {1} and restores {2} Health per {3} sec. for {4} min", "Збільшує броню на {1} та відновлює {2} здоров'я кожні {3} с.#armor by {1} and restores {2} Health per {3} sec", en="Demon Skin" },
    [697] = { "Виклик пустотника", "Викликає пустотника, підкореного чорнокнижникові.", en="Summon Voidwalker" },
    [698] = { "Ритуал виклику", "Починає ритуал, що викликає обраного учасника групи. Для завершення ритуалу потрібна допомога 2 учасників групи. Щоб узяти участь у ритуалі, усі гравці повинні бути поза боєм, натиснути правою кнопкою миші на портал і не рухатися до завершення ритуалу.", en="Ritual of Summoning" },
    [699] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [700] = { "Сон", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [701] = { "Вогняна стріла", "Завдає цілі {1} шкоди вогнем.#for {1} Fire", en="Firebolt" },
    [702] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [703] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [704] = { "Прокляття відчайдушності", "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", en="Curse of Recklessness" },
    [705] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [706] = { "Демонічний обладунок", "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", en="Demon Armor" },
    [707] = { "Жертовний вогонь", "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Immolate" },
    [709] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [710] = { "Вигнання", "Виганяє ворожу ціль до іншого виміру, перешкоджаючи всім її діям, але при цьому робить її невразливою протягом {1} с. Одночасно лише одна ціль може бути вигнаною. Діє лише на демонів та елементалів.#for up to {1} sec", "Невразливість, але неможливо виконувати будь-які дії.", en="Banish" },
    [712] = { "Виклик сукуба", "Викликає сукуба, підкореного чорнокнижникові.", en="Summon Succubus" },
    [713] = { "Виклик інкуба", "Викликає інкуба, підкореного чорнокнижникові.", en="Summon Incubus" },
    [720] = { "Обплетення", nil, "Обплетено", en="Entangle" },
    [724] = { "Колодязь світла", "Створює священний колодязь світла біля жерця. Учасники вашої групи чи рейду можуть випити з нього щоб відновити {1} здоров'я протягом {2} с. Будь-яка отримана шкода знімає цей ефект. Колодязь існує {3} хв або до {4} застосувань.#restore {1} health over {2} sec#lasts for {3} min or {4} charges", en="Lightwell" },
    [731] = { "Обплетення", nil, "Обплетено", en="Entangle" },
    [740] = { "Спокій", "Відновлює всім учасникам групи неподалік {1} здоров'я кожні {2} с протягом {3} с. Друїд має підтримувати закляття.#for {1} every {2} seconds for {3} sec", "Зцілює учасникам групи неподалік {1} здоров'я кожні {2} с.#for {1} every {2} sec", en="Tranquility" },
    [744] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [746] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [750] = { "Лати", en="Plate Mail" },
    [755] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [759] = { "Начаклування маноагату", "Начаклувати маноагат, який можна використати для миттєвого відновлення від {1} до {2} мани.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на 15 хвилин.#restore {1} to {2}", en="Conjure Mana Agate" },
    [768] = { "Котяча подоба", "Набути котячої подоби, що збільшує силу атаки ближнього бою на {1} плюс показник спритності. Також захищає заклинача від ефектів поліморфії та дозволяє використання котячих здібностей.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#power by {1} plus", "Невразливість до ефектів поліморфії. Збільшує силу атаки ближнього бою на {1} плюс показник спритності.#power by {1} plus", en="Cat Form" },
    [769] = { "Розмах", "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", en="Swipe" },
    [770] = { "Чарівний вогонь", "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Faerie Fire" },
    [772] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [774] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [778] = { "Чарівний вогонь", "Зменшує броню цілі на {1} протягом {2} с. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Faerie Fire" },
    [779] = { "Розмах", "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", en="Swipe" },
    [780] = { "Розмах", "Вдарити {1} ворогів поблизу, завдаючи {2} шкоди.#Swipe {1} nearby#inflicting {2} damage", en="Swipe" },
    [781] = { "Відступ", "Провести спробу відступити від цілі, зменшуючи загрозу. Персонаж виходить з бою.", en="Disengage" },
    [782] = { "Шипи", "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", "Завдає {1} шкоди від природи нападникам.#Causes {1}", en="Thorns" },
    [783] = { "Мандрівна подоба", "Набути мандрівної подоби, що збільшує швидкість руху на {1}%. Також захищає заклинача від ефектів поліморфії. Можна використовувати лише просто неба.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#speed by {1}%", "Невразливість до ефектів поліморфії. Швидкість руху збільшено на {1}%.#by {1}%", en="Travel Form" },
    [785] = { "Істинне щастя", nil, "Причаровано.\nШкоду збільшено на {1}%.\nЗакляття вимовляються миттєво.\nВсі опори збільшено на {2}.\nШвидкість руху збільшено на {3}%.#Damage increased by {1}%#resistances increased by {2}#speed increased by {3}%", en="True Fulfillment" },
    [806] = { "Палкість", "Збільшує силу на {1} та завдає вам {2} шкоди кожні {3} с протягом {4} хв.#by {1} and does {2} damage to you every {3} sec for {4} min", "Силу збільшено. Отримання періодичної шкоди.", en="Fervor" },
    [812] = { "Періодичне спалення мани", "Періодично застосовує спалення мани.", "Періодично застосовує спалення мани.", en="Periodic Mana Burn" },
    [818] = { "Звичайне вогнище", "Розпалити вогнище, яке дозволяє готувати їжу та підвищує дух навколишніх персонажів на {1}.#those nearby by {1} and", en="Basic Campfire" },
    [833] = { "Зелений чай", "Миттєво відновлює {1} здоров'я. Також відновлює {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі.#heals {1} damage#restores {2} mana over {3} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Green Tea" },
    [834] = { "Мале підвищення броні", "Збільшує броню на {1} протягом {2} год.#by {1} for {2} h", "Броню збільшено на {1}.#by {1}", en="Lesser Armor" },
    [835] = { "Оберіг припливу", ref=56, en="Tidal Charm" },
    [837] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [845] = { "Розсічення", "Розмашиста атака, що завдає шкоди зброєю плюс {1} по цілі та по найближчому до неї ворогу.#damage plus {1} to", en="Cleave" },
    [853] = { "Молот правосуддя", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Hammer of Justice" },
    [865] = { "Крижаний спалах", "Вражає ворогів поруч із заклиначем, завдаючи [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди кригою, та приморожує їх на місці на {1} с. Подальше завдання шкоди може перервати дію цього ефекту.#up to {1} sec", "Приморожено.", en="Frost Nova" },
    [871] = { "Стіна щитів", "Зменшує отриману шкоду від атак ближнього бою, дальнього бою та заклять на {1}% протягом {2} с.#by {1}% for {2} sec", "Отриману шкоду зменшено на {1}%.#reduced by {1}%", en="Shield Wall" },
    [879] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [883] = { "Виклик вихованця", "Викликає вашого вихованця.", en="Call Pet" },
    [905] = { "Блискавковий щит", "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", en="Lightning Shield" },
    [913] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [915] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [921] = { "Кишенькова крадіжка", "Обнишпорити кишені цілі.", en="Pick Pocket" },
    [930] = { "Ланцюгова блискавка", "Кидає в ціль блискавку, що завдає від {1} до {2} шкоди від природи та перестрибує на інших ворогів неподалік. Кожен стрибок завдає на {3}% менше шкоди. Вражає до {4} цілей.#dealing {1} to {2}#damage by {3}#{4} total targets.", en="Chain Lightning" },
    [939] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [943] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [945] = { "Блискавковий щит", "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", en="Lightning Shield" },
    [959] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [970] = { "Слово тіні: Біль", "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Shadow Word: Pain" },
    [976] = { "Захист від тіні", "Збільшує опір цілі до тіні на {1} протягом {2} хв.#by {1} for {2} min", "Опір тіні збільшено на {1}.#by {1}", en="Shadow Protection" },
    [982] = { "Оживлення вихованця", "Оживляє вашого вихованця, повертаючи його до життя з {1}% здоров'я.#with {1}%", en="Revive Pet" },
    [984] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [988] = { "Розвіювання магії", "Розвіює магію з цілі, знімаючи 2 негативні ефекти з союзника або 2 сприятливі ефекти з ворога.", en="Dispel Magic" },
    [990] = { "Начаклування їжі", "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min", en="Conjure Food" },
    [992] = { "Слово тіні: Біль", "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Shadow Word: Pain" },
    [996] = { "Молитва зцілення", "Потужна молитва, що зцілює всім учасникам групи в межах {1} м від {2} до {3} здоров'я.#within {1} yards for {2} to {3}", en="Prayer of Healing" },
    [1002] = { "Очі звіра", "Узяти безпосередній контроль над вашим вихованцем і бачити його очима протягом {1} хв.#for {1} min", "Безпосередній контроль вихованця.", en="Eyes of the Beast" },
    [1004] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [1006] = { "Внутрішній вогонь", "Сплеск священної енергії наповнює заклинача, збільшуючи броню на {1}. Кожна атака ближнього чи дальнього бою проти жерця знімає один заряд ефекту. Триває {2} хв або поки не буде використано {3} зарядів.#armor by {1}#Lasts {2} min or until {3} charges", "Збільшує броню на {1}.#by {1}", en="Inner Fire" },
    [1008] = { "Підсилення магії", "Підсилює магію на обраному учаснику групи, збільшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", "Збільшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}", en="Amplify Magic" },
    [1020] = { "Божественний щит", "Захищає паладина від будь-якої шкоди та заклять на {1} с, але [збільшує інтервал між вашими атаками на {1}%#time between your attacks by {1}%][зменшує всю вашу шкоду на {1}%#reduces all damage you deal by {1}%]. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", "Невразливість до всіх атак і заклять, але [інтервал між атаками збільшено на {1}%#time between your attacks by {1}%][всю завдану шкоду зменшено на {1}%#all damage you deal by {1}%].", en="Divine Shield" },
    [1022] = { "Благословення захисту", "Захищає обраного учасника групи від усіх фізичних атак на {1} с, але протягом цього часу ціль не може атакувати чи використовувати фізичні здібності. Гравці можуть мати лише одне благословення від кожного паладина одночасно. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" повторно протягом {2} хв.#attacks for {1} sec#again for {2} min", "Невразливість до фізичних атак. Не може атакувати чи використовувати фізичні здібності.", en="Blessing of Protection" },
    [1026] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [1032] = { "Аура відданості", "Надає {1} додаткової броні учасникам групи в радіусі {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#within {2} y", "Збільшує броню на {1}.#by {1}", en="Devotion Aura" },
    [1038] = { "Благословення спасіння", "Благословляє учасника групи, зменшуючи його загрозу на {1}% протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1}% for {2} min", "Зменшує загрозу на {1}%.#by {1}%", en="Blessing of Salvation" },
    [1042] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [1044] = { "Благословення свободи", "Благословляє дружню ціль, надаючи невразливість до ефектів обмеження руху на {1} с. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#for {1} sec", "Невразливість до ефектів обмеження руху.", en="Blessing of Freedom" },
    [1058] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [1062] = { "Опутуюче коріння", "Приковує ціль на місці та завдає {1} шкоди від природи протягом {2} с. Подальша завдана шкода може перервати дію ефекту. Можна використовувати лише просто неба.#causes {1}#over {2} sec", "Приковано. Завдає {1} шкоди від природи кожні {2} с.#Causes {1}#every {2} sec", en="Entangling Roots" },
    [1064] = { "Ланцюгове зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я та перестрибує на інші цілі неподалік. Якщо закляття було націлене на учасника групи, подальші стрибки переходитимуть лише на інших її учасників. Кожен наступний стрибок зцілює на {3}% менше здоров'я. Зцілює до {4} цілей.#for {1} to {2}#{3}% as effective#Heals {4} total", en="Chain Heal" },
    [1066] = { "Водна подоба", "Набути водної подоби, що збільшує швидкість плавання на {1}% та дозволяє дихати під водою. Також захищає заклинача від ефектів поліморфії.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#speed by {1}%", "Невразливість до ефектів поліморфії. Збільшує швидкість плавання на {1}% та дозволяє дихати під водою.#speed by {1}%", en="Aquatic Form" },
    [1075] = { "Шипи", "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", "Завдає {1} шкоди від природи нападникам.#Causes {1}", en="Thorns" },
    [1079] = { "Розірвання", "Завершальний рух, що завдає шкоди з часом. Шкода збільшується залежно від довжини комбінації та сили атаки:\n  1 прийом: {1} шкоди за {2} cекунд\n  2 прийоми: {3} шкоди за {4} cекунд\n  3 прийоми: {5} шкоди за {6} cекунд\n  4 прийоми: {7} шкоди за {8} cекунд\n  5 прийомів: {9} шкоди за {10} cекунд#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "Шкода від кровотечі кожні {1} с.#every {1} sec", en="Rip" },
    [1082] = { "Дряпання", "Дряпає ворога, завдаючи {1} додаткової шкоди. Збільшує довжину комбінації на {2} прийом.#causing {1}#{2} combo", en="Claw" },
    [1084] = { "Вогняна стріла III", ref=690, en="Firebolt III" },
    [1086] = { "Демонічний обладунок", "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", en="Demon Armor" },
    [1088] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [1090] = { "Сон", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [1094] = { "Жертовний вогонь", "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Immolate" },
    [1096] = { "Вогняна стріла IV", ref=690, en="Firebolt IV" },
    [1098] = { "Поневолення демона", "Поневолює обраного демона до {1} рівня, примушуючи його підкоритися вам. Протягом дії поневолення інтервал між атаками демона збільшується на {2}%, а його вимова заклять сповільнюється на {3}%. Триває до {4} хв. Якщо ви знову поневолюватимете одного й того ж демона, його буде важче контролювати з кожною наступною спробою.#up to level {1}#increased by {2}%#slowed by {3}%#up to {4} min", "Поневолено.", en="Subjugate Demon" },
    [1106] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [1108] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [1120] = { "Висмоктування душі", "Висмоктує душу з цілі, завдаючи {1} шкоди тінню протягом {2} с. Якщо ціль під час цього помирає та приносить досвід або честь, заклинач отримує уламок душі. Уламки душі потрібні для інших заклять.#causing {1}#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2}", en="Drain Soul" },
    [1121] = { "Обплетення", nil, "Обплетено", en="Entangle" },
    [1122] = { "Пекло", "Викликає метеорит з Підсвітньої Крутоверті, що завдає {1} шкоди вогнем і приголомшує всі ворожі цілі в місці падіння на {2} с. З кратера підіймається пекельник, підкорений заклиначеві на {3} хв. Після закінчення цього часу пекельника потрібно поневолити, щоб продовжити керувати ним. Можна використовувати лише просто неба.#causing {1} Fire#area for {2} sec#caster for {3} min", en="Inferno" },
    [1126] = { "Знак дикої природи", "Збільшує броню дружньої цілі на {1} на {2} хв.#armor by {1} for {2} min", "Збільшує броню на {1}.#armor by {1}", en="Mark of the Wild" },
    [1127] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [1129] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [1130] = { "Мітка мисливця", "Відмічає ціль мисливською міткою, збільшуючи силу атаки дальнього бою всіх нападників проти відміченої цілі на {1}. Окрім того мисливець завжди бачить відмічену ціль, навіть якщо та стає непомітною або невидимою. Ціль також відображається на мінімапі. Триває {2} хв.#target by {1}#Lasts for {2} min", "Всі нападники отримують додатково {1} сили атаки дальнього бою проти цієї цілі.#gain {1} Ranged", en="Hunter's Mark" },
    [1131] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [1133] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [1135] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [1137] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [1138] = { "Кришталевий захист", "Збільшує опір кризі та тіні на {1} протягом {2} хв.#by {1} for {2} min", "Опір кризі та тіні збільшено.", en="Crystal Protection" },
    [1139] = { "Холодне око", "Збільшує інтервал між атаками цілі на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість атак зменшено.", en="Cold Eye" },
    [1152] = { "Омовіння", "Очищує дружню ціль, знімаючи 1 ефект хвороби та 1 ефект отруєння.", en="Purify" },
    [1159] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я щосекунди.#Healing {1} damage", en="First Aid" },
    [1160] = { "Деморалізуючий клич", "Зменшує силу атаки ближнього бою всіх ворогів в межах {1} м на {2} протягом {3} с.#within {1} yards by {2} for {3} sec", "Зменшує силу атаки ближнього бою на {1}.#power by {1}", en="Demoralizing Shout" },
    [1161] = { "Провокуючий клич", "Змушує всіх ворогів навколо атакувати вас протягом {1} с.#for {1} sec", "Спровоковано.", en="Challenging Shout" },
    [1180] = { "Кинджали", en="Daggers" },
    [1243] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [1244] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [1245] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [1329] = { "Скалічити", "Миттєва атака зброєю в обох руках, що завдає {1}% та додатково {2} шкоди від кожної зброї. Шкода збільшується на {3}% проти отруєних цілей. Збільшує довжину комбінації на {4} прийоми.#weapons for {1}% weapon#additional {2} with each#by {3}% against Poisoned#Awards {4} combo", en="Mutilate" },
    [1386] = { "Відлуння Лордерона", nil, "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%", en="Echoes of Lordaeron" },
    [1430] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [1449] = { "Арканічний вибух", "Створює вибух арканічної магії навколо заклинача, завдаючи від {1} до {2} шкоди арканою всім цілям у радіусі {3} м.#causing {1} to {2}#within {3} yards", en="Arcane Explosion" },
    [1454] = { "Витік життя", "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana", en="Life Tap" },
    [1455] = { "Витік життя", "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana", en="Life Tap" },
    [1456] = { "Витік життя", "Перетворює {1} здоров'я на {2} мани.#{1} health into {2} mana", en="Life Tap" },
    [1459] = { "Арканічний інтелект", "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", "Збільшує інтелект на {1}.#by {1}", en="Arcane Intellect" },
    [1460] = { "Арканічний інтелект", "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", "Збільшує інтелект на {1}.#by {1}", en="Arcane Intellect" },
    [1461] = { "Арканічний інтелект", "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", "Збільшує інтелект на {1}.#by {1}", en="Arcane Intellect" },
    [1462] = { "Знання звіра", "Збирає інформацію про вибраного звіра. Підказка відобразить шкоду, здоров'я, броню, особливі опори та дієту.", "Знання виявлено.", en="Beast Lore" },
    [1463] = { "Щит мани", "Поглинає {1} фізичної шкоди за рахунок мани. Випалює {2} мани за кожну одиницю поглинутої шкоди. Триває {3} хв.#Absorbs {1} physical#Drains {2} mana#Lasts {3} min", "Поглинає фізичну шкоду за рахунок мани.", en="Mana Shield" },
    [1464] = { "Розтрощення", "Трощить ворога, завдаючи шкоди зброєю плюс {1}.#damage plus {1}", en="Slam" },
    [1494] = { "Вистежування звірів", "Відображає на мінімапі місцезнаходження звірів неподалік. Одночасно можна вистежувати лише щось одне.", "Вистежування звірів.", en="Track Beasts" },
    [1495] = { "Укус мангусти", "Контратакує ворога, завдаючи {1} шкоди. Можна виконати лише після того, як ви ухилилися.#for {1} damage", en="Mongoose Bite" },
    [1499] = { "Заморожувальна пастка", "Встановити крижану пастку, яка заморозить першого ворога при наближенні та унеможливить всі його дії впродовж {1} с. Будь-яка шкода розіб'є лід. Пастка існуватиме {2} хв. Пастки можна встановлювати лише поза боєм. Одночасно може бути активною лише одна пастка.#action for up to {1} sec#exist for {2} min", en="Freezing Trap" },
    [1510] = { "Обстріл", "Безперервно обстрілює вибране місце, завдаючи {1} шкоди від аркани ворожим цілям в межах {2} м щосекунди протягом {3} с.#causing {1}#within {2} y#for {3} sec", en="Volley" },
    [1513] = { "Відлякування звіра", "Відлякує звіра, змушуючи його тікати з переляку протягом {1} с. Завдана шкода може перервати ефект. Одночасно лише один звір може бути наляканим.#for up to {1} sec", "Налякано.", en="Scare Beast" },
    [1515] = { "Приручення звіра", "Почати приручення звіра, який стане вашим супутником. Ваша броня знижується на {1}%, поки ви зосереджуєтеся на процесі приручення звіра протягом {2} с. Якщо ви втратите увагу звіра з будь-якої причини, процес приручення провалиться. Після приручення, звір буде дуже нещасливим та недовірливим. Спробуйте одразу погодувати вихованця, щоб зробити його щасливим.#by {1}%#for {2} sec", "Приручення вихованця.", en="Tame Beast" },
    [1539] = { "Ефект годування вихованця", nil, "Збільшує щастя.", en="Feed Pet Effect" },
    [1543] = { "Освітлювальна ракета", "Викриває всіх прихованих та невидимих ворогів в межах {1} м від вибраного місця протягом {2} с.#within {1} y#for {2} sec", "Виявлення прихованих та невидимих істот.", en="Flare" },
    [1604] = { "Запаморочення", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Dazed" },
    [1608] = { "Героїчний удар", "Сильна атака, що збільшує шкоду ближнього бою на {1} і спричиняє високий рівень загрози.#damage by {1}", en="Heroic Strike" },
    [1671] = { "Удар щитом", "Удар цілі щитом, що завдає {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Shield Bash" },
    [1672] = { "Удар щитом", "Удар цілі щитом, що завдає {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Shield Bash" },
    [1680] = { "Вихор", "Ви атакуєте до {1} ворогів в межах {2} м сталевим вихром, завдаючи шкоди зброєю кожному ворогу.#up to {1} enemies within {2} yards", en="Whirlwind" },
    [1706] = { "Левітація", "Дозволяє заклиначу левітувати, плинучи невисоко над землею. Під час левітації ви падатимете зі зниженою швидкістю та зможете ходити по воді. Будь-яка шкода скасує цей ефект. Триває {1} хв.#Lasts {1} min", "Левітує.", en="Levitate" },
    [1714] = { "Прокляття мови", "Примушує ціль говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}%. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі. Триває {2} с.#by {1}%#Lasts {2} sec", "Говорить мовою демонів, що збільшує час вимови заклять на {1}%.#by {1}%", en="Curse of Tongues" },
    [1715] = { "Нівечення", "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Hamstring" },
    [1719] = { "Навіженість", "[Воїн буде завдавати критичних ударів більшістю своїх атак та#cause critical hits with most attacks][Ймовірність критичного удару збільшиться на {1}%, а воїн#will gain {1}% increased critical strike chance] отримає невразливість до ефектів страху протягом {1} с, але отримана шкода збільшиться на {2}%.#next {1} sec#increased by {2}", "Невразливість до ефектів страху, більшість атак завдають критичних ударів[, але отриману шкоду збільшено на {1}%#damage taken is increased by {1}%].", en="Recklessness" },
    [1725] = { "Відволікання", "Метнути приманку, що відволіче увагу всіх ворогів поблизу на {1} с. Не порушує непомітності.#for {1} sec", en="Distract" },
    [1735] = { "Деморалізуючий рев", "Друїд реве, зменшуючи силу атаки ближнього бою навколишніх ворогів на {1}. Триває {2} с.#power by {1}#Lasts {2} sec", "Силу атаки ближнього бою зменшено на {1}.#power by {1}", en="Demoralizing Roar" },
    [1742] = { "Зіщулювання", "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", en="Cower" },
    [1752] = { "Підступний удар", "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", en="Sinister Strike" },
    [1753] = { "Зіщулювання", "Зіщулитися, не завдаючи шкоди, але зменшуючи вашу загрозу та знижуючи ймовірність того, що ворог атакуватиме саме вас.", en="Cower" },
