    [1768] = { "Копняк", "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Kick" },
    [1769] = { "Копняк", "Швидкий удар ногою, що завдає {1} шкоди. Також перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Kick" },
    [1776] = { "Ошелешення", "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", "Недієздатність.", en="Gouge" },
    [1777] = { "Ошелешення", "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", "Недієздатність.", en="Gouge" },
    [1784] = { "Непомітність", "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", "Непомітність. Рух сповільнено на {1}%.#by {1}%", en="Stealth" },
    [1785] = { "Непомітність", "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", "Непомітність. Рух сповільнено на {1}%.#by {1}%", en="Stealth" },
    [1786] = { "Непомітність", "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", "Непомітність. Рух сповільнено на {1}%.#by {1}%", en="Stealth" },
    [1787] = { "Непомітність", "Дозволяє пройдисвіту пересуватися непомітно, знижує швидкість руху на {1}%. Триває до скасування.#by {1}%", "Непомітність. Рух сповільнено на {1}%.#by {1}%", en="Stealth" },
    [1804] = { "Зламування замків", "Дозволяє відкривати замкнені скрині та двері.", en="Pick Lock" },
    [1822] = { "Роздирання", "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [1823] = { "Роздирання", "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [1824] = { "Роздирання", "Роздирає ціль, завдаючи {1} шкоди та додатково {2} шкоди протягом {3} с. Збільшує довжину комбінації на {4} прийом.#for {1} damage and an additional {2} damage over {3} sec#{4} combo", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [1833] = { "Брудний прийом", "Приголомшує ціль на {1} с. Необхідно перебувати в непомітності. Збільшує довжину комбінації на {2} прийоми.#for {1} sec#{2} combo", "Приголомшено.", en="Cheap Shot" },
    [1842] = { "Знешкодження пасток", "Підкрастися до пастки та знешкодити її. Не наближайтеся занадто близько, інакше пастка спрацює.", en="Disarm Trap" },
    [1850] = { "Порив", "Збільшує швидкість руху на {1}% протягом {2} с. Не перериває дію здібності \"Зачаїтися\".#speed by {1}% for {2} sec", "Швидкість руху збільшено на {1}%.#by {1}%", en="Dash" },
    [1853] = { "Рик", "Провокує ціль, збільшуючи ймовірність того, що вона зосередить свої атаки на вас.", en="Growl" },
    [1856] = { "Зникнення", "Дозволяє пройдисвіту зникнути з поля зору ворогів, увійшовши в стан покращеної непомітності на {1} с. Також знімає всі ефекти обмеження руху.#for {1} sec", "Покращена непомітність.", en="Vanish" },
    [1857] = { "Зникнення", "Дозволяє пройдисвіту зникнути з поля зору ворогів, увійшовши в стан покращеної непомітності на {1} с. Також знімає всі ефекти обмеження руху.#for {1} sec", "Покращена непомітність.", en="Vanish" },
    [1860] = { "Безпечне падіння", "Зменшує шкоду від падіння.", en="Safe Fall" },
    [1906] = { "Виснажливий ривок", "Ривок у ворога, що сповільнює його рух на {1} с.#for {1} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Debilitating Charge" },
    [1940] = { "Вибух ракети", "Завдає від {1} до {2} шкоди вогнем в радіусі {3} м.#Inflicts {1} to {2} Fire#a {3} yard", en="Rocket Blast" },
    [1943] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [1949] = { "Пекельний вогонь", "Підпалює землю навколо заклинача, щосекунди завдаючи {1} шкоди вогнем йому та {2} шкоди вогнем усім ворогам поблизу. Триває {3} с.#causing {1}#and {2}#Lasts {3} sec", "Завдає шкоди собі та всім навколишнім ворогам.", en="Hellfire" },
    [1953] = { "Блим", "Телепортує заклинача на {1} м уперед, якщо на шляху немає перешкод. Також звільняє від приголомшень та пут.#caster {1} yards", "Блимає.", en="Blink" },
    [1966] = { "Фінт", "Виконує оманливий випад, що не завдає шкоди та трохи зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Feint" },
    [1978] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [2006] = { "Воскресіння", "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Resurrection" },
    [2008] = { "Дух пращурів", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Ancestral Spirit" },
    [2010] = { "Воскресіння", "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Resurrection" },
    [2018] = { "Ковальство", "Дозволяє виготовляти просту зброю і обладунки та розвивати навичку до 75 рівня. Потребує каміння й металу, які можна знайти за допомогою гірництва.", en="Blacksmithing" },
    [2023] = { "Відновлення мани", "Відновлює [{1}#Restores {1} mana.][від {1} до {2}#Restores {1} to {2} mana.] мани.", en="Restore Mana" },
    [2024] = { "Зілля лікування", "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", en="Healing Potion" },
    [2050] = { "Мале зцілення", "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", en="Lesser Heal" },
