    [2060] = { "Велике зцілення", "Повільне закляття, що зцілює одній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Greater Heal" },
    [2061] = { "Швидке зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#target for {1} to {2}", en="Flash Heal" },
    [2070] = { "Оглушення", "Робить ціль недієздатною на {1} с. Необхідно перебувати в непомітності. Діє лише проти гуманоїдів, що перебувають поза боєм. Будь-яка шкода знімає ефект з ураженої цілі. Одночасно лише 1 ціль може бути оглушеною.#up to {1} sec", "Недієздатність.", en="Sap" },
    [2090] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [2091] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [2094] = { "Засліплення", "Засліплює ціль, змушуючи її блукати протягом {1} с. Будь-яка шкода перериває дію ефекту.#for up to {1} sec", "Дезорієнтовано.", en="Blind" },
    [2096] = { "Видіння розуму", "Дозволяє заклиначу бачити очима цілі протягом {1} хв.#for {1} min", "Здатність бачити очима цілі.", en="Mind Vision" },
    [2098] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [2108] = { "Шкірництво", "Дозволяє виготовляти шкіряні обладунки та розвивати навичку до 75 рівня. Потребує обрізків шкіри та шкур, які можна зібрати за допомогою навички шкуродерства.", en="Leatherworking" },
    [2120] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [2121] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [2136] = { "Вогняний підрив", "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", en="Fire Blast" },
    [2137] = { "Вогняний підрив", "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", en="Fire Blast" },
    [2138] = { "Вогняний підрив", "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", en="Fire Blast" },
    [2139] = { "Протизакляття", "Протидіє вимові закляття ворогом, унеможливлюючи вимову будь-яких інших заклять тієї ж школи магії протягом {1} с. Спричиняє високий рівень загрози.#cast for {1} sec", en="Counterspell" },
    [2147] = { "Загоєння", "Періодичне зцілення", "Зцілює {1} здоров'я кожні {2} с.#for {1} every {2} sec", en="Mending" },
    [2148] = { "Періодичне застосування Тіньового шторму", "Періодично застосовує Тіньовий шторм.", "Періодично застосовує Тіньовий шторм.", en="Periodic Shadow Storm" },
    [2259] = { "Алхімія", "Дозволяє варити прості зілля та розвивати навичку до 75 рівня. Потребує трав, які можна знайти за допомогою травництва.", en="Alchemy" },
    [2362] = { "Створення каменя чарів", "Створює камінь чарів для заклинача. При спорядженні та використанні цей камінь чарів усуває всі магічні ефекти із заклинача та поглинає {1} магічної шкоди протягом {2} хв. Також при спорядженні цей камінь чарів збільшує ваш шанс завдання критичного удару закляттями на {3}%.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {4} хв.#absorb {1}#for {2} min#spells by {3}#than {4} min", en="Create Spellstone" },
    [2367] = { "Мале підвищення сили", "Збільшує силу на {1} протягом {2} год.#by {1} for {2} h", "Силу збільшено на {1}.#by {1}", en="Lesser Strength" },
    [2370] = { "Зілля омолодження", "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", en="Rejuvenation Potion" },
    [2374] = { "Мале підвищення спритності", "Збільшує спритність на {1} протягом {2} год.#by {1} for {2} h", "Спритність збільшено на {1}.#by {1}", en="Lesser Agility" },
    [2376] = { "Мале збільшення інтелекту", "Збільшує інтелект на {1} протягом {2} год.#by {1} for {2} h", "Інтелект збільшено на {1}.#by {1}", en="Lesser Intellect" },
    [2378] = { "Здоров'я", "Збільшує запас здоров'я на {1} протягом {2} год.#by {1} for {2} h", "Запас здоров'я збільшено на {1}.#by {1}", en="Health" },
    [2379] = { "Швидкість", "Збільшує швидкість бігу на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість бігу збільшено на {1}%.#by {1}%", en="Speed" },
    [2380] = { "Опір", "Збільшує ваш опір всім школам магії на {1} протягом {2} хв.#by {1} for {2} min", "Опір магії збільшено.", en="Resistance" },
    [2383] = { "Пошук трав", "На мінікарті з'являються мітки кущів з травами неподалік. Одночасно можна відстежувати лише щось одне.", "Шукає трави.", en="Find Herbs" },
    [2457] = { "Бойова стійка", "Збалансована бойова стійка.", en="Battle Stance" },
    [2458] = { "Стійка берсерка", "Агресивна стійка. Збільшує ймовірність завдання критичного удару на {1}%, а всю отриману шкоду на {2}%.#chance is increased by {1}#taken is increased by {2}", en="Berserker Stance" },
    [2479] = { "Безчесна ціль", nil, "Наразі ви не приносите жодних очок честі ворогам.", en="Honorless Target" },
    [2480] = { "Постріл з лука", en="Shoot Bow" },
    [2481] = { "Пошук скарбів", "Дозволяє дворфу відчувати скарби неподалік, відмічаючи їх на мінімапі. Триває до відміни.", "Пошук скарбів.", en="Find Treasure" },
    [2484] = { "Тотем земного зв'язування", "Викликає тотем земного зв'язування з {1} здоров'я на {2} с. Тотем сповільнює рух ворогів в межах {3} м.#with {1} health#for {2} sec#within {3} y", en="Earthbind Totem" },
    [2537] = { "Удар лицаря", "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", "Збільшує отриману шкоду святістю на {1}.#up to {1}", en="Crusader Strike" },
    [2550] = { "Кулінарія", "Дозволяє готувати базові страви та розвивати навичку до 75 рівня. Потребує джерела вогню та м'яса тварин.", en="Cooking" },
    [2565] = { "Блок щитом", "Збільшує ймовірність блокування щитом на {1}% протягом {2} с, але блокує лише [{1} атаку#block {1} attack.][{1} атаки#block {1} attacks.].#block by {1}% for {2} sec", "Ймовірність блокування збільшено на {1}% для наступної атаки.#increased by {1}%", en="Shield Block" },
    [2567] = { "Метальна зброя", en="Thrown" },
    [2575] = { "Гірництво", "Основи добування руди та каміння з мінеральних жил для використання в інженерії та ковальстві. Дозволяє розвивати навичку гірництва до 75 рівня. Для збору мінеральних жил необхідне кайло.", en="Mining" },
    [2576] = { "Гірництво", "Більш високий рівень гірництва. Дозволяє розвивати навичку гірництва до 150 рівня.", en="Mining" },
    [2580] = { "Пошук мінералів", "На мінікарті з'являються мітки покладів мінералів неподалік. Одночасно можна відстежувати лише щось одне.", "Шукає мінерали.", en="Find Minerals" },
    [2584] = { "В очікуванні воскресіння", en="Waiting to Resurrect" },
    [2589] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [2590] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [2591] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [2597] = { "Зілля омолодження", "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", en="Rejuvenation Potion" },
    [2599] = { "Зілля омолодження", "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", en="Rejuvenation Potion" },
    [2600] = { "Зілля омолодження", "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та [{1}#and {1} health][від {1} до {2}#and {1} to {2} health] здоров'я.", en="Rejuvenation Potion" },
    [2637] = { "Сплячка", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно лише одна ціль може бути змушена впасти в сплячку. Діє лише на звірів і драконів.#up to {1} sec", "Спить.", en="Hibernate" },
    [2639] = { "Їжа", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health and {2} mana over {3} sec", "Відновлює {1} здоров'я та {2} мани щосекунди.#Restores {1} health and {2} mana", en="Food" },
    [2641] = { "Відклик вихованця", "Відкликає вашого вихованця та зменшує його щастя на {1}.#by {1}", en="Dismiss Pet" },
    [2643] = { "Багатозарядний постріл", "Вистрілює декілька набоїв, вражаючи {1} цілі.#{1} targets", en="Multi-Shot" },
    [2645] = { "Примарний вовк", "Перетворює шамана на примарного вовка, збільшуючи швидкість руху на {1}%. Можна використовувати лише просто неба.#speed by {1}%", "Збільшує швидкість руху на {1}%.#by {1}%", en="Ghost Wolf" },
    [2649] = { "Рик", "Провокує ціль, збільшуючи ймовірність того, що вона зосередить свої атаки на вас.", en="Growl" },
    [2651] = { "Милість Елуни", "Зменшує отриману шкоду від атак дального бою на {1} і збільшує ймовірність ухилення на {2}% протягом {3} с.#taken by {1}#dodge by {2}% for {3} sec", "Отриману шкоду від атак дального бою зменшено на {1}, а ймовірність ухилення збільшено на {2}%.#reduced by {1}#increased by {2}", en="Elune's Grace" },
    [2652] = { "Дотик слабкості", "Наступна атака ближнього бою проти заклинача завдасть {1} шкоди тінню та зменшить шкоду нападника на {2} протягом {3} хв.#cause {1}#by {2} for {3} min", "Наступна ворожа атака ближнього бою завдасть шкоди нападнику та послабить його.", en="Touch of Weakness" },
    [2656] = { "Переплавлення", "Дозволяє гірникові переплавляти руду на злитки металу. Для виплавки необхідно бути біля кузні.", en="Smelting" },
    [2687] = { "Кривава лють", "Надає {1} люті ціною здоров'я та ще додатково {2} люті протягом {3} с. Поки діє ефект, вважається, що воїн перебуває в бою.#Generates {1} rage#additional {2} rage over {3} sec", en="Bloodrage" },
    [2764] = { "Кинути", "Кинути метальну зброю в ціль.", en="Throw" },
    [2767] = { "Слово тіні: Біль", "Слово темряви, що завдає {1} шкоди тінню протягом {2} с.#causes {1} Shadow damage over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Shadow Word: Pain" },
    [2782] = { "Зняття прокляття", "Знімає {1} прокляття з дружньої цілі.#Dispels {1} Curse", en="Remove Curse" },
    [2791] = { "Слово сили: Стійкість", "Сила наповнює ціль, збільшуючи її витривалість на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує витривалість на {1}.#by {1}", en="Power Word: Fortitude" },
    [2800] = { "Покладання рук", "Зцілює дружню ціль на значення, що дорівнює максимальному запасу здоров'я паладина, та відновлює їй {1} мани. Витрачає весь залишок мани паладина при використанні.#restores {1} of their", en="Lay on Hands" },
    [2812] = { "Священний гнів", "Посилає стріли священної сили в усіх напрямках, завдаючи від {1} до {2} шкоди святістю усім невмерлим та демонам в межах {3} м.#causing {1} to {2}#within {3} y", en="Holy Wrath" },
    [2818] = { "Смертельна отрута", nil, "Отримує {1} шкоди від природи кожні {2} с.#takes {1} Nature#every {2} sec", en="Deadly Poison" },
    [2819] = { "Смертельна отрута II", ref=2818, en="Deadly Poison II" },
    [2823] = { "Смертельна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, завдаючи {3} шкоди від природи протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#for {3} Nature damage over {4} sec#up to {5} times#{6} charges", en="Deadly Poison" },
    [2824] = { "Смертельна отрута II", ref=2823, en="Deadly Poison II" },
    [2828] = { "Заточка леза", "Збільшує шкоду гострої зброї на {1} протягом {2} хвилин.#by {1} for {2} min", en="Sharpen Blade" },
    [2829] = { "Заточка леза II", ref=2828, en="Sharpen Blade II" },
    [2830] = { "Заточка леза III", ref=2828, en="Sharpen Blade III" },
    [2834] = { "Періодичне застосування Громового удару", "Періодично застосовує Громовий удар.", "Періодично застосовує Громовий удар.", en="Periodic Thunderclap" },
    [2835] = { "Смертельна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, завдаючи {3} шкоди від природи протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#for {3} Nature damage over {4} sec#up to {5} times#{6} charges", en="Deadly Poison" },
    [2836] = { "Виявлення пасток", "Значно підсилює здатність виявляти пастки.", "Виявлення пасток.", en="Detect Traps" },
    [2837] = { "Смертельна отрута II", ref=2835, en="Deadly Poison II" },
    [2842] = { "Отрути", "Ви можете створювати та змішувати отрути як зі знайдених, так і з придбаних інгредієнтів.", en="Poisons" },
    [2860] = { "Ланцюгова блискавка", "Кидає в ціль блискавку, що завдає від {1} до {2} шкоди від природи та перестрибує на інших ворогів неподалік. Кожен стрибок завдає на {3}% менше шкоди. Вражає до {4} цілей.#dealing {1} to {2}#damage by {3}#{4} total targets.", en="Chain Lightning" },
    [2870] = { "Лікування хвороби", "Виліковує {1} хворобу з цілі.#Cures {1}", en="Cure Disease" },
    [2878] = { "Вигнати невмерлого", "Обраний невмерлий ворог буде змушений втікати протягом {1} с. Подальше завдання шкоди може перервати ефект. Одночасно лише одна ціль може бути вигнаною.#for up to {1} sec", "Змушений утікати.", en="Turn Undead" },
    [2893] = { "Усунення отрути", "Намагається вилікувати {1} ефект отруєння на цілі та ще {2} ефект отруєння кожні {3} с протягом {4} с.#cure {1} poison#and {2} more#every {3} seconds for {4} sec", "Намагається вилікувати {1} отруєння кожні {2} с.#cure {1} poison every {2} sec", en="Abolish Poison" },
    [2908] = { "Вгамування звіра", "Вгамовує обраного звіра, зменшуючи відстань, на якій він буде атакувати вас, на {1} м. Діє лише на звірів {2} рівня або нижче. Триває {3} с.#by {1} y#level {2} or lower#Lasts {3} sec", "Зменшено відстань, на якій ціль буде атакувати.", en="Soothe Animal" },
    [2912] = { "Зоряний вогонь", "Завдає цілі від {1} до {2} шкоди від аркани.#Causes {1} to {2} Arcane", en="Starfire" },
    [2941] = { "Жертовний вогонь", "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Immolate" },
    [2943] = { "Дотик слабкості", nil, "Фізичну шкоду зменшено на {1}.#by {1}", en="Touch of Weakness" },
    [2944] = { "Ненажерна чума", "Вражає ціль хворобою, що завдає {1} шкоди тінню протягом {2} с. Шкода від \"Ненажерної чуми\" зцілює заклинача.#causes {1}#over {2} sec", "Завдає {1} шкоди кожні {2} с та зцілює заклинача.#{1} damage every {2} sec", en="Devouring Plague" },
    [2947] = { "Вогняний щит", "Оточує ціль щитом з вогню. Кожен удар по цілі завдає {1} шкоди вогнем нападнику. Триває {2} хв. Заклинач не може накласти \"Вогняний щит\" на себе.#causes {1} Fire#Lasts {2} min", "Завдає {1} шкоди вогнем нападникові при отриманні удару.#Does {1}", en="Fire Shield" },
    [2948] = { "Опік", "Обпікає ворога, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Scorch" },
    [2970] = { "Виявлення невидимості", "Дозволяє дружній цілі виявляти невидимість протягом {1} хв.#for {1} min", "Виявлення невидимості.", en="Detect Invisibility" },
    [2973] = { "Удар раптора", "Потужна атака зі збільшенням шкоди ближнього бою на {1}.#by {1}", en="Raptor Strike" },
    [2974] = { "Підрізати крила", "Завдає {1} шкоди та сповільнює рух ворога на {2}% протягом {3} с.#Inflicts {1}#by {2}% for {3} sec", "Швидкість руху зменшено на {1}%.#by {1}", en="Wing Clip" },
    [2983] = { "Спринт", "Збільшує швидкість руху на {1}% протягом {2} с. Не порушує непомітності.#speed by {1}% for {2} sec", "Швидкість руху збільшено на {1}%.#by {1}%", en="Sprint" },
    [3009] = { "Дряпання", "Дряпає ворога, завдаючи від {1} до {2} шкоди.#causing {1} to {2}", en="Claw" },
    [3010] = { "Дряпання", "Дряпає ворога, завдаючи від {1} до {2} шкоди.#causing {1} to {2}", en="Claw" },
    [3029] = { "Дряпання", "Дряпає ворога, завдаючи {1} додаткової шкоди. Збільшує довжину комбінації на {2} прийом.#causing {1}#{2} combo", en="Claw" },
    [3034] = { "Жало гадюки", "Жалить ціль, випалюючи {1} мани протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} mana over {2} sec", "Випалює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Viper Sting" },
    [3043] = { "Жало скорпіда", "Жалить ціль, зменшуючи силу та спритність на {1} протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#by {1} for {2} sec", "Силу та спритність зменшено на {1}.#by {1}", en="Scorpid Sting" },
    [3044] = { "Арканічний постріл", "Миттєвий постріл, що завдає {1} шкоди арканою.#causes {1} Arcane", en="Arcane Shot" },
    [3045] = { "Швидка стрілянина", "Збільшує швидкість атаки дальнього бою на {1}%[, а швидкість атаки ближнього бою на {1}%#melee attack speed by {1}%] протягом {2} с.#ranged attack speed by {1}%#for {2} sec", "Збільшує швидкість атаки дальнього бою на {1}%[, а швидкість ближнього бою - на {1}%#melee attack speed by {1}%].#ranged attack speed by {1}%", en="Rapid Fire" },
    [3100] = { "Ковальство", "Дозволяє виготовляти якісну зброю і обладунки та розвивати навичку до 150 рівня.", en="Blacksmithing" },
