    [3976] = { "Точний приціл", ref=3974, en="Accurate Scope" },
    [4036] = { "Інженерія", "Дозволяє створювати базові пристрої та розвивати навичку до 75 рівня. Потребує каміння й металу, які можна знайти за допомогою гірництва.", en="Engineering" },
    [4037] = { "Інженерія", "Дозволяє створювати потужніші пристрої і вибухівку та розвивати навичку до 150 рівня.", en="Engineering" },
    [4038] = { "Інженерія", "Дозволяє створювати дивовижні пристрої і вибухівку та розвивати навичку до 225 рівня.", en="Engineering" },
    [4042] = { "Зілля лікування", "Відновлює [{1}#Restores {1} health.][від {1} до {2}#Restores {1} to {2} health.] здоров'я.", en="Healing Potion" },
