    [5100] = { "Вибух спор", "Use: Завдає [{1}#Inflicts {1} Nature][від {1} до {2}#Inflicts {1} to {2} Nature] шкоди від природи в радіусі {1} м.#in a {1} yard radius", en="Spore Burst" },
    [5106] = { "Кришталевий спалах", "Приголомшує ворогів у конусі перед заклиначем, позбавляючи їх можливості рухатися та атакувати на {1} с.#for {1} sec", "Приголомшено.", en="Crystal Flash" },
    [5116] = { "Запаморочливий постріл", "Паморочить ціль, сповільнюючи рух на {1}% протягом {2} с.#by {1}% for {2} sec", "Рух сповільнено на {1}%.#by {1}", en="Concussive Shot" },
    [5118] = { "Аспект гепарда", "Мисливець переймає аспекти гепарда, збільшуючи швидкість руху на {1}%. Отримана шкода викличе запаморочення на {2} с. Одночасно може бути активним лише один аспект.#speed by {1}%#for {2} sec", "Швидкість руху збільшено на {1}%. Запаморочення при отриманні удару.#{1}% increased", en="Aspect of the Cheetah" },
    [5134] = { "Світлова бомба", "Змушує всіх звірів у радіусі {1} м втікати протягом {2} с.#in a {1} yard#for {2} sec", "Налякано.", en="Flash Bomb" },
    [5137] = { "Поклик могили", "Завдає ворогові {1} шкоди від тіні через {2} с.#Inflicts {1} Shadow#after {2} sec", "{1} шкоди від тіні через {2} с.#{1} Shadow#after {2} sec", en="Call of the Grave" },
    [5138] = { "Висмоктування мани", "Передає {1} мани щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1}#Lasts {2} sec", "Висмоктує {1} мани щосекунди, передаючи її заклиначеві.#Drains {1} mana", en="Drain Mana" },
    [5143] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [5144] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [5145] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [5149] = { "Дресирування звіра", "Дозволяє мисливцю дресирувати свого вихованця різноманітним здібностям.", en="Beast Training" },
    [5159] = { "Розплавлена руда", "Завдає {1} шкоди вогнем навколишнім ворогам та сповільнює їх рух на {2}% протягом {3} с.#Inflicts {1} Fire#speed by {2}% for {3} sec", "{1} шкоди вогнем протягом {2} с.\nШвидкість руху зменшено на {3}%.#{1} Fire#over {2} sec#by {3}%", en="Melt Ore" },
    [5164] = { "Збиття з ніг", "Збиває ворога з ніг, приголомшуючи його на {1} с.#for {1} sec", "Приголомшено.", en="Knockdown" },
    [5171] = { "М'ясорубка", "Завершальний рух, що збільшує швидкість атаки ближнього бою на {1}%. Тривалість залежить від довжини комбінації:\n  1 прийом: {2} с\n  2 прийоми: {3} с\n  3 прийоми: {4} с\n  4 прийоми: {5} с\n  5 прийомів: {6} с#speed by {1}%#1 point  : {2} sec#2 points: {3} sec#3 points: {4} sec#4 points: {5} sec#5 points: {6} sec", "Швидкість атаки ближнього бою збільшено на {1}%.#by {1}%", en="Slice and Dice" },
    [5176] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [5177] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [5178] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [5179] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [5180] = { "Гнів", "Завдає цілі від {1} до {2} шкоди від природи.#Causes {1} to {2}", en="Wrath" },
    [5185] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [5186] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [5187] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [5188] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [5189] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [5195] = { "Опутуюче коріння", "Приковує ціль на місці та завдає {1} шкоди від природи протягом {2} с. Подальша завдана шкода може перервати дію ефекту. Можна використовувати лише просто неба.#causes {1}#over {2} sec", "Приковано. Завдає {1} шкоди від природи кожні {2} с.#Causes {1}#every {2} sec", en="Entangling Roots" },
    [5196] = { "Опутуюче коріння", "Приковує ціль на місці та завдає {1} шкоди від природи протягом {2} с. Подальша завдана шкода може перервати дію ефекту. Можна використовувати лише просто неба.#causes {1}#over {2} sec", "Приковано. Завдає {1} шкоди від природи кожні {2} с.#Causes {1}#every {2} sec", en="Entangling Roots" },
    [5201] = { "Дряпання", "Дряпає ворога, завдаючи {1} додаткової шкоди. Збільшує довжину комбінації на {2} прийом.#causing {1}#{2} combo", en="Claw" },
    [5208] = { "Отруєний гарпун", "Завдає ворогу звичайної шкоди плюс {1} та ще {2} шкоди від природи кожні {3} с протягом {4} хв.#plus {1} to#additional {2} Nature#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poisoned Harpoon" },
    [5209] = { "Войовничий рев", "Примушує всіх ворогів поблизу зосередити свої атаки на вас протягом {1} с.#for {1} sec", "Спровоковано.", en="Challenging Roar" },
    [5211] = { "Стусан", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Bash" },
    [5215] = { "Зачаїтися", "Дозволяє друїду пересуватися непомітно, але зменшує швидкість руху на {1}%. Триває до скасування.#speed by {1}%", "Непомітність. Рух сповільнено на {1}%.#slowed by {1}%", en="Prowl" },
    [5217] = { "Лють тигра", "Збільшує шкоду на {1} протягом {2} с.#by {1} for {2} sec", "Збільшує шкоду на {1}.#by {1}", en="Tiger's Fury" },
    [5221] = { "Шматування", "Шматує ціль, завдаючи {1}% шкоди плюс {2}. Необхідно бути позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Shred" },
    [5225] = { "Вистежування гуманоїдів", "Відображає на мінімапі місцезнаходження гуманоїдів неподалік. Одночасно можна вистежувати лише щось одне.", "Вистежування гуманоїдів.", en="Track Humanoids" },
    [5227] = { "Підводне дихання", "Ви можете затримувати дихання під водою на {1}% довше.#lasts {1}% longer", en="Underwater Breathing" },
    [5229] = { "Несамовитість", "Надає {1} люті протягом {2} сек, але знижує базову броню на {3}% у ведмежій подобі та на {4}% у подобі жахливого ведмедя. Поки діє ефект, вважається, що друїд перебуває в бою.#{1} rage over {2} sec#by {3}% in Bear Form and {4}% in Dire Bear Form", "Отримує {1} люті щосекунди.[ Базову броню зменшено.#Base armor reduced]#Gain {1} rage per sec", en="Enrage" },
    [5232] = { "Знак дикої природи", "Збільшує броню дружньої цілі на {1} та всі характеристики на {2} протягом {3} хв.#armor by {1} and all attributes by {2} for {3} min", "Збільшує броню на {1} та всі характеристики на {2}.#armor by {1}#attributes by {2}", en="Mark of the Wild" },
    [5234] = { "Знак дикої природи", "Збільшує броню дружньої цілі на {1}, всі характеристики на {2} та всі види опору на {3} протягом {4} хв.#armor by {1}#attributes by {2}#resistances by {3} for {4} min", "Збільшує броню на {1}, всі характеристики на {2} та всі види опору на {3}.#armor by {1}#attributes by {2}#resistances by {3}", en="Mark of the Wild" },
    [5242] = { "Бойовий клич", "Воїн кричить, збільшуючи силу атаки ближнього бою всіх учасників групи в межах {1} м на {2}. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Збільшує силу атаки ближнього бою на {1}.#power by {1}", en="Battle Shout" },
    [5246] = { "Жахаючий клич", "Воїн кричить, змушуючи свою ціль тремтіти від страху. До {1} ворогів поблизу втікати від страху. Триває {2} с.#to {1} total#Lasts {2} sec", "Нажахано.", en="Intimidating Shout" },
    [5257] = { "Громузвар", "Збільшує витривалість на {1}.#Stamina by {1}", en="Thunderbrew" },
    [5271] = { "Проклятий клинок", "Збільшує інтервал між атаками ворога на {1}% протягом {2} с.#by {1}% for {2} sec", "Інтервал між атаками збільшено на {1}%.#by {1}%", en="Cursed Blade" },
    [5277] = { "Уникнення", "Збільшує ймовірність ухилення на {1}% протягом {2} с.#by {1}% for {2} sec", "Збільшує ймовірність ухилення на {1}%.#by {1}%", en="Evasion" },
    [5308] = { "Страта", "Спроба добити пораненого ворога, завдаючи {1} шкоди і додатково {2} шкоди за кожну надлишкову одиницю люті. Можна використати лише проти ворогів, що мають не більше {3}% здоров'я.#causing {1} damage#into {2} additional#have {3}% or less", en="Execute" },
    [5320] = { "Грація Ічіякі", en="Echeyakee's Grace" },
    [5321] = { "Лють Ішамугала", "Збільшує витривалість цілі на {1} протягом {2} хв.#target by {1} for {2} min", en="Ishamuhale's Rage" },
    [5337] = { "Удар зав'ядання", ref=5271, en="Wither Strike" },
    [5384] = { "Удавання мертвого", "Прикинутися мертвим, що може ввести в оману ворогів та змусити їх вас ігнорувати. Триває до {1} хв.#Lasts up to {1} min", "Удає мертвого.", en="Feign Death" },
    [5394] = { "Тотем цілющого потоку", "Викликає тотем цілющого потоку з {1} здоров'я на {2} хв. Тотем зцілює учасникам групи в межах {3} м {4} здоров'я кожні {5} с.#with {1} health#for {2} min#within {3} yards for {4} every {5} sec", en="Healing Stream Totem" },
    [5405] = { "Поповнення мани", ref=436, en="Replenish Mana" },
    [5406] = { "Поповнення мани II", ref=436, en="Replenish Mana II" },
    [5413] = { "Їдкий каталізатор", "Зменшує опір природі ворога на {1} протягом {2} хв.#by {1} for {2} min", "Опір природі зменшено на {1}.#reduced by {1}", en="Noxious Catalyst" },
    [5416] = { "Отруйне жало", "Завдає ворогу {1} шкоди від природи та додатково {2} шкоди кожні {3} с протягом {4} с.#Inflicts {1} Nature#additional {2} damage every {3} sec#for {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Venom Sting" },
    [5484] = { "Виття жаху", "Виття, що змушує {1} ворогів в межах {2} м втікати від жаху протягом {3} с. Шкода може перервати цей ефект.#causing {1} enemies#within {2} y#for {3} sec", "Втікає від жаху.", en="Howl of Terror" },
    [5487] = { "Ведмежа подоба", "Набути ведмежої подоби, збільшуючи силу атаки ближнього бою на {1}, броню від предметів на {2}% та здоров'я на {3}. Також захищає заклинача від ефектів поліморфії та дозволяє використання ведмежих здібностей.\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#power by {1}#items by {2}%#health by {3}", "Невразливість до ефектів поліморфії. Збільшує силу атаки ближнього бою на {1}, броню від предметів на {2}% та здоров'я на {3}.#power by {1}#items by {2}%#health by {3}", en="Bear Form" },
    [5500] = { "Чуття демонів", "Відображає на мінімапі місцезнаходження демонів неподалік. Одночасно можна вистежувати лише щось одне.", "Відстеження демонів.", en="Sense Demons" },
    [5502] = { "Чуття невмерлих", "Відображає на мінімапі місцезнаходження невмерлих неподалік. Одночасно можна вистежувати лише щось одне.", "Відстеження невмерлих.", en="Sense Undead" },
    [5504] = { "Начаклування води", "Начаклувати пляшки води ({1} шт.), щоб забезпечити мага та союзників питвом.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} bottles#than {2} min", en="Conjure Water" },
    [5505] = { "Начаклування води", "Начаклувати пляшки води ({1} шт.), щоб забезпечити мага та союзників питвом.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} bottles#than {2} min", en="Conjure Water" },
    [5506] = { "Начаклування води", "Начаклувати пляшки води ({1} шт.), щоб забезпечити мага та союзників питвом.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} bottles#than {2} min", en="Conjure Water" },
    [5514] = { "Затьмарення зору", "Зменшує ймовірність завдання удару ціллю на {1}% протягом {2} с.#chance to hit by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Darken Vision" },
    [5567] = { "В'язка багнюка", ref=3542, en="Miring Mud" },
    [5568] = { "Тупіт", "Завдає навколишнім ворогам звичайної шкоди плюс {1}.#plus {1} to", en="Trample" },
    [5570] = { "Рій комах", "Ворожу ціль оточують комахи, зменшуючи її ймовірність поцілити на {1}% і завдаючи {2} шкоди від природи протягом {3} с.#hit by {1}#causing {2} Nature damage over {3} sec", "Зменшує ймовірність завдання удару на {1}% та завдає {2} шкоди від природи кожні {3} с.#by {1}% and {2}#every {3} sec", en="Insect Swarm" },
    [5573] = { "Божественний захист", "Ви захищені від усіх фізичних атак і заклять на {1} с, але протягом цього часу не можете атакувати чи використовувати фізичні здібності. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" протягом {2} хв.#spells for {1} sec#again for {2} min", "Невразливість до всіх атак і заклять. Не може атакувати чи використовувати фізичні здібності.", en="Divine Protection" },
    [5579] = { "Невразливість до знерухомлення/сповільнення/приголомшення", "Знімає всі ефекти знерухомлення, сповільнення та приголомшення.", en="Immune Root/Snare/Stun" },
    [5588] = { "Молот правосуддя", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Hammer of Justice" },
    [5589] = { "Молот правосуддя", "Приголомшує ціль на {1} с.#for {1} sec", "Приголомшено.", en="Hammer of Justice" },
    [5599] = { "Благословення захисту", "Захищає обраного учасника групи від усіх фізичних атак на {1} с, але протягом цього часу ціль не може атакувати чи використовувати фізичні здібності. Гравці можуть мати лише одне благословення від кожного паладина одночасно. Захищена ціль не зможе отримати невразливість від заклять \"Божественний щит\", \"Божественний захист\" та \"Благословення захисту\" повторно протягом {2} хв.#attacks for {1} sec#again for {2} min", "Невразливість до фізичних атак. Не може атакувати чи використовувати фізичні здібності.", en="Blessing of Protection" },
    [5614] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [5615] = { "Екзорцизм", "Завдає від {1} до {2} шкоди святістю невмерлому чи демону.#Causes {1} to {2} Holy", en="Exorcism" },
    [5627] = { "Вигнати невмерлого", "Обраний невмерлий ворог буде змушений втікати протягом {1} с. Подальше завдання шкоди може перервати ефект. Одночасно лише одна ціль може бути вигнаною.#for up to {1} sec", "Змушений утікати.", en="Turn Undead" },
    [5665] = { "Лють болотянчика", "Збільшує фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Збільшено шкоду ближнього бою.", en="Fury of the Bogling" },
    [5672] = { "Цілющий потік", nil, "Зцілює {1} здоров'я кожні {2} с.#Heals {1} every {2} sec", en="Healing Stream" },
    [5675] = { "Тотем джерела мани", "Викликає тотем джерела мани з {1} здоров'я на {2} хв. Тотем відновлює {3} мани кожні {4} с учасникам групи в межах {5} м.#with {1} health#for {2} min#{3} mana every {4} sec#within {5} y", en="Mana Spring Totem" },
    [5676] = { "Палючий біль", "Викликає у ворожої цілі палючий біль, завдаючи від {1} до {2} шкоди вогнем. Спричиняє високий рівень загрози.#causing {1} to {2}", en="Searing Pain" },
    [5677] = { "Джерело мани", nil, "Відновлює {1} мани кожні {2} с.#Gain {1} mana every {2} sec", en="Mana Spring" },
    [5697] = { "Нескінченне дихання", "Дозволяє цілі дихати під водою протягом {1} хв.#for {1} min", "Підводне дихання.", en="Unending Breath" },
    [5699] = { "Створення каменя здоров'я", "Створює камінь здоров'я, який можна використати для миттєвого відновлення {1} здоров'я.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#restore {1} health#than {2} min", en="Create Healthstone" },
    [5707] = { "Відновлення життєкаменя", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health every {2} sec", en="Lifestone Regeneration" },
    [5708] = { "Наліт", "Завдає звичайної шкоди плюс {1} ворогам в конусі перед заклиначем, приголомшуючи їх на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Swoop" },
    [5720] = { "Камінь здоров'я", "Миттєво відновлює {1} здоров'я.#restores {1} life", en="Healthstone" },
    [5723] = { "Великий камінь здоров'я", ref=5720, en="Greater Healthstone" },
    [5730] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [5740] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи {1} шкоди вогнем протягом {2} с.#{1} Fire damage over {2} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Rain of Fire" },
    [5760] = { "Задурлива отрута", nil, "Вимову заклять сповільнено на {1}%.#by {1}%", en="Mind-numbing Poison" },
    [5761] = { "Задурлива отрута", "Покриває зброю отрутою на {1} хв. Кожен удар з ймовірністю {2}% отруює ворога, сповільнюючи вимову заклять на {3}% протягом {4} с. {5} зарядів.#lasts for {1} min#a {2}% chance#by {3}% for {4} sec#{5} charges", en="Mind-numbing Poison" },
    [5763] = { "Задурлива отрута", "Покриває зброю отрутою на {1} хв. Кожен удар з ймовірністю {2}% отруює ворога, сповільнюючи вимову заклять на {3}% протягом {4} с. {5} зарядів.#lasts for {1} min#a {2}% chance#by {3}% for {4} sec#{5} charges", en="Mind-numbing Poison" },
    [5782] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати геть протягом {1} с. Шкода може перервати цей ефект. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Налякано.", en="Fear" },
    [5784] = { "Виклик скверножеребця", "Викликає скверножеребця для верхової їзди. Швидкість руху збільшується на {1}%.#by {1}%", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Felsteed" },
    [5857] = { "Ефект пекельного вогню", en="Hellfire Effect" },
    [5884] = { "Прокляття банші", ref=5514, en="Banshee Curse" },
    [5909] = { "Розбавлене пиво", "Це слабке пиво збільшує ваш дух на {1} та зменшує витривалість на {2} протягом {3} хв.#your Spirit by {1} and decreases your Stamina by {2} for {3} min", en="Watered-down Beer" },
    [5917] = { "Незграбність", "Зменшує ймовірність завдання удару ціллю на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання удару зменшено.", en="Fumble" },
    [5923] = { "Священна міць", "Збільшує ймовірність критичного ефекту ваших заклять святості на {1}%.#by {1}%", en="Holy Power" },
    [5952] = { "Спеціалізація на метальній зброї", "Збільшує шкоду від метальної зброї на {1}.#Throwing Weapons by {1}", en="Throwing Specialization" },
    [6016] = { "Пробиття броні", "Зменшує броню ворога на {1}% протягом {2} с.#by {1}% for {2} sec", "Броню зменшено на {1}%.#by {1}%", en="Pierce Armor" },
    [6041] = { "Блискавка", "Кидає в ціль блискавку, завдаючи від {1} до {2} шкоди від природи.#for {1} to {2}", en="Lightning Bolt" },
    [6057] = { "Спеціалізація на жезлах", "Збільшує шкоду жезлів на {1}%.#by {1}%", en="Wand Specialization" },
    [6060] = { "Кара", "Карає ворога, завдаючи від {1} до {2} шкоди святістю.#for {1} to {2}", en="Smite" },
    [6063] = { "Зцілення", "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", en="Heal" },
    [6064] = { "Зцілення", "Зцілює цілі від {1} до {2} здоров'я.#target for {1} to {2}", en="Heal" },
    [6065] = { "Слово сили: Щит", "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", "Поглинає шкоду.", en="Power Word: Shield" },
    [6066] = { "Слово сили: Щит", "Створює з частинки душі учасника групи щит, що поглинає {1} шкоди. Триває {2} с. Поки щит тримається, отримана шкода не спричинить затримки вимови заклять. Повторно накласти щит на ціль можна тільки через {3} с.#absorbing {1}#Lasts {2} sec#again for {3} sec", "Поглинає шкоду.", en="Power Word: Shield" },
    [6074] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [6075] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [6076] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [6077] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [6078] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [6114] = { "Рапторовий пунш", "Збільшує ваш інтелект на {1} але зменшує витривалість на {2} протягом {3} хв.#Intellect by {1} and#Stamina by {2} for {3} min", "Інтелект збільшено, а витривалість зменшено.", en="Raptor Punch" },
    [6117] = { "Магівський обладунок", "Збільшує ваш опір усій магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять. Одночасно може бути активним лише один обладунок. Триває {3} хв.#magic by {1} and allows {2}%#Lasts {3} min", "Збільшує опір усім школам магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять.#by {1} and allows {2}%", en="Mage Armor" },
    [6127] = { "Начаклування води", "Начаклувати пляшки води ({1} шт.), щоб забезпечити мага та союзників питвом.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} bottles#than {2} min", en="Conjure Water" },
    [6129] = { "Начаклування їжі", "Начаклувати кекси ({1} шт.), щоб забезпечити мага та союзників їжею.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {2} хв.#Conjures {1} muffins#than {2} min", en="Conjure Food" },
    [6131] = { "Крижаний спалах", "Вражає ворогів поруч із заклиначем, завдаючи [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди кригою, та приморожує їх на місці на {1} с. Подальше завдання шкоди може перервати дію цього ефекту.#up to {1} sec", "Приморожено.", en="Frost Nova" },
    [6136] = { "Охолодження", nil, "Рух сповільнено на {1}%, а інтервал між атаками збільшено на {2}%.#slowed by {1}%#increased by {2}%", en="Chilled" },
    [6141] = { "Метелиця", "Уламки льоду вкривають вибрану область, завдаючи {1} шкоди від криги протягом {2} с.#doing {1} Frost#over {2} sec", "{1} шкоди від криги щосекунди.#{1} Frost", en="Blizzard" },
    [6143] = { "Крижаний оберіг", "Поглинає {1} шкоди від криги. Триває {2} сек.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від криги.", en="Frost Ward" },
    [6150] = { "Швидкі постріли", nil, "Швидкість атаки дальнього бою збільшено на {1}%.#by {1}%", en="Quick Shots" },
    [6178] = { "Ривок", "Ривок у ворога, що збільшує лють на {1} і приголомшує його на {2} с. Не можна використовувати в бою.#generate {1} rage#for {2} sec", en="Charge" },
    [6190] = { "Деморалізуючий клич", "Зменшує силу атаки ближнього бою всіх ворогів в межах {1} м на {2} протягом {3} с.#within {1} yards by {2} for {3} sec", "Зменшує силу атаки ближнього бою на {1}.#power by {1}", en="Demoralizing Shout" },
    [6192] = { "Бойовий клич", "Воїн кричить, збільшуючи силу атаки ближнього бою всіх учасників групи в межах {1} м на {2}. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Збільшує силу атаки ближнього бою на {1}.#power by {1}", en="Battle Shout" },
    [6196] = { "Далекозорість", "Переносить поле зору заклинача до обраного місця. Триває {1} хв. Можна використовувати лише просто неба.#Lasts {1} min", "Не може рухатися під час використання \"Далекозорості\".", en="Far Sight" },
    [6197] = { "Орлине око", "Загострює зір мисливця. Можна використовувати лише просто неба. Триває {1} хв.#Lasts {1} min", en="Eagle Eye" },
    [6205] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [6213] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати геть протягом {1} с. Шкода може перервати цей ефект. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Налякано.", en="Fear" },
    [6215] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати геть протягом {1} с. Шкода може перервати цей ефект. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Налякано.", en="Fear" },
    [6219] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи {1} шкоди вогнем протягом {2} с.#{1} Fire damage over {2} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Rain of Fire" },
    [6222] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Corruption" },
    [6223] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Corruption" },
    [6226] = { "Висмоктування мани", "Передає {1} мани щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1}#Lasts {2} sec", "Висмоктує {1} мани щосекунди, передаючи її заклиначеві.#Drains {1} mana", en="Drain Mana" },
    [6229] = { "Тіньовий оберіг", "Поглинає {1} шкоди від тіні. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від тіні.", en="Shadow Ward" },
    [6253] = { "Різкий удар", "Різко б'є ворога, приголомшуючи його на {1} с.#for {1} sec", "Приголомшено.", en="Backhand" },
    [6262] = { "Крихітний камінь здоров'я", ref=5720, en="Minor Healthstone" },
    [6263] = { "Малий камінь здоров'я", ref=5720, en="Lesser Healthstone" },
    [6278] = { "Повзуча пліснява", "Завдає ворогу {1} шкоди від природи кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Creeping Mold" },
    [6296] = { "Чари: Вогняний спалах", "Зачарування зброї чарами, що з ймовірністю {1}% завдають [{1}#to inflict {1} Fire damage][від {1} до {2}#to inflict {1} to {2} Fire damage] шкоди вогнем всім ворогам в межах {2} м.#a {1}% chance#enemies within {2} y", en="Enchant: Fiery Blaze" },
    [6298] = { "Форма місяцескрада", "Перетворитися на місяцескрада та отримати невидимість на {1} хв.#for {1} min", "Невидимість.", en="Form of the Moonstalker" },
    [6304] = { "Удар Рак'Зора", "Завдає ворогу від {1} до {2} шкоди, приголомшуючи його на {3} с.#Inflicts {1} to {2} damage#for {3} sec", "Приголомшено.", en="Rhahk'Zor Slam" },
    [6306] = { "Кислотні бризки", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} с.#Inflicts {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Acid Splash" },
    [6307] = { "Кривава угода", "Збільшує витривалість учасників групи на {1}.#Stamina by {1}", "Збільшує витривалість на {1}.#by {1}", en="Blood Pact" },
    [6343] = { "Громовий удар", "Вражає ворогів неподалік, збільшуючи інтервал між їхніми атаками на {1}% протягом {2} с та завдаючи їм {3} шкоди. Подіє не більше ніж на {4} цілі.#attacks by {1}% for {2} sec and doing {3} damage#up to {4} targets", "Інтервал між атаками збільшено на {1}%.#increased by {1}%", en="Thunder Clap" },
    [6346] = { "Оберіг від страху", "Оберігає дружню ціль від страху. Наступний ефект страху проти цілі буде нейтралізовано за рахунок оберегу. Триває {1} хв.#Lasts {1} min", "Захищено від страху.", en="Fear Ward" },
    [6353] = { "Випалення душі", "Обпалює душу ворога, завдаючи від {1} до {2} шкоди вогнем.#causing {1} to {2}", en="Soul Fire" },
    [6358] = { "Зваблення", "Зваблює ціль, перешкоджаючи всім її діям протягом {1} с. Будь-яка шкода скасує ефект. Діє лише на гуманоїдів.#for up to {1} sec", "Причаровано.", en="Seduction" },
    [6360] = { "Заспокійливий поцілунок", "Заспокоює ціль, збільшуючи ймовірність того, що вона атакуватиме когось іншого.", en="Soothing Kiss" },
    [6363] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
    [6364] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
    [6365] = { "Тотем обпалення", "Викликає тотем обпалення з {1} здоров'я на {2} с. Тотем періодично атакує ворогів у радіусі {3} м, завдаючи від {4} до {5} шкоди вогнем.#with {1} health#for {2} sec#within {3} yards for {4} to {5} Fire", en="Searing Totem" },
    [6371] = { "Цілющий потік", nil, "Зцілює {1} здоров'я кожні {2} с.#Heals {1} every {2} sec", en="Healing Stream" },
    [6372] = { "Цілющий потік", nil, "Зцілює {1} здоров'я кожні {2} с.#Heals {1} every {2} sec", en="Healing Stream" },
    [6375] = { "Тотем цілющого потоку", "Викликає тотем цілющого потоку з {1} здоров'я на {2} хв. Тотем зцілює учасникам групи в межах {3} м {4} здоров'я кожні {5} с.#with {1} health#for {2} min#within {3} yards for {4} every {5} sec", en="Healing Stream Totem" },
    [6377] = { "Тотем цілющого потоку", "Викликає тотем цілющого потоку з {1} здоров'я на {2} хв. Тотем зцілює учасникам групи в межах {3} м {4} здоров'я кожні {5} с.#with {1} health#for {2} min#within {3} yards for {4} every {5} sec", en="Healing Stream Totem" },
    [6390] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [6391] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [6392] = { "Тотем кам'яного пазура", "Викликає тотем кам'яного пазура з {1} здоров'я на {2} с. Тотем провокує істот в межах {3} м атакувати його.#with {1} health#for {2} sec#within {3} y", en="Stoneclaw Totem" },
    [6405] = { "Форма хутропуза", "Перетворює вас на хутропуза на {1} хв.#for {1} min", "Перетворено на хутропуза.", en="Furbolg Form" },
    [6410] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [6435] = { "Потужний бац", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Smite Slam" },
    [6495] = { "Сторожовий тотем", "Викликає нерухомий сторожовий тотем зі {1} здоров'я на {2} хв. Тотем дозволяє спостерігати за територією навколо нього та попереджає про ворогів, що атакують його. Натисніть правою кнопкою миші на іконку ефекту, щоб перемикатися між зором шамана та зором тотема.#with {1} health#for {2} min", "Дозволяє бачити крізь сторожовий тотем. Натисніть правою кнопкою миші на іконку ефекту, щоб перемикатися між зором шамана та зором тотема.", en="Sentry Totem" },
    [6510] = { "Сліпучий порошок", "Створити реагент для здібності \"Засліплення\".", en="Blinding Powder" },
    [6512] = { "Виявлення малої невидимості", "Надає виявлення малої невидимості на {1} хв.#for {1} min", "Виявлення малої невидимості.", en="Detect Lesser Invisibility" },
    [6524] = { "Тремтіння землі", "Приголомшує навколишніх ворогів, позбавляючи їх можливості рухатися та атакувати на {1} с.#for {1} sec", "Приголомшено.", en="Ground Tremor" },
    [6530] = { "Кидок бруду", "Кидає бруд в очі ворога, знижуючи його шанс завдання удару на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Sling Dirt" },
    [6533] = { "Сітка", ref=3542, en="Net" },
    [6546] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [6547] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [6548] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [6552] = { "Луснути", "Лупить ціль, завдаючи {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Pummel" },
    [6554] = { "Луснути", "Лупить ціль, завдаючи {1} шкоди. Перериває вимову закляття та унеможливлює вимову заклять тієї ж школи протягом {2} с.#for {1} damage#for {2} sec", en="Pummel" },
    [6572] = { "Помста", "Миттєва контратака, що завдає від {1} до {2} шкоди та значно збільшує рівень загрози. Помста повинна слідувати за блокуванням, ухиленням або парируванням.#for {1} to {2} damage", en="Revenge" },
    [6574] = { "Помста", "Миттєва контратака, що завдає від {1} до {2} шкоди та значно збільшує рівень загрози. Помста повинна слідувати за блокуванням, ухиленням або парируванням.#for {1} to {2} damage", en="Revenge" },
