    [7272] = { "Хмара пилу", "Зменшує ймовірність завдання удару навколишніх ворогів на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Dust Cloud" },
    [7289] = { "Зменшення", "Зменшує силу ворога на {1}, а витривалість - на {2} протягом {3} хв.#Strength by {1}#Stamina by {2} for {3} min", "Силу зменшено на {1}.\nВитривалість зменшено на {2}.#Strength reduced by {1}#Stamina reduced by {2}", en="Shrink" },
    [7290] = { "Витягування душі", "Висмоктує {1} здоров'я з ворога та його найближчого союзника протягом {2} с, зцілюючи заклиначеві вдвічі більше здоров'я.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Soul Siphon" },
    [7294] = { "Аура розплати", "Завдає {1} шкоди святістю ворогам, що завдають удару учасникам групи в межах {2} м. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#Causes {1} Holy#within {2} y", "Завдає {1} шкоди святістю будь-кому, хто вас ударяє.#Does {1} Holy damage", en="Retribution Aura" },
    [7295] = { "Висмоктування душі", "Знерухомлює ворога на {1} с та висмоктує {2} здоров'я, передаючи його заклиначу.#for {1} sec#drains {2} health", "Знерухомлено", en="Soul Drain" },
    [7300] = { "Крижаний обладунок", "Збільшує броню на {1}. Якщо ворог завдає удару заклиначеві, його рух може сповільнитися на {2}%, а інтервал між атаками збільшитися на {3}% протягом {4} с. Одночасно може бути активним лише один обладунок. Триває {5} хв.#Armor by {1}#slowed by {2}%#increased by {3}% for {4} sec#Lasts {5} min", "Збільшує броню на {1} та може сповільнити нападників.#Armor by {1}", en="Frost Armor" },
    [7301] = { "Крижаний обладунок", "Збільшує броню на {1}. Якщо ворог завдає удару заклиначеві, його рух може сповільнитися на {2}%, а інтервал між атаками збільшитися на {3}% протягом {4} с. Одночасно може бути активним лише один обладунок. Триває {5} хв.#Armor by {1}#slowed by {2}%#increased by {3}% for {4} sec#Lasts {5} min", "Збільшує броню на {1} та може сповільнити нападників.#Armor by {1}", en="Frost Armor" },
    [7302] = { "Льодяний обладунок", "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}", en="Ice Armor" },
    [7320] = { "Льодяний обладунок", "Збільшує броню на {1} та опір кризі на {2}. Якщо ворог завдає удару по заклиначу, його швидкість руху може сповільнитися на {3}%, а інтервал між атаками збільшитися на {4}% протягом {5} с. Одночасно може бути активним лише один обладунок. Триває {6} хв.#Armor by {1}#resistance by {2}#slowed by {3}%#increased by {4}% for {5} sec#Lasts {6} min", "Збільшує броню на {1}, опір кризі на {2} і може сповільнити нападників.#Armor by {1}#resistance by {2}", en="Ice Armor" },
    [7321] = { "Охолодження", nil, "Рух сповільнено на {1}%, а інтервал між атаками збільшено на {2}%.#slowed by {1}%#increased by {2}%", en="Chilled" },
    [7322] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [7328] = { "Спокута", "Повертає мертвого гравця до життя з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Redemption" },
    [7353] = { "Затишне вогнище", "Збільшує ваш дух на {1}.#Spirit by {1}", "Збільшує дух на {1}.#by {1}", en="Cozy Fire" },
    [7357] = { "Отруйний удар", "Завдає ворогу {1} шкоди від природи кожні {2} с, збільшує інтервал між його атаками на {3}% і сповільнює його рух на на {4}% протягом {5} с.#Inflicts {1} Nature#every {2} sec#attacks by {3}%#movement by {4}% for {5} sec", "{1} шкоди від природи кожні {2} с.\nІнтервал між атаками збільшено на {3}%.\nШвидкість руху зменшено на {4}%.#{1} Nature#every {2} sec#attacks increased by {3}%#speed reduced by {4}%", en="Poisonous Stab" },
    [7358] = { "Затишне вогнище", "Збільшує ваш дух на {1}.#Spirit by {1}", "Збільшує дух на {1}.#by {1}", en="Cozy Fire" },
    [7363] = { "Відблиск полум'я", "Збільшує дух учасників групи неподалік на {1}.#by {1}", en="Fire's Glow" },
    [7365] = { "Пляшка отрути", "Кидає у ворога пляшку з отрутою, що завдає {1} шкоди від природи кожні {2} с протягом {3} с.#inflicting {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Bottle of Poison" },
    [7367] = { "Інфікований укус", "Завдає {1} шкоди від природи ворогу кожні {2} с та збільшує отриману ним фізичну шкоду на {3} протягом {4} хв.#Inflicts {1} Nature#every {2} sec#by {3} for {4} min", "Завдає {1} шкоди від природи кожні {2} с.\nОтриману фізичну шкоду збільшено на {3}.#{1} Nature#every {2} sec#increased by {3}", en="Infected Bite" },
    [7369] = { "Розсічення", "Розмашиста атака, що завдає шкоди зброєю плюс {1} по цілі та по найближчому до неї ворогу.#damage plus {1} to", en="Cleave" },
    [7371] = { "Ривок", "Ривок у ворога, що знерухомлює його на {1} с і додає {2} сили атаки ближнього бою до наступної атаки кнура.#for {1} sec#adds {2} melee", en="Charge" },
    [7372] = { "Нівечення", "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Hamstring" },
    [7373] = { "Нівечення", "Калічить ворога, завдаючи {1} шкоди та зменшуючи швидкість руху на {2}% протягом {3} с.#causing {1} damage#movement by {2}% for {3} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Hamstring" },
    [7379] = { "Помста", "Миттєва контратака, що завдає від {1} до {2} шкоди та значно збільшує рівень загрози. Помста повинна слідувати за блокуванням, ухиленням або парируванням.#for {1} to {2} damage", en="Revenge" },
    [7384] = { "Здолання", "Миттєво долає ворога, завдаючи шкоди зброєю плюс {1}. Можна використати лише після того, як ціль ухилилась. Здолання не можна блокувати, ухилитися від нього або парирувати.#damage plus {1}", en="Overpower" },
    [7386] = { "Розкол броні", "Розколює броню цілі, зменшуючи її на {1} за кожен ефект \"Розколу броні\", та спричиняє високий рівень загрози. Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено на {1}.#decreased by {1}", en="Sunder Armor" },
    [7394] = { "Закручений удар", "Завдає навколишнім ворогам звичайної шкоди плюс {1}.#plus {1} to", en="Spinning Slash" },
    [7396] = { "Риб'ячий жир", "Збільшує швидкість вашої атаки на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість атаки збільшено.", en="Fishliver Oil" },
    [7400] = { "Глумливий удар", "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", "Спровоковано.", en="Mocking Blow" },
    [7402] = { "Глумливий удар", "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", "Спровоковано.", en="Mocking Blow" },
    [7405] = { "Розкол броні", "Розколює броню цілі, зменшуючи її на {1} за кожен ефект \"Розколу броні\", та спричиняє високий рівень загрози. Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено на {1}.#decreased by {1}", en="Sunder Armor" },
    [7411] = { "Накладання чарів", "Дозволяє накладати чари на зброю і обладунки та розвивати навичку до 75 рівня. Потребує пилу та субстанцій, які можна добути з магічних предметів за допомогою руйнування чарів.", en="Enchanting" },
    [7412] = { "Накладання чарів", "Дозволяє накладати чари на зброю і обладунки та розвивати навичку до 150 рівня.", en="Enchanting" },
    [7413] = { "Накладання чарів", "Дозволяє накладати майстерні чари на зброю і обладунки та розвивати навичку до 225 рівня.", en="Enchanting" },
