    [8129] = { "Спалення мани", "Спалює цілі від {1} до {2} мани. Кожна одиниця спаленої таким чином мани завдає цілі {3} шкоди тінню.#{1} to {2} mana#takes {3} Shadow", en="Mana Burn" },
    [8131] = { "Спалення мани", "Спалює цілі від {1} до {2} мани. Кожна одиниця спаленої таким чином мани завдає цілі {3} шкоди тінню.#{1} to {2} mana#takes {3} Shadow", en="Mana Burn" },
    [8134] = { "Блискавковий щит", "Оточує заклинача {1} кульовими блискавками. Коли будь-яке закляття, атака ближнього чи дальнього бою влучає у заклинача, нападнику завдається {2} шкоди від природи. При цьому витрачається одна кульова блискавка. Кульові блискавки можуть активуватися лише раз на кілька секунд. Триває {3} хв.#by {1} balls#struck for {2} Nature#Lasts {3} min", "Завдає {1} шкоди від природи нападникам при отриманні удару.#Causes {1} Nature", en="Lightning Shield" },
