    [8191] = { "Ревність", "Виплеск енергії наповнює вас, збільшуючи шкоду на {1} і броню на {2} протягом {3} с.#damage by {1} and armor by {2} for {3} sec", "Шкоду та броню збільшено.", en="Zeal" },
    [8192] = { "Заспокоєння розуму", "Заспокоює ціль, зменшуючи відстань, на якій вона атакуватиме вас, на {1} м. Діє лише на гуманоїдів рівня {2} або нижче. Триває {3} с.#by {1} y#level {2} or lower#Lasts {3} sec", "Зменшено відстань, з якої ціль атакуватиме.", en="Mind Soothe" },
    [8198] = { "Громовий удар", "Вражає ворогів неподалік, збільшуючи інтервал між їхніми атаками на {1}% протягом {2} с та завдаючи їм {3} шкоди. Подіє не більше ніж на {4} цілі.#attacks by {1}% for {2} sec and doing {3} damage#up to {4} targets", "Інтервал між атаками збільшено на {1}%.#increased by {1}%", en="Thunder Clap" },
    [8202] = { "Зір сапти", "Дозволює шаману бачити духів стихій.", "Здатність бачити духів стихій.", en="Sapta Sight" },
    [8204] = { "Громовий удар", "Вражає ворогів неподалік, збільшуючи інтервал між їхніми атаками на {1}% протягом {2} с та завдаючи їм {3} шкоди. Подіє не більше ніж на {4} цілі.#attacks by {1}% for {2} sec and doing {3} damage#up to {4} targets", "Інтервал між атаками збільшено на {1}%.#increased by {1}%", en="Thunder Clap" },
    [8205] = { "Громовий удар", "Вражає ворогів неподалік, збільшуючи інтервал між їхніми атаками на {1}% протягом {2} с та завдаючи їм {3} шкоди. Подіє не більше ніж на {4} цілі.#attacks by {1}% for {2} sec and doing {3} damage#up to {4} targets", "Інтервал між атаками збільшено на {1}%.#increased by {1}%", en="Thunder Clap" },
    [8212] = { "Збільшення", "Ваш розмір збільшується, а ваша сила зростає на {1}, відповідно до вашого нового розміру. Триває {2} хв.#up by {1}#Lasts {2} min", "Силу збільшено на {1}, а також збільшено розмір.#by {1}", en="Enlarge" },
    [8215] = { "Швидка вимова", nil, "Швидкість вимови заклять збільшено.", en="Rapid Cast" },
    [8219] = { "Підміна", nil, "Видозмінено.", en="Flip Out" },
    [8220] = { "Підміна", nil, "Видозмінено.", en="Flip Out" },
    [8221] = { "Яааарррр", nil, "Видозмінено.", en="Yaaarrrr" },
    [8222] = { "Яааарррр", nil, "Видозмінено.", en="Yaaarrrr" },
    [8223] = { "Отакої!", nil, "Видозмінено.", en="Oops!" },
    [8224] = { "Боягузтво", nil, "Налякано.", en="Cowardice" },
    [8225] = { "Тікай!", nil, "Налякано.", en="Run Away!" },
    [8226] = { "Імітація смерті", nil, "Вдає мертвого.", en="Fake Death" },
    [8227] = { "Тотем язика полум'я", "Викликає тотем язика полум'я з {1} здоров'я. Тотем підсилює вогнем зброю в основній руці всіх учасників групи в межах {2} м. Кожен удар завдає від {3} до {4} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {5} хв.#with {1} health#within {2} y#causes {3} to {4}#Lasts {5} min", en="Flametongue Totem" },
    [8232] = { "Зброя буревію", "Підсилює зброю шамана вітром. Кожен удар з ймовірністю {1}% спричиняє {2} додаткові атаки зі збільшеною на {3} силою атаки ближнього бою. Триває {4} хв.#{1}% chance#{2} extra attacks with {3}#Lasts for {4} min", en="Windfury Weapon" },
    [8235] = { "Зброя буревію", "Підсилює зброю шамана вітром. Кожен удар з ймовірністю {1}% спричиняє {2} додаткові атаки зі збільшеною на {3} силою атаки ближнього бою. Триває {4} хв.#{1}% chance#{2} extra attacks with {3}#Lasts for {4} min", en="Windfury Weapon" },
    [8242] = { "Трощення щитом", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Shield Slam" },
    [8245] = { "Їдка кислота", "Зменшує броню навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Броню зменшено на {1}.#by {1}", en="Corrosive Acid" },
    [8249] = { "Тотем язика полум'я", "Викликає тотем язика полум'я з {1} здоров'я. Тотем підсилює вогнем зброю в основній руці всіх учасників групи в межах {2} м. Кожен удар завдає від {3} до {4} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {5} хв.#with {1} health#within {2} y#causes {3} to {4}#Lasts {5} min", en="Flametongue Totem" },
    [8256] = { "Летальний токсин", "Завдає ворогу {1} шкоди від природи кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Lethal Toxin" },
    [8257] = { "Отруйне жало", "Завдає ворогу {1} шкоди від природи та додатково {2} шкоди кожні {3} с протягом {4} с.#Inflicts {1} Nature#additional {2} damage every {3} sec#for {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Venom Sting" },
    [8258] = { "Аура відданості", "Надає {1} додаткової броні навколишнім учасникам групи протягом {2} хв. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#{1} additional armor#for {2} min", "Броню збільшено на {1}.#by {1}", en="Devotion Aura" },
    [8259] = { "Вихровий удар", "Завдає навколишнім ворогам звичайної шкоди плюс {1}.#plus {1} to", en="Whirling Barrage" },
    [8267] = { "Проклята кров", "Зменшує інтелект навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Інтелект зменшено на {1}.#by {1}", en="Cursed Blood" },
    [8269] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}% та збільшує фізичну шкоду на {2} протягом {3} хв.#speed by {1}%#deals by {2} for {3} min", "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
    [8272] = { "Тремор розуму", "Сповільнює вимову заклять ворогом на {1}% протягом {2} хв.#by {1}% for {2} min", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Mind Tremor" },
    [8275] = { "Отруєний постріл", "Завдає ворогу звичайної шкоди плюс {1} та ще {2} шкоди від природи кожні {3} с протягом {4} хв.#plus {1} to#additional {2} Nature#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poisoned Shot" },
    [8277] = { "Чаклунство вуду", "Зменшити фізичну шкоду цілі на {1} протягом {2} хв.#target is reduced by {1} for {2} min", "Фізичну шкоду зменшено.", en="Voodoo Hex" },
    [8281] = { "Звуковий сплеск", "Завдає навколишнім ворогам звичайної шкоди плюс {1} та знемовлює їх на {2} с.#plus {1} on#for {2} sec", "Не може вимовляти закляття.", en="Sonic Burst" },
    [8282] = { "Прокляття крові", "Збільшує отриману ворогом фізичну шкоду на {1} протягом {2} хв.#by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#by {1}", en="Curse of Blood" },
    [8288] = { "Висмоктування душі", "Висмоктує душу з цілі, завдаючи {1} шкоди тінню протягом {2} с. Якщо ціль під час цього помирає та приносить досвід або честь, заклинач отримує уламок душі. Уламки душі потрібні для інших заклять.#causing {1}#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2}", en="Drain Soul" },
    [8289] = { "Висмоктування душі", "Висмоктує душу з цілі, завдаючи {1} шкоди тінню протягом {2} с. Якщо ціль під час цього помирає та приносить досвід або честь, заклинач отримує уламок душі. Уламки душі потрібні для інших заклять.#causing {1}#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2}", en="Drain Soul" },
    [8312] = { "Пастка", "Знерухомлює ціль на {1} с.#unable to move for {1} sec", "Знерухомлено.", en="Trap" },
    [8313] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [8314] = { "Кам'яна шкіра", nil, "Збільшує броню та витривалість.", en="Rock Skin" },
    [8316] = { "Вогняний щит", "Оточує ціль щитом з вогню. Кожен удар по цілі завдає {1} шкоди вогнем нападнику. Триває {2} хв. Заклинач не може накласти \"Вогняний щит\" на себе.#causes {1} Fire#Lasts {2} min", "Завдає {1} шкоди вогнем нападникові при отриманні удару.#Does {1}", en="Fire Shield" },
    [8317] = { "Вогняний щит", "Оточує ціль щитом з вогню. Кожен удар по цілі завдає {1} шкоди вогнем нападнику. Триває {2} хв. Заклинач не може накласти \"Вогняний щит\" на себе.#causes {1} Fire#Lasts {2} min", "Завдає {1} шкоди вогнем нападникові при отриманні удару.#Does {1}", en="Fire Shield" },
    [8326] = { "Привид", nil, "Прямуйте до вашого тіла або поговоріть зі зцілювачем духу щоб повернутися до життя.", en="Ghost" },
    [8331] = { "Динаміт \"Простокид\"", "Динаміт для неінженерів, який майже завжди вражає ціль! Завдає [{1}#Inflicts {1} Fire damage][від {1} до {2}#Inflicts {1} to {2} Fire damage] шкоди вогнем в радіусі {1} м.#damage in a {1} y", en="Ez-Thro Dynamite" },
    [8333] = { "Шорсткий динаміт", ref=1940, en="Coarse Dynamite" },
    [8342] = { "Дефібриляція", "Кабельний дефібрилятор іноді може повернути до життя мертвого гравця. Не можна використовувати під час бою.", en="Defibrillate" },
    [8348] = { "Благословення Джулії", "Зцілює власнику {1} здоров'я протягом {2} с.#wielder of {1} damage over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#Heals {1} damage every {2} sec", en="Julie's Blessing" },
    [8363] = { "Паразит", "Завдає ворогу звичайної шкоди плюс {1} та ще {2} шкоди від природи кожні {3} с протягом {4} хв.#plus {1} to#additional {2} Nature#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", ref=5208, en="Parasite" },
    [8377] = { "Землехват", nil, "Знерухомлено.", en="Earthgrab" },
    [8379] = { "Роззброєння", "Роззброює ворога, змушуючи його припинити використовувати зброю протягом {1} с.#weapon for {1} sec", "Не тримає в руках зброю.", en="Disarm" },
    [8380] = { "Розкол броні", "Розколює броню цілі, зменшуючи її на {1} за кожен ефект \"Розколу броні\", та спричиняє високий рівень загрози. Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено на {1}.#decreased by {1}", en="Sunder Armor" },
    [8382] = { "П'явкова отрута", "Висмоктує {1} здоров'я з ворога кожні {2} с протягом {3} с, передаючи його заклиначу.#Drains {1} health#every {2} sec#over {3} sec", "Висмоктування {1} здоров'я кожні {2} с.#{1} health#every {2} sec", en="Leech Poison" },
    [8385] = { "Стрімкий вітер", nil, "Збільшує швидкість руху на {1}%.\nЗбільшує швидкість атаки на {2}%.#movement speed by {1}%#attack speed by {2}%", en="Swift Wind" },
    [8391] = { "Знищення", "Завдає ворогу звичайної шкоди плюс {1} та приголомшує його на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Ravage" },
    [8394] = { "Смугастий кригозуб", "Викликає та відпускає верхового смугастого кригозуба.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Striped Frostsaber" },
    [8395] = { "Смарагдовий раптор", "Викликає та відпускає верхового раптора.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Emerald Raptor" },
    [8398] = { "Залп крижаних стріл", "Завдає від {1} до {2} шкоди від криги навколишнім ворогам, зменшуючи їх швидкість руху на {3}% протягом {4} с.#Inflicts {1} to {2} Frost#speed by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt Volley" },
    [8399] = { "Сон", "Змушує ворогів неподалік спати протягом {1} с. Будь-яка шкода розбудить ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [8400] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [8401] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [8402] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [8406] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [8407] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [8408] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [8412] = { "Вогняний підрив", "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", en="Fire Blast" },
    [8413] = { "Вогняний підрив", "Підриває ворога, завдаючи від {1} до {2} шкоди вогнем.#{1} to {2}", en="Fire Blast" },
    [8416] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [8417] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [8422] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [8423] = { "Полум'яний удар", "Викликає вогняний стовп, що палить усіх ворогів у зоні ураження, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем і додатково {1} шкоди вогнем протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Flamestrike" },
    [8427] = { "Метелиця", "Уламки льоду вкривають вибрану область, завдаючи {1} шкоди від криги протягом {2} с.#doing {1} Frost#over {2} sec", "{1} шкоди від криги щосекунди.#{1} Frost", en="Blizzard" },
    [8437] = { "Арканічний вибух", "Створює вибух арканічної магії навколо заклинача, завдаючи від {1} до {2} шкоди арканою всім цілям у радіусі {3} м.#causing {1} to {2}#within {3} yards", en="Arcane Explosion" },
    [8438] = { "Арканічний вибух", "Створює вибух арканічної магії навколо заклинача, завдаючи від {1} до {2} шкоди арканою всім цілям у радіусі {3} м.#causing {1} to {2}#within {3} yards", en="Arcane Explosion" },
    [8439] = { "Арканічний вибух", "Створює вибух арканічної магії навколо заклинача, завдаючи від {1} до {2} шкоди арканою всім цілям у радіусі {3} м.#causing {1} to {2}#within {3} yards", en="Arcane Explosion" },
    [8444] = { "Опік", "Обпікає ворога, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Scorch" },
    [8445] = { "Опік", "Обпікає ворога, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Scorch" },
    [8446] = { "Опік", "Обпікає ворога, завдаючи [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем.", en="Scorch" },
    [8450] = { "Пом'якшення магії", "Послаблює магію на обраному учаснику групи, зменшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", "Зменшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}", en="Dampen Magic" },
    [8451] = { "Пом'якшення магії", "Послаблює магію на обраному учаснику групи, зменшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", "Зменшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}", en="Dampen Magic" },
    [8455] = { "Підсилення магії", "Підсилює магію на обраному учаснику групи, збільшуючи отриману ним шкоду від заклять на {1}, а зцілення закляттями на {2}. Триває {3} хв.#by up to {1} and healing spells by up to {2}#Lasts {3} min", "Збільшує отриману магічну шкоду на {1}, а зцілення на {2}.#by up to {1} and healing by up to {2}", en="Amplify Magic" },
    [8457] = { "Вогняний оберіг", "Поглинає {1} шкоди від вогню. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від вогню.", en="Fire Ward" },
    [8458] = { "Вогняний оберіг", "Поглинає {1} шкоди від вогню. Триває {2} с.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від вогню.", en="Fire Ward" },
    [8461] = { "Крижаний оберіг", "Поглинає {1} шкоди від криги. Триває {2} сек.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від криги.", en="Frost Ward" },
    [8462] = { "Крижаний оберіг", "Поглинає {1} шкоди від криги. Триває {2} сек.#Absorbs {1}#Lasts {2} sec", "Поглинає шкоду від криги.", en="Frost Ward" },
    [8492] = { "Конус холоду", "Завдає цілям у конусі перед заклиначем [{1}#take {1} Frost][від {1} до {2}#take {1} to {2} Frost] шкоди кригою та сповільнює їх на {1}% протягом {2} с.#slowed by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Cone of Cold" },
    [8494] = { "Щит мани", "Поглинає {1} фізичної шкоди за рахунок мани. Випалює {2} мани за кожну одиницю поглинутої шкоди. Триває {3} хв.#Absorbs {1} physical#Drains {2} mana#Lasts {3} min", "Поглинає фізичну шкоду за рахунок мани.", en="Mana Shield" },
    [8495] = { "Щит мани", "Поглинає {1} фізичної шкоди за рахунок мани. Випалює {2} мани за кожну одиницю поглинутої шкоди. Триває {3} хв.#Absorbs {1} physical#Drains {2} mana#Lasts {3} min", "Поглинає фізичну шкоду за рахунок мани.", en="Mana Shield" },
    [8512] = { "Тотем буревію", "Викликає тотем буревію з {1} здоров'я. Тотем підсилює вітром зброю в основній руці всіх учасників групи в межах {2} м. Кожен удар з імовірністю {3}% спричиняє {4} додаткову атаку зі збільшеною на {5} силою атаки ближнього бою. Триває {6} хв.#with {1} health#within {2} y#{3}% chance#{4} extra attack with {5}#Lasts {6} min", en="Windfury Totem" },
    [8532] = { "Аквадинамічна блешня", ref=8087, en="Aquadynamic Fish Lens" },
    [8552] = { "Прокляття слабкості", "Сила атаки ближнього бою цілі зменшується на {1} протягом {2} хв.#reduced by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [8599] = { "Несамовитість", nil, "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
    [8600] = { "Чумна лихоманка", "Завдає ворогу {1} шкоди від природи та додатково {2} шкоди кожні {3} с протягом {4} хв.#Inflicts {1} Nature#additional {2} damage#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Fevered Plague" },
    [8601] = { "Сповільнююча отрута", en="Slowing Poison" },
    [8611] = { "Фазування", nil, "Невидимість, але не може атакувати. Невразливість до всіх атак і заклять.", en="Phase Shift" },
    [8613] = { "Шкуродерство", "Основи білування тварин для отримання їхніх шкір та хутра, які можна використовувати у шкірництві. Дозволяє розвивати навичку шкуродерства до 75 рівня. Потрібен ніж для зняття шкур.", en="Skinning" },
    [8617] = { "Шкуродерство", "Поглиблений рівень навички здирання шкіри зі звірів для використання у шкірництві. Дозволяє розвивати навичку шкуродерства до 150 рівня. Потрібен ніж для зняття шкур.", en="Skinning" },
    [8618] = { "Шкуродерство", "Рівень навички експерта здирання шкур зі звірів для використання у шкірництві. Дозволяє розвивати навичку шкуродерства до 225 рівня. Потрібен ніж для зняття шкур.", en="Skinning" },
    [8621] = { "Підступний удар", "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", en="Sinister Strike" },
    [8623] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [8624] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [8629] = { "Ошелешення", "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", "Недієздатність.", en="Gouge" },
    [8631] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [8632] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [8633] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [8637] = { "Фінт", "Виконує оманливий випад, що не завдає шкоди та значно зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Feint" },
    [8639] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [8640] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [8643] = { "Удар по нирках", "Завершальний рух, що приголомшує ціль. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} с\n  2 прийоми: {2} с\n  3 прийоми: {3} с\n  4 прийоми: {4} с\n  5 прийомів: {5} с#1 point  : {1}#2 points: {2}#3 points: {3}#4 points: {4}#5 points: {5}", "Приголомшено.", en="Kidney Shot" },
    [8646] = { "Стрімкий копняк", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Snap Kick" },
    [8647] = { "Зняття броні", "Завершальний рух, що оголює ціль на {1} с, зменшуючи броню в залежності від довжини комбінації:\n  1 прийом: {2} броні\n  2 прийоми: {3} броні\n  3 прийоми: {4} броні\n  4 прийоми: {5} броні\n  5 прийомів: {6} броні#for {1} sec#1 point  : {2}#2 points: {3}#3 points: {4}#4 points: {5}#5 points: {6}", "Броню зменшено.", en="Expose Armor" },
    [8649] = { "Зняття броні", "Завершальний рух, що оголює ціль на {1} с, зменшуючи броню в залежності від довжини комбінації:\n  1 прийом: {2} броні\n  2 прийоми: {3} броні\n  3 прийоми: {4} броні\n  4 прийоми: {5} броні\n  5 прийомів: {6} броні#for {1} sec#1 point  : {2}#2 points: {3}#3 points: {4}#4 points: {5}#5 points: {6}", "Броню зменшено.", en="Expose Armor" },
    [8650] = { "Зняття броні", "Завершальний рух, що оголює ціль на {1} с, зменшуючи броню в залежності від довжини комбінації:\n  1 прийом: {2} броні\n  2 прийоми: {3} броні\n  3 прийоми: {4} броні\n  4 прийоми: {5} броні\n  5 прийомів: {6} броні#for {1} sec#1 point  : {2}#2 points: {3}#3 points: {4}#4 points: {5}#5 points: {6}", "Броню зменшено.", en="Expose Armor" },
    [8676] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [8679] = { "Миттєва отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, миттєво завдаючи від {3} до {4} шкоди від природи. {5} зарядів.#lasts for {1} min#has a {2}% chance#inflicts {3} to {4} Nature#{5} charges", en="Instant Poison" },
    [8680] = { "Миттєва отрута", en="Instant Poison" },
    [8681] = { "Миттєва отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, миттєво завдаючи від {3} до {4} шкоди від природи. {5} зарядів.#lasts for {1} min#has a {2}% chance#inflicts {3} to {4} Nature#{5} charges", en="Instant Poison" },
