    [8696] = { "Спринт", "Збільшує швидкість руху на {1}% протягом {2} с. Не порушує непомітності.#speed by {1}% for {2} sec", "Швидкість руху збільшено на {1}%.#by {1}%", en="Sprint" },
    [8715] = { "Жахаюче виття", "Змушує навколишніх ворогів втікати зі страху протягом {1} с.#for {1} sec", "Втікає зі страху.", en="Terrifying Howl" },
    [8721] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [8724] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [8725] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [8732] = { "Громовий удар", "Завдає всім навколишнім ворогам від {1} до {2} шкоди від природи.#for {1} to {2} nature", en="Thunderclap" },
    [8733] = { "Благословення Чорноводдя", nil, "Збільшує інтелект на {1}\nЗбільшує дух на {2}\nЗбільшує шкоду кригою на {3}#intellect by {1}#spirit by {2}#damage done by {3}", en="Blessing of Blackfathom" },
    [8737] = { "Кольчуга", en="Mail" },
    [8806] = { "Отруєний постріл", "Завдає ворогу звичайної шкоди плюс {1} та ще {2} шкоди від природи кожні {3} с протягом {4} хв.#plus {1} to#additional {2} Nature#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poisoned Shot" },
    [8817] = { "Димова шашка", "Кидає димову шашку, що приголомшує навколишніх ворогів на {1} с та надає заклиначу непомітність.#for {1} sec", "Приголомшено.", en="Smoke Bomb" },
    [8820] = { "Розтрощення", "Трощить ворога, завдаючи шкоди зброєю плюс {1}.#damage plus {1}", en="Slam" },
    [8823] = { "Удар лицаря", "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", "Збільшує отриману шкоду святістю на {1}.#up to {1}", en="Crusader Strike" },
    [8824] = { "Удар лицаря", "Удар, що завдає {1} шкоди та збільшує отриману ціллю шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#causes {1} damage#by up to {2} per#applied up to {3} times#Lasts {4} sec", "Збільшує отриману шкоду святістю на {1}.#up to {1}", en="Crusader Strike" },
    [8835] = { "Тотем поваби вітру", "Викликає тотем поваби вітру з {1} здоров'я. Тотем збільшує спритність учасників групи в межах {2} м на {3}. Триває {4} хв.#with {1} health#within {2} yards by {3}#Lasts {4} min", en="Grace of Air Totem" },
    [8836] = { "Поваба вітру", nil, "Збільшує спритність на {1}.#by {1}", en="Grace of Air" },
    [8873] = { "Полум'яне дихання", "Завдає {1} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} Fire", en="Flame Breath" },
    [8892] = { "Гоблінські реактивні черевики", "Ці небезпечні на вигляд черевики значно збільшують вашу швидкість бігу на {1} секунд. Однак вони можуть вибухнути, тому будьте обережні.#speed for {1} sec", "Збільшує швидкість руху. Також може вибухнути.", en="Goblin Rocket Boots" },
