    [9342] = { "Збільшення шкоди заклять {1}#Increase Spell Dam {1}", "Збільшує шкоду і зцілення від магічних заклинань і ефектів на {1}.#magical spells and effects by up to {1}", en="Increase Spell Dam 13" },
