    [9806] = { "Фантомний удар", "Зменшує броню цілі на {1} протягом {2} с. Поки діє ефект, ціль не може отримати ефект непомітності чи невидимості.#armor of the target by {1} for {2} sec", "Броню зменшено на {1}. Не може отримати ефект непомітності чи невидимості.#armor by {1}", en="Phantom Strike" },
