    [9910] = { "Шипи", "Шипи проростають із дружньої цілі, завдаючи {1} шкоди від природи нападникам при отриманні удару. Триває {2} хв.#causing {1}#Lasts {2} min", "Завдає {1} шкоди від природи нападникам.#Causes {1}", en="Thorns" },
