    [11100] = { "Метання полум'я", "Збільшує дальність дії ваших заклять вогню на {1} м.#by {1} yard", en="Flame Throwing" },
    [11103] = { "Струс", "Надає вашим закляттям вогню {1}% ймовірність приголомшити ціль на {2} с.#{1}% chance#for {2} sec", en="Impact" },
    [11108] = { "Покращений полум'яний удар", "Підвищує ймовірність критичного удару вашого закляття \"Полум'яний удар\" на {1}%.#spell by {1}%", en="Improved Flamestrike" },
    [11113] = { "Вибухова хвиля", "Заклинач збурює навколо себе полум'яну хвилю, яка завдає від {1} до {2} шкоди вогнем усім ворогам у радіусі дії, а також паморочить їх на {3} с.#blast for {1} to {2}#dazing them for {3} sec", "Запаморочення.", en="Blast Wave" },
    [11115] = { "Критична маса", "Підвищує ймовірність критичного удару ваших заклять вогню на {1}%.#spells by {1}%", en="Critical Mass" },
    [11119] = { "Займання", "Ваші критичні удари закляттями вогню змушують ціль горіти, отримуючи додатково {1}% від шкоди закляття протягом {2} с.#additional {1}#over {2} sec", en="Ignite" },
    [11124] = { "Сила вогню", "Збільшує шкоду від ваших заклять вогню на {1}%.#spells by {1}%", en="Fire Power" },
    [11129] = { "Палання", "При активації збільшує ймовірність критичного удару ваших заклять вогню на {1}% за кожне влучання закляттями вогню. Цей ефект триває, доки ви тричі не завдасте критичного удару закляттями вогню.#spells by {1}%", en="Combustion" },
    [11151] = { "Пронизливий лід", "Збільшує шкоду від ваших заклять криги на {1}%.#spells by {1}%", en="Piercing Ice" },
    [11160] = { "Спрямування криги", "Зменшує витрати мани на ваші закляття криги на {1}% і спричинену ними загрозу на {2}%.#mana cost of your Frost spells by {1}%#threat caused by your Frost spells by {2}%", en="Frost Channeling" },
    [11165] = { "Покращений крижаний спалах", "Зменшує час відновлення вашого закляття \"Крижаний спалах\" на {1} с.#spell by {1}", en="Improved Frost Nova" },
    [11170] = { "Розтрощення", "Збільшує ймовірність критичного удару всіх ваших заклять проти заморожених цілей на {1}%.#targets by {1}", en="Shatter" },
    [11175] = { "Вічна мерзлота", "Збільшує тривалість ваших ефектів \"Охолодження\" на {1} с та зменшує швидкість ворожої цілі ще на {2}%.#effects by {1} sec#additional {2}%", en="Permafrost" },
    [11180] = { "Зимова холоднеча", "Ваші крижані закляття з ймовірністю {1}% спричинять ефект \"Зимової холоднечі\", що збільшує ймовірність критичного удару заклять криги по цілі на {2}% протягом {3} с. Ефект накопичується до {4} разів.#{1}% chance#by {2}% for {3} sec#up to {4} times", en="Winter's Chill" },
    [11185] = { "Покращена метелиця", "Надає вашому закляттю \"Метелиця\" ефект охолодження, що знижує швидкість руху цілей на {1}% протягом {2} с.#speed by {1}%#Lasts {2} sec", en="Improved Blizzard" },
    [11189] = { "Крижаний захист", "Збільшує броню та опір від ваших заклять \"Крижаний обладунок\" і \"Льодяний обладунок\" на {1}%, а також надає вашому закляттю \"Крижаний оберіг\" {2}% імовірності відбити закляття та ефекти криги.#spells by {1}#{2}% chance to reflect", en="Frost Warding" },
    [11190] = { "Покращений конус холоду", "Збільшує шкоду від вашого закляття \"Конус холоду\" на {1}%.#spell by {1}%", en="Improved Cone of Cold" },
    [11196] = { "Щойно перев'язано", nil, "Не можна перев'язати знову.", en="Recently Bandaged" },
    [11197] = { "Зняття броні", "Завершальний рух, що оголює ціль на {1} с, зменшуючи броню в залежності від довжини комбінації:\n  1 прийом: {2} броні\n  2 прийоми: {3} броні\n  3 прийоми: {4} броні\n  4 прийоми: {5} броні\n  5 прийомів: {6} броні#for {1} sec#1 point  : {2}#2 points: {3}#3 points: {4}#4 points: {5}#5 points: {6}", "Броню зменшено.", en="Expose Armor" },
    [11198] = { "Зняття броні", "Завершальний рух, що оголює ціль на {1} с, зменшуючи броню в залежності від довжини комбінації:\n  1 прийом: {2} броні\n  2 прийоми: {3} броні\n  3 прийоми: {4} броні\n  4 прийоми: {5} броні\n  5 прийомів: {6} броні#for {1} sec#1 point  : {2}#2 points: {3}#3 points: {4}#4 points: {5}#5 points: {6}", "Броню зменшено.", en="Expose Armor" },
    [11201] = { "Травматична отрута", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Crippling Poison" },
    [11202] = { "Травматична отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, зменшуючи швидкість руху на {3}% протягом {4} с.#lasts for {1} min#{2}% chance#speed by {3}% for {4} sec", en="Crippling Poison" },
    [11207] = { "Льодяні уламки", "Збільшує додаткову шкоду від критичних ударів заклять криги на {1}%.#spells by {1}", en="Ice Shards" },
    [11210] = { "Арканічна вправність", "Зменшує опір цілі всім вашим закляттям на {1} та загрозу від ваших заклять аркани на {2}%.#all your spells by {1}#Arcane spells by {2}", en="Arcane Subtlety" },
    [11213] = { "Арканічна сконцентрованість", "Після завдання удару закляттям, ви з ймовірністю {1}% отримаєте ефект \"Ясномова\". \"Ясномова\" зменшує витрати мани вашого наступного бойового закляття на {2}%.#you a {1}% chance#spell by {2}%", en="Arcane Concentration" },
    [11222] = { "Арканічна зосередженість", "Зменшує ймовірність опонента протистояти вашим закляттям аркани на {1}%.#spells by {1}", en="Arcane Focus" },
    [11232] = { "Арканічний розум", "Збільшує ваш максимальний запас мани на {1}%.#maximum Mana by {1}%", en="Arcane Mind" },
    [11255] = { "Покращене протизакляття", "Надає вашому \"Протизакляттю\" {1}% імовірності знемовити ціль на {2} с.#{1}% chance#for {2} sec", en="Improved Counterspell" },
    [11267] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [11268] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [11269] = { "Засідка", "Раптовий удар, що завдає цілі {1}% від шкоди зброї плюс {2}. Необхідно перебувати в непомітності та позаду цілі. Працює лише за наявності кинджалу в основній руці. Збільшує довжину комбінації на 1 прийом.#causing {1}% weapon damage plus {2} to", en="Ambush" },
    [11273] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [11274] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [11275] = { "Розрив", "Завершальний рух, що завдає періодичної шкоди, яка збільшується від сили атаки. Тривалість залежить від довжини комбінації:\n  1 прийом: {1} шкоди за {2} c\n  2 прийоми: {3} шкоди за {4} c\n  3 прийоми: {5} шкоди за {6} c\n  4 прийоми: {7} шкоди за {8} c\n  5 прийомів: {9} шкоди за {10} c#1 point  : {1} damage over {2}#2 points: {3} damage over {4}#3 points: {5} damage over {6}#4 points: {7} damage over {8}#5 points: {9} damage over {10}", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Rupture" },
    [11279] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [11280] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [11281] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [11285] = { "Ошелешення", "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", "Недієздатність.", en="Gouge" },
    [11286] = { "Ошелешення", "Завдає {1} шкоди, робить ворога недієздатним на {2} с та зупиняє вашу атаку. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі. Збільшує довжину комбінації на {3} прийом.#Causes {1} damage#for {2} sec#Awards {3} combo", "Недієздатність.", en="Gouge" },
    [11289] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [11290] = { "Гарота", "Придушити ворога, завдаючи {1} шкоди протягом {2} с, що збільшується від вашої сили атаки. Необхідно перебувати в непомітності та позаду цілі. Збільшує довжину комбінації на {3} прийом.#causing {1} damage over {2} sec#Awards {3} combo", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Garrote" },
    [11293] = { "Підступний удар", "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", en="Sinister Strike" },
    [11294] = { "Підступний удар", "Миттєвий удар, завдає додатково {1} шкоди до звичайної шкоди зброєю. Збільшує довжину комбінації на {2} прийом.#causes {1}#{2} combo", en="Sinister Strike" },
    [11297] = { "Оглушення", "Робить ціль недієздатною на {1} с. Необхідно перебувати в непомітності. Діє лише проти гуманоїдів, що перебувають поза боєм. Будь-яка шкода знімає ефект з ураженої цілі. Одночасно лише 1 ціль може бути оглушеною.#up to {1} sec", "Недієздатність.", en="Sap" },
    [11299] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [11300] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [11303] = { "Фінт", "Виконує оманливий випад, що не завдає шкоди та значно зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Feint" },
    [11305] = { "Спринт", "Збільшує швидкість руху на {1}% протягом {2} с. Не порушує непомітності.#speed by {1}% for {2} sec", "Швидкість руху збільшено на {1}%.#by {1}%", en="Sprint" },
    [11319] = { "Ходіння по воді", "Дозволяє вам ходити по воді протягом {1} хв.#for {1} min", "Дозволяє ходити по воді та водоподібних поверхнях.", en="Water Walking" },
