    [11359] = { "Відновлення", "Знімає з вас один магічний ефект, прокляття, отруту або хворобу кожні {1} с протягом {2} с.#every {1} seconds for {2} sec", "Знімає один магічний ефект, прокляття, отруту або хворобу кожні {1} с протягом {2} с.#every {1} seconds for {2} sec", en="Restoration" },
    [11363] = { "Опір", "Збільшує ваш опір всім школам магії на {1} протягом {2} хв.#by {1} for {2} min", "Опір магії збільшено.", en="Resistance" },
    [11364] = { "Опір", "Збільшує ваш опір всім школам магії на {1} протягом {2} хв.#by {1} for {2} min", "Опір магії збільшено.", en="Resistance" },
    [11366] = { "Вогняна брила", "Кидає величезний вогняний валун, що завдає від {1} до {2} шкоди вогнем і додатково {3} шкоди вогнем протягом {4} с.#causes {1} to {2}#additional {3}#over {4} sec", "{1} шкоди вогнем кожні {2} секунди.#{1} Fire damage every {2} sec", en="Pyroblast" },
    [11371] = { "Дар Артаса", "Збільшує опір тіні на {1}. Нападників з ймовірністю {2}% буде уражено хворобою, яка збільшить отриману ними шкоду на {3} протягом {4} хв. Триває {5} хв.#shadow by {1}#a {2}% chance#damage taken by {3} for {4} min#Lasts for {5} min", "Збільшує опір тіні на {1} та може вразити нападників хворобою.#resist by {1}", en="Gift of Arthas" },
    [11374] = { "Дар Артаса", "Збільшує отриману фізичну шкоду на {1} протягом {2} хв..#taken by {1} for {2} min", "Отриману фізичну шкоду збільшено на {1}.#taken by {1}", en="Gift of Arthas" },
    [11387] = { "Зілля диколоззя", "Відновлює від {1} до {2} здоров'я та від {3} до {4} мани.#{1} to {2} health and {3} to {4} mana", en="Wildvine Potion" },
    [11389] = { "Виявлення невмерлих", "Відображає на мінімапі місцезнаходження невмерлих неподалік протягом {1} год.#for {1} h", "Виявлення невмерлих.", en="Detect Undead" },
    [11390] = { "Арканічний еліксир", "Збільшує шкоду заклинань на {1} протягом {2} хв.#to {1} for {2} min", "Магічну шкоду заклинань та здібностей збільшено на {1}.#by up to {1}", en="Arcane Elixir" },
