    [11629] = { "Потужний алкоголь", "Потужний алкогольний напій.", "Налиганий.", en="Potent Alcohol" },
    [11639] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [11641] = { "Пристріт", "Перетворює ворога на жабу, позбавляючи його можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [11650] = { "Удар головою", ref=56, en="Head Butt" },
    [11657] = { "Джанґ'траз", "Захищає власника від фізичної шкоди, поглинаючи від {1} до {2} шкоди. Триває {3} секунд.#absorbing {1} to {2} damage#Lasts {3} sec", "Поглинає фізичну шкоду.", en="Jang'thraze" },
