    [11693] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [11694] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [11695] = { "Канал здоров'я", "Передає прислужникові заклинача {1} здоров'я щосекунди протягом {2} с, поки заклинач підтримує це закляття.#Gives {1}#for {2} sec", "Передає здоров'я.", en="Health Funnel" },
    [11699] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [11700] = { "Висмоктування життя", "Передає {1} здоров'я щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1} health#Lasts {2} sec", "Висмоктує {1} здоров'я щосекунди, передаючи його заклиначеві.#Drains {1} health", en="Drain Life" },
    [11703] = { "Висмоктування мани", "Передає {1} мани щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1}#Lasts {2} sec", "Висмоктує {1} мани щосекунди, передаючи її заклиначеві.#Drains {1} mana", en="Drain Mana" },
    [11704] = { "Висмоктування мани", "Передає {1} мани щосекунди від цілі до заклинача. Триває {2} с.#Transfers {1}#Lasts {2} sec", "Висмоктує {1} мани щосекунди, передаючи її заклиначеві.#Drains {1} mana", en="Drain Mana" },
    [11707] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [11708] = { "Прокляття слабкості", "Ціль завдає на {1} менше шкоди протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [11717] = { "Прокляття відчайдушності", "Проклинає ціль відчайдушністю, збільшуючи її силу атаки ближнього бою на {1}, але зменшуючи броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху та жаху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", "Збільшує силу атаки ближнього бою на {1} і зменшує броню на {2}. Ціль не втікатиме та ігноруватиме ефекти страху та жаху.#power by {1}#armor by {2}", en="Curse of Recklessness" },
    [11719] = { "Прокляття мови", "Примушує ціль говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}%. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі. Триває {2} с.#by {1}%#Lasts {2} sec", "Говорить мовою демонів, що збільшує час вимови заклять на {1}%.#by {1}%", en="Curse of Tongues" },
    [11725] = { "Поневолення демона", "Поневолює обраного демона до {1} рівня, примушуючи його підкоритися вам. Протягом дії поневолення інтервал між атаками демона збільшується на {2}%, а його вимова заклять сповільнюється на {3}%. Триває до {4} хв. Якщо ви знову поневолюватимете одного й того ж демона, його буде важче контролювати з кожною наступною спробою.#up to level {1}#increased by {2}%#slowed by {3}%#up to {4} min", "Поневолено.", en="Subjugate Demon" },
    [11726] = { "Поневолення демона", "Поневолює обраного демона до {1} рівня, примушуючи його підкоритися вам. Протягом дії поневолення інтервал між атаками демона збільшується на {2}%, а його вимова заклять сповільнюється на {3}%. Триває до {4} хв. Якщо ви знову поневолюватимете одного й того ж демона, його буде важче контролювати з кожною наступною спробою.#up to level {1}#increased by {2}%#slowed by {3}%#up to {4} min", "Поневолено.", en="Subjugate Demon" },
    [11732] = { "Величезний камінь здоров'я", ref=5720, en="Major Healthstone" },
    [11733] = { "Демонічний обладунок", "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", en="Demon Armor" },
    [11734] = { "Демонічний обладунок", "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", en="Demon Armor" },
    [11735] = { "Демонічний обладунок", "Захищає заклинача, збільшуючи броню на {1}, а опір тіні на {2} та відновлюючи {3} здоров'я кожні {4} с протягом {5} хв.#armor by {1}#resistance by {2} and restores {3} health every {4} sec. for {5} min", "Збільшує броню на {1}, опір тіні на {2} та відновлює {3} здоров'я кожні {4} с.#armor by {1}#resistance by {2} and restores {3} health every {4} sec", en="Demon Armor" },
