    [11770] = { "Вогняний щит", "Оточує ціль щитом з вогню. Кожен удар по цілі завдає {1} шкоди вогнем нападнику. Триває {2} хв. Заклинач не може накласти \"Вогняний щит\" на себе.#causes {1} Fire#Lasts {2} min", "Завдає {1} шкоди вогнем нападникові при отриманні удару.#Does {1}", en="Fire Shield" },
    [11771] = { "Вогняний щит", "Оточує ціль щитом з вогню. Кожен удар по цілі завдає {1} шкоди вогнем нападнику. Триває {2} хв. Заклинач не може накласти \"Вогняний щит\" на себе.#causes {1} Fire#Lasts {2} min", "Завдає {1} шкоди вогнем нападникові при отриманні удару.#Does {1}", en="Fire Shield" },
