    [11790] = { "Отруйна хмара", "Завдає {1} шкоди від природи кожні {2} секунд усім ворогам в межах {3} м довкола заклинача протягом {4} секунд.#Deals {1} Nature#every {2} sec#in an {3} yard#for {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#Deals {1} Nature#every {2} sec", en="Poison Cloud" },
