    [11903] = { "Відновлення мани", "Відновлює [{1}#Restores {1} mana.][від {1} до {2}#Restores {1} to {2} mana.] мани.", en="Restore Mana" },
    [11918] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [11921] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [11922] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [11958] = { "Льодяна брила", "Вас огортає брила льоду, що захищає вас від усіх фізичних атак і заклять на {1} с, але протягом цього часу ви не можете атакувати, рухатися або вимовляти закляття.#for {1} sec", "Невразливість до всіх атак та заклять. Не може атакувати, рухатися та застосовувати закляття.", en="Ice Block" },
    [11960] = { "Прокляття Жахобою", nil, "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Curse of the Dreadmaul" },
    [11962] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [11963] = { "Знесилення", ref=7289, en="Enfeeble" },
    [11969] = { "Вогненний спалах", "Завдає шкоди від вогню навколишнім ворогам.", en="Fire Nova" },
    [11970] = { "Вогненний спалах", "Завдає шкоди від вогню навколишнім ворогам.", en="Fire Nova" },
    [11971] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [11977] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [11980] = { "Прокляття слабкості", "Зменшує завдану ціллю фізичну шкоду на {1} протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [11983] = { "Струмінь пари", "Завдає {1} шкоди від природи навколишнім ворогам та зменшує їх шанс завдання удару на {2}% протягом {3} с.#Inflicts {1} Nature#by {2}% for {3} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Steam Jet" },
