    [12530] = { "Кволість", "Зменшує всі характеристики навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Всі характеристики зменшено на {1}.#by {1}", en="Frailty" },
    [12531] = { "Морозний дотик", nil, "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Chilling Touch" },
    [12533] = { "Кислотний подих", "Завдає {1} шкоди від природи та додатково {2} шкоди кожні {3} с ворогам у конусі перед заклиначем. Триває {4} с.#Inflicts {1} Nature#additional {2} damage every {3} sec#Lasts {4} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Acid Breath" },
    [12536] = { "Ясномова", nil, "Витрати мани вашого наступного бойового закляття зменшено на {1}%.#reduced by {1}%", en="Clearcasting" },
    [12539] = { "Упиряча гниль", en="Ghoul Rot" },
    [12540] = { "Ошелешення", "Завдає ворогу {1} шкоди та приголомшує його на {2} с. Ви автоматично перестанете атакувати. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі.#Inflicts {1} damage#for up to {2} sec", "Недієздатність.", en="Gouge" },
    [12541] = { "Упиряча гниль", nil, "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Ghoul Rot" },
    [12542] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for {1} sec", "Втікає зі страху.", en="Fear" },
    [12543] = { "Фугасна бомба", ref=4064, en="Hi-Explosive Bomb" },
    [12548] = { "Крижаний шок", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frost Shock" },
    [12557] = { "Конус холоду", "Завдає шкоди від криги ворогам у конусі перед заклиначем та зменшує їх швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Cone of Cold" },
    [12560] = { "Гірництво", "Збільшує навичку гірництва на {1}.#Mining +{1}", en="Mining" },
    [12561] = { "Вогняний захист", "Поглинає від {1} до {2} шкоди від вогню. Триває {3} хв.#Absorbs {1} to {2}#Lasts {3} min", "Поглинає шкоду від вогню.", en="Fire Protection" },
    [12562] = { "Великан", ref=4064, en="The Big One" },
    [12579] = { "Зимова холоднеча", nil, "Закляття криги мають збільшену на {1}% ймовірність завдати критичного удару.#have a {1}%", en="Winter's Chill" },
    [12606] = { "Магічна налаштованість", "Посилює ефект заклять \"Підсилення магії\" та \"Пом'якшення магії\" на {1}%.#spells by {1}%", en="Magic Attunement" },
    [12608] = { "Виявлення непомітності", "Злегка посилює вашу здатність виявлення непомітності на {1} хв.#for {1} min", "Здатність виявлення непомітності злегка посилено.", en="Stealth Detection" },
    [12611] = { "Конус холоду", "Завдає шкоди від криги ворогам у конусі перед заклиначем та зменшує їх швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Cone of Cold" },
    [12656] = { "Інженерія", "Дозволяє створювати неймовірні пристрої і вибухівку та розвивати навичку до 300 рівня.", en="Engineering" },
    [12674] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [12675] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [12685] = { "Розтанення", "Розтанути у повітрі, зменшуючи всю вашу загрозу протягом {1} с.#for {1} sec", "Рівень загрози зменшено.", en="Fade" },
    [12686] = { "Несамовитість", "Збільшує шкоду на {1} і швидкість атаки на {2}% протягом {3} с.#done by {1} and#speed by {2}% for {3} sec", "Шкоду та швидкість атак ближнього бою збільшено.", en="Enrage" },
    [12693] = { "Висмоктування життя", "Викрадає {1} здоров'я у ворожої цілі.#Steals {1} life", en="Drain Life" },
    [12731] = { "Сила каменю", "Збільшує шкоду на {1} протягом {2} с.#damage by {1} for {2} sec", "Шкоду ближнього бою збільшено.", en="Strength of Stone" },
    [12733] = { "Безстрашність", "Збільшує броню на {1}, опір всім школам магії на {2} та надає невразливість до страху на {3} с.#armor by {1}#resistances by {2}#Fear for {3} sec", "Броню та опір магії збільшено. Невразливість до страху.", en="Fearless" },
    [12734] = { "Гуркіт землі", "Завдає фізичної шкоди навколишнім ворогам та приголомшує їх на {1} с.#for {1} sec", "Приголомшено.", en="Ground Smash" },
    [12738] = { "Збільшення шкоди", "Збільшує будь-яку отриману ворогом шкоду на {1}% протягом {2} с.#by {1}% for {2} sec", "Отриману фізичну та магічну шкоду збільшено на {1}%.#by {1}%", en="Amplify Damage" },
    [12741] = { "Прокляття слабкості", "Зменшує завдану навколишніми ворогами фізичну шкоду на {1} протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [12742] = { "Жертовний вогонь", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Immolate" },
    [12747] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [12748] = { "Крижаний спалах", "Вражає ворогів неподалік кригою, знерухомлюючи їх на {1} с.#immobilizing them for up to {1} sec", "Знерухомлено", en="Frost Nova" },
    [12749] = { "Мітрилове механічне драконеня", "Активувати мітрилове механічне драконеня, що битиметься за вас протягом {1} хв. Перш ніж його можна буде використати знову, йому потрібно відновитись протягом години.#fight for you for {1} min", en="Mithril Mechanical Dragonling" },
    [12765] = { "Покращена провокація", "Зменшує час відновлення здібності \"Провокація\" на {1} с.#ability by {1} sec", en="Improved Taunt" },
    [12792] = { "Виклик", "Збільшує загрозу від ваших атак на {1}% допоки ви перебуваєте в захисній стійці.#attacks by {1}", en="Defiance" },
    [12797] = { "Покращена помста", "\"Помста\" з ймовірністю {1}% приголомшить ціль на {2} с.#{1}% chance#for {2} sec", en="Improved Revenge" },
    [12809] = { "Приголомшливий удар", "Приголомшує ворога на {1} с.#for {1} sec", "Приголомшено.", en="Concussion Blow" },
    [12822] = { "Вбивця демонів", "Збільшує силу атаки на {1} в бою з демонами.#+{1} Attack Power when fighting Demons", en="Demon Slaying 18" },
    [12824] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [12825] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [12826] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття. Прискорене відновлення здоров'я.", en="Polymorph" },
    [12834] = { "Глибокі рани", "Ваші критичні удари викликають у супротивника кровотечу, що завдає {1}% від середньої шкоди вашої зброї ближнього бою протягом {2} с.#dealing {1}#over {2} sec", en="Deep Wounds" },
    [12857] = { "Покращений бойовий клич", "Збільшує додаткову силу атаки ближнього бою від вашого \"Бойового кличу\" на {1}%.#Shout by {1}%", en="Improved Battle Shout" },
    [12858] = { "Покращений бойовий клич", "Збільшує додаткову силу атаки ближнього бою від вашого \"Бойового кличу\" на {1}%.#Shout by {1}%", en="Improved Battle Shout" },
    [12860] = { "Покращений бойовий клич", "Збільшує додаткову силу атаки ближнього бою від вашого \"Бойового кличу\" на {1}%.#Shout by {1}%", en="Improved Battle Shout" },
    [12861] = { "Покращений бойовий клич", "Збільшує додаткову силу атаки ближнього бою від вашого \"Бойового кличу\" на {1}%.#Shout by {1}%", en="Improved Battle Shout" },
    [12862] = { "Покращене розтрощення", "Зменшує час застосування здібності \"Розтрощення\" на {1} с.#by {1} sec", en="Improved Slam" },
    [12863] = { "Покращена внутрішня лють", "Зменшує час відновлення здіюності \"Внутрішня лють\" на {1} с.#by {1} sec", en="Improved Inner Rage" },
    [12864] = { "Покращена внутрішня лють", "Зменшує час відновлення здіюності \"Внутрішня лють\" на {1} с.#by {1} sec", en="Improved Inner Rage" },
    [12865] = { "Покращена внутрішня лють", "Зменшує час відновлення здіюності \"Внутрішня лють\" на {1} с.#by {1} sec", en="Improved Inner Rage" },
