    [13225] = { "Агонічна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, зменшуючи ефективність будь-якого зцілення на {3} протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#them by {3} for {4} sec#up to {5} times#{6} charges", en="Wound Poison" },
    [13226] = { "Агонічна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, зменшуючи ефективність будь-якого зцілення на {3} протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#them by {3} for {4} sec#up to {5} times#{6} charges", en="Wound Poison" },
    [13227] = { "Агонічна отрута", "Покриває зброю отрутою на {1} хв.\nКожен удар з ймовірністю {2}% отруює ворога, зменшуючи ефективність будь-якого зцілення на {3} протягом {4} с. Ефект накопичується до {5} разів на одній цілі. {6} зарядів.#lasts for {1} min#a {2}% chance#them by {3} for {4} sec#up to {5} times#{6} charges", en="Wound Poison" },
    [13228] = { "Агонічна отрута II", ref=13220, en="Wound Poison II" },
    [13229] = { "Агонічна отрута III", ref=13220, en="Wound Poison III" },
    [13230] = { "Агонічна отрута IV", ref=13220, en="Wound Poison IV" },
    [13234] = { "Пояс запобігання шкоді", "Силовий щит захищає вас від наступних {1} од. шкоди протягом наступних {2} хв. УВАГА: Силове поле може перевантажитися при ударі, тимчасово запроторюючи власника в інший вимір.#next {1} damage#next {2} min", "Поглинає шкоду. Ефективність не гарантовано.", en="Harm Prevention Belt" },
    [13237] = { "Гоблінська мортира", "Завдає від {1} до {2} шкоди вогнем та приголомшує цілі в радіусі {3} метрів на {4} с.#Inflicts {1} to {2} Fire#in a {3} yard#for {4} sec", "Приголомшено.", en="Goblin Mortar" },
    [13238] = { "Гоблінська мортира", "Завдає від {1} до {2} шкоди вогнем та завдає {3} шкоди протягом {4} с цілям в радіусі {5} метрів.#Inflicts {1} to {2} Fire#causes {3} damage over {4} sec#in a {5} yard", "Приголомшено.", en="Goblin Mortar" },
    [13241] = { "Гоблінський саперний заряд", "При спрацюванні вибухає, завдаючи [{1}#triggered dealing {1} Fire damage][від {1} до {2}#triggered dealing {1} to {2} Fire damage] шкоди вогнем всім ворогам поблизу та [{1}#nearby and {1} damage to you][від {1} до {2}#nearby and {1} to {2} damage to you] шкоди вам.", en="Goblin Sapper Charge" },
    [13262] = { "Руйнування чарів", "Вилучення магічних елементів зі зброї чи обладунків як мінімум високої якості (зелений колір назви). При цьому предмет БЕЗПОВОРОТНО ЗНИЩУЄТЬСЯ.", en="Disenchant" },
    [13298] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [13318] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [13322] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [13323] = { "Поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати та вимовляти закляття, але дуже швидко відновлює здоров'я. Будь-яка шкода поверне ціль до нормального стану. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено.", en="Polymorph" },
    [13327] = { "Безрозсудний ривок", "Здійснити у ворога ривок, що робить його недієздатним на {1} секунд. Також збиває вас з ніг, приголомшуючи на короткий час. Будь-яка шкода повертає ціль до тями.#for {1} sec", "Недієздатність.", en="Reckless Charge" },
    [13338] = { "Прокляття мови", "Примушує ворога говорити мовою демонів, сповільнюючи час вимови заклять на {1}% протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1}% for {2} sec", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Curse of Tongues" },
    [13375] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [13383] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
    [13384] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
    [13385] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
    [13386] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
    [13387] = { "Збільшення навички захисту", "Збільшує навичку захисту на {1}.#Defense +{1}", en="Increased Defense" },
