    [14168] = { "Покращене зняття броні", "Посилює ефект зниження броні від здібності \"Зняття броні\" на {1}%.#by {1}%", en="Improved Expose Armor" },
    [14171] = { "Зазубрені леза", "Ваші атаки ігнорують {1} броні цілі, а ваша здібність \"Розрив\" завдає на {2}% більше шкоди. Значення ігнорованої броні зростає з вашим рівнем.#ignore {1}#by {2}", en="Serrated Blades" },
    [14174] = { "Покращений удар по нирках", "Перебуваючи під дією вашої здібності \"Удар по нирках\", ціль додатково отримує {1}% шкоди з усіх джерел.#additional {1}%", en="Improved Kidney Shot" },
