    [14178] = { "Липка смола", en="Sticky Tar" },
    [14179] = { "Невідступні удари", "Ваші завершальні рухи з ймовірністю {1}% за кожен прийом в комбінації відновлюють {2} енергії.#a {1}% chance#restore {2} energy", en="Relentless Strikes" },
