    [16059] = { "Рудий шаблезуб", "Викликає та відпускає верхового рудого шаблезуба.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Tawny Sabercat" },
    [16060] = { "Золотистий шаблезуб", "Викликає та відпускає верхового золотистого шаблезуба.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Golden Sabercat" },
    [16067] = { "Арканічний спалах", "Завдає цілі {1} шкоди від аркани.#for {1} Arcane", en="Arcane Blast" },
