    [16128] = { "Інфікований укус", "Завдає шкоди від природи ворогу кожні {1} с та збільшує отриману ним фізичну шкоду на {2} хв.#every {1} sec#for {2} min", "Завдає шкоди від природи кожні {1} с.\nОтриману фізичну шкоду збільшено.#every {1} sec", en="Infected Bite" },
    [16138] = { "Заточка леза V", ref=2828, en="Sharpen Blade V" },
    [16143] = { "Трупні черви", nil, "Отримання {1} шкоди від тіні кожні {2} с.\nВідновлення здоров'я сповільнено на {3}%.#{1} Shadow#every {2} sec#reduced by {3}%", en="Cadaver Worms" },
    [16145] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [16164] = { "Стихійна зосередженість", "Після вимови будь-якого бойового закляття вогню, криги чи природи ви з ймовірністю {1}% отримаєте ефект \"Ясномова\". \"Ясномова\" зменшує витрати мани вашого наступного бойового закляття на {2}%.#a {1}% chance#spell by {2}%", en="Elemental Focus" },
    [16168] = { "Вогняний ляпас", "Завдає цілі шкоди вогнем і збільшує отриману нею вогняну шкоду на {1} с.#for {1} sec", "Збільшено отриману шкоду від вогню.", en="Flame Buffet" },
    [16172] = { "Тріщина в черепі", "Зменшує витривалість ворога на {1} протягом {2} с.#by {1} for {2} sec", "Витривалість зменшено на {1}.#by {1}", en="Head Crack" },
    [16173] = { "Тотемна зосередженість", "Зменшує витрати мани ваших тотемів на {1}%.#by {1}%", en="Totemic Focus" },
    [16176] = { "Зцілення пращурів", "Збільшує броню вашої цілі на {1}% протягом {2} с після отримання критичного ефекту ваших цілющих заклять.#by {1}% for {2} sec", en="Ancestral Healing" },
    [16177] = { "Стійкість пращурів", nil, "Збільшує броню від предметів на {1}%.#by {1}%", en="Ancestral Fortitude" },
    [16178] = { "Очищення", "Збільшує ефективність ваших заклять зцілення на {1}%.[ Додатково збільшує ефективність зцілення \"Бистрини\" та \"Щита землі\" на {1}%.#Earth Shield by an additional {1}%]#healing spells by {1}%", en="Purification" },
    [16179] = { "Припливна зосередженість", "Зменшує витрати мани ваших заклять зцілення на {1}%.#by {1}%", en="Tidal Focus" },
    [16180] = { "Сприяння природи", "Збільшує вашу ймовірність завдати удару в ближньому бою та закляттями на {1}%.#by {1}%", en="Nature's Guidance" },
    [16181] = { "Зосередженість на зціленні", "З ймовірністю {1}% ви уникнете затримки вимови цілющих заклять при отриманні шкоди.#a {1}% chance", en="Healing Focus" },
    [16182] = { "Покращена хвиля зцілення", "Зменшує час вимови закляття \"Хвиля зцілення\" на {1} с.#by {1} sec", en="Improved Healing Wave" },
    [16184] = { "Покращена реінкарнація", "Зменшує час відновлення вашої здібності \"Реінкарнація\" на {1} хв та збільшує обсяг здоров'я і мани, з яким ви повертаєтеся до життя, на {2}%.#by {1} min#additional {2}%", en="Improved Reincarnation" },
    [16186] = { "Чумна лихоманка", "Завдає ворогу {1} шкоди від природи та додатково {2} шкоди кожні {3} с протягом {4} хв.#Inflicts {1} Nature#additional {2} damage#every {3} sec#for {4} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Fevered Plague" },
    [16187] = { "Відновлювальні тотеми", "Посилює ефекти ваших тотемів джерела мани та цілющого потоку на {1}%.#by {1}%", en="Restorative Totems" },
    [16188] = { "Стрімкість природи", "При активації ваше наступне закляття природи з тривалістю вимови менше {1} с буде миттєвим.#than {1} sec", "Ваше наступне закляття природи з тривалістю вимови менше {1} с буде миттєвим.#than {1} sec", en="Nature's Swiftness" },
    [16189] = { "Опанування тотемів", "Радіус дії ваших тотемів, які діють на дружні цілі, збільшено до {1} м.#increased to {1} y", en="Totemic Mastery" },
    [16190] = { "Тотем припливу мани", "Викликає тотем припливу мани з {1} здоров'я на {2} с. Тотем відновлює {3} мани кожні {4} с учасникам групи в межах {5} м.#with {1} health#for {2} sec#restores {3} mana every {4} sec#within {5} y", en="Mana Tide Totem" },
    [16191] = { "Приплив мани", nil, "Відновлює {1} мани кожні {2} с.#Gain {1} mana every {2} sec", en="Mana Tide" },
    [16194] = { "Опанування припливів", "Збільшує ймовірність критичного ефекту ваших заклять зцілення та блискавки на {1}%.#by {1}%", en="Tidal Mastery" },
    [16196] = { "Сприяння природи", "Збільшує вашу ймовірність завдати удару в ближньому бою та закляттями на {1}%.#by {1}%", en="Nature's Guidance" },
    [16198] = { "Сприяння природи", "Збільшує вашу ймовірність завдати удару в ближньому бою та закляттями на {1}%.#by {1}%", en="Nature's Guidance" },
    [16231] = { "Прокляття відчайдушності", "Збільшує силу атаки ближнього бою ворога на {1}, але зменшує його броню на {2} протягом {3} хв. Прокляті вороги не втікатимуть та ігноруватимуть ефекти страху. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#power by {1}#armor by {2} for {3} min", "Силу атаки ближнього бою збільшено на {1}.\nБроню зменшено на {2}.\nІгнорує ефекти страху.#increased by {1}#reduced by {2}", en="Curse of Recklessness" },
    [16244] = { "Деморалізуючий клич", "Зменшує силу атаки ближнього бою ворогів поблизу на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Demoralizing Shout" },
    [16246] = { "Ясномова", nil, "Ваше наступне стихійне бойове закляття витратить на {1}% менше мани.#by {1}%", en="Clearcasting" },
    [16247] = { "Прокляття шипів", "Проклинає ворога на {1} хв, внаслідок чого з ймовірністю {2}% при завданні удару він отримуватиме від {3} до {4} шкоди.#for {1} min#it {2}% chance to take {3} to {4} damage", "З ймовірністю {1}% отримає від {2} до {3} шкоди при атаці.#{1}% chance#take {2} to {3} damage", en="Curse of Thorns" },
    [16249] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [16250] = { "Залп вогняних куль", "Завдає шкоди від вогню навколишнім ворогам.", en="Fireball Volley" },
