    [16314] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [16315] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [16316] = { "Зброя каменолома", "Підсилює зброю шамана, внаслідок чого сила атаки ближнього бою збільшується на {1}, а атаки ближнього бою цією зброєю спричиняють додаткову загрозу. Триває {2} хв.#power by {1} and#for {2} min", en="Rockbiter Weapon" },
    [16321] = { "Джуджу уникання", "Збільшує ваш шанс ухилення від атак на {1}% протягом {2} с.#dodge by {1}% for {2} sec", "Ймовірність ухилення збільшено на {1}%.#chance by {1}%", en="Juju Escape" },
    [16322] = { "Джуджу шквалу", "Збільшує швидкість атаки цілі на {1}% протягом {2} с.#attack speed by {1}% for {2} sec", "Швидкість атаки збільшено на {1}%.#speed by {1}%", en="Juju Flurry" },
    [16323] = { "Джуджу сили", "Збільшує силу цілі на {1} протягом {2} хв.#Strength by {1} for {2} min", "Силу збільшено на {1}.#by {1}", en="Juju Power" },
    [16325] = { "Джуджу холоду", "Збільшує опір кризі на {1} протягом {2} хв.#resistance by {1} for {2} min", "Опір кризі збільшено на {1}.#by {1}", en="Juju Chill" },
    [16326] = { "Джуджу жару", "Збільшує опір вогню на {1} протягом {2} хв.#resistance by {1} for {2} min", "Опір вогню збільшено на {1}.#by {1}", en="Juju Ember" },
    [16327] = { "Джуджу кмітливості", "Збільшує інтелект цілі на {1} протягом {2} хв.#Intellect by {1} for {2} min", "Інтелект збільшено на {1}.#by {1}", en="Juju Guile" },
    [16329] = { "Джуджу міці", "Збільшує силу атаки на {1} протягом {2} хв.#attack power by {1} for {2} min", "Силу атаки збільшено на {1}.#by {1}", en="Juju Might" },
    [16333] = { "Дотик знесилення", "Зменшує силу ворога на {1}, а витривалість - на {2} протягом {3} хв.#Strength by {1}#Stamina by {2} for {3} min", "Силу зменшено на {1}.\nВитривалість зменшено на {2}.#Strength reduced by {1}#Stamina reduced by {2}", en="Debilitating Touch" },
    [16336] = { "Одержимі примари", ref=7057, en="Haunting Phantoms" },
    [16339] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [16340] = { "Крижаний подих", "Завдає шкоди від криги ворогам у конусі перед заклиначем, викрадаючи у них ману і зменшуючи швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Frost Breath" },
    [16341] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [16342] = { "Зброя язика полум'я", "Підсилює зброю шамана вогнем. Кожен удар завдає цілі від {1} до {2} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {3} хв.#causes {1} to {2}#Lasts for {3} min", en="Flametongue Weapon" },
    [16350] = { "Заморозка", "Крижаний спалах завдає шкоди та приголомшує ворогів у конусі перед заклиначем, та додатково завдає шкоди від криги кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Приголомшено.\nОтримання шкоди від криги кожні {1} с.#every {1} sec", en="Freeze" },
    [16355] = { "Зброя крижаного тавра", "Підсилює зброю шамана кригою. Кожен удар може завдати цілі додатково {1} шкоди кригою та сповільнити її рух на {2}% протягом {3} с. Триває {4} хв.#causing {1}#by {2}% for {3} sec#Lasts for {4} min", en="Frostbrand Weapon" },
    [16356] = { "Зброя крижаного тавра", "Підсилює зброю шамана кригою. Кожен удар може завдати цілі додатково {1} шкоди кригою та сповільнити її рух на {2}% протягом {3} с. Триває {4} хв.#causing {1}#by {2}% for {3} sec#Lasts for {4} min", en="Frostbrand Weapon" },
    [16359] = { "Подих їдкої кислоти", "Подих хмарою їдкої кислоти у ворогів, що перебувають у конусі перед заклиначем, зменшуючи їхню броню і завдаючи шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Броню зменшено.\nОтримання шкоди від природи кожні {1} с.#every {1} sec", en="Corrosive Acid Breath" },
    [16362] = { "Зброя буревію", "Підсилює зброю шамана вітром. Кожен удар з ймовірністю {1}% спричиняє {2} додаткові атаки зі збільшеною на {3} силою атаки ближнього бою. Триває {4} хв.#{1}% chance#{2} extra attacks with {3}#Lasts for {4} min", en="Windfury Weapon" },
    [16375] = { "Висмоктування життя", "Викрадає від {1} до {2} здоров'я у ворожої цілі.#Steals {1} to {2} life", en="Drain Life" },
    [16387] = { "Тотем язика полум'я", "Викликає тотем язика полум'я з {1} здоров'я. Тотем підсилює вогнем зброю в основній руці всіх учасників групи в межах {2} м. Кожен удар завдає від {3} до {4} додаткової шкоди вогнем залежно від швидкості зброї. Повільна зброя завдає більшої шкоди за удар. Триває {5} хв.#with {1} health#within {2} y#causes {3} to {4}#Lasts {5} min", en="Flametongue Totem" },
    [16390] = { "Полум'яне дихання", "Завдає {1} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} Fire", en="Flame Breath" },
    [16393] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [16396] = { "Полум'яне дихання", "Завдає {1} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} Fire", en="Flame Breath" },
    [16400] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [16401] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [16402] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди протягом {2} секунд.#causing {1} damage over {2} sec", "{1} шкоди від тіні кожні {2} с.#Inflicts {1} Shadow#every {2} sec", en="Corruption" },
    [16403] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [16405] = { "Рана", "Ранить ціль, завдаючи {1} шкоди.#for {1} damage", en="Wound" },
    [16406] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [16407] = { "Крижаний вибух", "Завдає цілі [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Blast" },
    [16408] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [16409] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [16410] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [16411] = { "Смертельна рана", "Завдає смертельної рани на [{1}#for {1} damage][{1}-{2}#for {1} to {2} damage] шкоди.", en="Fatal Wound" },
    [16412] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [16413] = { "Вогняна куля", "Кидає вогняну кулю, що завдає {1} шкоди від вогню і додатково {2} шкоди протягом {3} с.#causes {1} Fire#additional {2} damage over {3} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [16414] = { "Висмоктування життя", "Викрадає {1} здоров'я у ворожої цілі.#Steals {1} life", en="Drain Life" },
    [16415] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [16427] = { "Смертоносна отрута", nil, "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Virulent Poison" },
    [16429] = { "Пронизлива тінь", "Зменшує опір тіні ворога на {1} протягом {2} хв.#by {1} for {2} min", "Опір тіні зменшено на {1}.#by {1}", en="Piercing Shadow" },
    [16430] = { "Висмоктування душі", "Висмоктує частину душі ворога. Викрадає {1} здоров'я кожні {2} с та {3} мани кожні {4} с, передаючи їх заклиначу. Триває {5} с.#Steals {1} health every {2} sec#and {3} mana every {4} sec#Lasts {5} sec", "Викрадення {1} здоров'я кожні {2} с.\nВикрадення {3} мани кожні {4} с.#{1} health leeched every {2} sec#{3} mana leeched every {4} sec", en="Soul Tap" },
    [16431] = { "Кістяна броня", "Оточує заклинача кістяною броню, що поглинає від {1} до {2} шкоди протягом {3} хв. Під захистом кістяної броні отримана фізична шкода не спричиняє затримки вимови заклять.#absorbing {1} to {2} damage for {3} min", "Шкода поглинається кістяною бронею.", en="Bone Armor" },
    [16432] = { "Чумний туман", nil, "{1} шкоди від природи кожні {2} с.\nНе можна отримати ефект непомітності чи невидимості.#{1} Nature damage every {2} sec", en="Plague Mist" },
    [16433] = { "Рана", "Ранить ціль, завдаючи {1} шкоди.#for {1} damage", en="Wound" },
    [16448] = { "Чорна гниль", "Зменшує ймовірність ухилення ворога на {1}% протягом {2} хв.#by {1}% for {2} min", "Ймовірність ухилення зменшено на {1}%.#by {1}%", en="Black Rot" },
    [16449] = { "Личинковий слиз", "Зменшує силу атаки ближнього бою ворога на {1}, а силу атаки дальнього бою на {2} протягом {3} хв.#melee attack power by {1} and#ranged attack power by {2} for {3} min", "Силу атаки ближнього бою зменшено на {1}.\nСилу атаки дальнього бою зменшено на {2}.#Melee attack power reduced by {1}#Ranged attack power reduced by {2}", en="Maggot Slime" },
    [16454] = { "Палючий вибух", "Завдає цілі {1} шкоди від вогню та збільшує отриману нею шкоду від вогню на {2} протягом {3} с.#target for {1} Fire#by Fire damage by {2} for {3} sec", en="Searing Blast" },
    [16458] = { "Чума гуля", "Зменшує швидкість руху ворога на {1}% та зменшує всю завдану ним фізичну та магічну шкоду на {2}. Триває {3} хв.#enemy by {1}%#deals by {2}#Lasts {3} min", "Швидкість руху зменшено на {1}%.\nЗавдану фізичну та магічну шкоду зменшено на {2}.#speed reduced by {1}%#dealt is reduced by {2}", en="Ghoul Plague" },
    [16460] = { "Гнійні укуси", "Зменшує ймовірність завдання критичного удару ближнього бою ворога на {1}% та зменшує його ймовірність завдання критичного удару закляттями на {2}%. Триває {3} хв.#melee attack by {1}%#spell attack by {2}%#Lasts {3} min", "Ймовірність завдання критичного удару в ближньому бою зменшено на {1}%.\nЙмовірність завдання критичного удару закляттями зменшено на {2}%.#Melee critical-hit chance reduced by {1}%#Spell critical-hit chance reduced by {2}%", en="Festering Bites" },
    [16462] = { "Відбиття", "Збільшує вашу ймовірність парирування на {1}%.#by {1}%", en="Deflection" },
    [16468] = { "Материнське молоко", "Отруює навколишніх ворогів. Доки отрута не буде повністю виведена, вона буде періодично знерухомлювати отруєні цілі та їх союзників неподалік.", "Може знерухомити носія та навколишніх союзників. Триває поки отруту не розвіють або поки носія не \"подоять\".", en="Mother's Milk" },
    [16469] = { "Павутинний вибух", "Знерухомлює ціль на {1} с.#for {1} sec", en="Web Explosion" },
    [16470] = { "Дар каменю", "Збільшує броню на {1} протягом {2} с, однак протягом дії цього ефекту ви не можете атакувати чи вимовляти заклинання.#armor by {1} for {2} sec", "Броню збільшено на {1}, але неможливо атакувати та вимовляти заклинання.#armor by {1} but", en="Gift of Stone" },
    [16487] = { "Манія крові", "Відновлює {1}% здоров'я протягом {2} с після отримання критичного удару.#Regenerates {1}#over {2} sec", en="Blood Craze" },
    [16488] = { "Манія крові", nil, "Відновлює {1}% здоров'я протягом {2} с.#Regenerates {1}%#over {2} sec", en="Blood Craze" },
    [16493] = { "Пронизування", "Збільшує додаткову шкоду від критичних ударів ваших здібностей на {1}% у бойовій, оборонній та стійці берсерка.#stance by {1}%", en="Impale" },
    [16498] = { "Чарівний вогонь", "Зменшує броню ворога на {1} протягом {2} хв. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} min", "Броню зменшено на {1}.\nНе може отримати ефект непомітності чи невидимості.#by {1}", en="Faerie Fire" },
    [16508] = { "Жахаючий рик", "Ричить на ворога, змушуючи його тремтіти від страху протягом {1} с та змушуючи їнших ворогів довкола цілі втікати від страху.#for {1} sec", "Нажахано.", en="Intimidating Roar" },
    [16509] = { "Розрив", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає фізичної шкоди кожні {1} с.#every {1} sec", en="Rend" },
    [16511] = { "Крововилив", "Миттєвий удар, який завдає шкоди цілі та спричиняє крововилив, що збільшує отриману фізичну шкоду на {1}. Діє на {2} ударів або протягом {3} с. Збільшує довжину комбінації на {4} прийом.#by up to {1}#Lasts {2} charges or {3} sec#{4} combo", "Збільшує отриману шкоду на {1}.#by {1}", en="Hemorrhage" },
    [16513] = { "Мерзенні отрути", "Збільшує шкоду ваших отрут на {1}% та зменшує ймовірість розвіювання ваших отрут на {2}%.#by {1}%#{2}% chance", en="Vile Poisons" },
    [16528] = { "Нестерпний біль", "Викликає у цілі нестерпний біль, що завдає {1} шкоди від природи кожні {2} с і збільшує інтервал між атаками на {3}% протягом {4} с.#deals {1} Nature#every {2} sec#attacks by {3}% for {4} sec", "Завдає {1} шкоди від природи кожні {2} с. Інтервал між атаками збільшено на {3}%.#Deals {1} Nature#every {2} sec#attacks by {3}%", en="Numbing Pain" },
    [16536] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [16550] = { "Кістяні шипи", "Завдає [{1}#Deals {1} damage][від {1} до {2}#Deals {1} to {2} damage] шкоди, при отриманні критичного удару в ближньому бою.", en="Bonespike" },
    [16552] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [16555] = { "Утоплення", nil, "Швидкість плавання зменшено на {1}%.\nСпритність зменшено на {2}%.#speed reduced by {1}%#Agility reduced by {2}%", en="Drowning Death" },
    [16559] = { "Полум'яна лють", "Огортає власника вогняним щитом на {1} с та випускає вогняне кільце, що завдає [{1}#dealing {1} damage][від {1} до {2}#dealing {1} to {2} damage] шкоди всім ворогам поблизу.#Fire shield for {1} sec", en="Flame Wrath" },
