    [16862] = { "Звірина агресія", "Ваш \"Деморалізуючий рев\" знижує силу атаки ворога додатково на {1}%. Ваш \"Безжалісний укус\" завдає на {2}% більше шкоди.#Roar by {1}#Bite by {2}", en="Feral Aggression" },
    [16864] = { "Передвістя ясності", "Насичує друїда природною енергією. Атаки ближнього бою[ та немиттєві закляття#and non-instant spell casts] друїда можуть наділити його ефектом \"Ясномови\", який знижує витрати мани, енергії або люті на наступне ваше атакуюче чи цілюще закляття чи здібність на {1}%. Триває {2} хв.#by {1}#Lasts {2} min", "Атаки ближнього бою[ та немиттєві закляття#non-instant spell cast] можуть наділити заклинача ефектом \"Ясномови\".", en="Omen of Clarity" },
    [16866] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [16867] = { "Прокляття банші", "Зменшує ймовірність завдання удару навколишніми ворогами на {1}% протягом {2} с.#chance to hit by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Banshee Curse" },
    [16869] = { "Льодяна могила", ref=3609, en="Ice Tomb" },
    [16870] = { "Ясномова", nil, "Ваше наступне бойове або цілюще закляття чи здібність має знижену витрату мани, люті або енергії на {1}%.#by {1}%", en="Clearcasting" },
    [16871] = { "Хмуродеревне прокляття", "На ворога накладається хмуродеревне прокляття, що зменшує опір магії на {1}. Ефект накопичується до {2} разів.#resistances by {1}#up to {2} times", "Проклято. Опір магії зменшено на {1}.#reduced by {1}", en="Bleakwood Curse" },
    [16875] = { "Божественний дух", "Свята сила наповнює ціль, збільшуючи її дух на {1} протягом {2} хв.#by {1} for {2} min", "Збільшує дух на {1}.#by {1}", en="Divine Spirit" },
    [16876] = { "Арканічний інтелект", "Збільшує інтелект цілі на {1} протягом {2} хв.#by {1}#for {2} min", "Збільшує інтелект на {1}.#by {1}", en="Arcane Intellect" },
    [16880] = { "Природна благодать", "Критичні удари заклять дарують вам благословення природи, скорочуючи час вимови вашого наступного закляття на {1} с.#by {1} sec", en="Nature's Grace" },
    [16884] = { "Здоров'я II", ref=2378, en="Health II" },
    [16886] = { "Природна благодать", nil, "Час вимови вашого наступного закляття скорочено на {1} с.#by {1} sec", en="Nature's Grace" },
    [16887] = { "Броня IV", ref=673, en="Armor IV" },
    [16896] = { "Місячна лють", "Збільшує шкоду від ваших заклять \"Зоряний вогонь\", \"Місячний вогонь\" та \"Гнів\" на {1}%.#by {1}%", en="Moonfury" },
    [16898] = { "Обпалення", "Підпалиює ворога та завдає йому {1} шкоди протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди кожні {2} с.#{1} damage every {2} sec", en="Blaze" },
    [16902] = { "Зброя природи", "Збільшує [всю вашу шкоду#all damage][шкоду фізичних атак в усіх подобах#physical attacks] на {1}%.#by {1}%", en="Natural Weapons" },
    [16903] = { "Зброя природи", "Збільшує [всю вашу шкоду#all damage][шкоду фізичних атак в усіх подобах#physical attacks] на {1}%.#by {1}%", en="Natural Weapons" },
    [16904] = { "Зброя природи", "Збільшує [всю вашу шкоду#all damage][шкоду фізичних атак в усіх подобах#physical attacks] на {1}%.#by {1}%", en="Natural Weapons" },
    [16905] = { "Зброя природи", "Збільшує [всю вашу шкоду#all damage][шкоду фізичних атак в усіх подобах#physical attacks] на {1}%.#by {1}%", en="Natural Weapons" },
    [16906] = { "Зброя природи", "Збільшує [всю вашу шкоду#all damage][шкоду фізичних атак в усіх подобах#physical attacks] на {1}%.#by {1}%", en="Natural Weapons" },
    [16909] = { "Помста", "Збільшує додаткову шкоду від критичних ударів заклять \"Зоряний вогонь\", \"Місячний вогонь\" та \"Гнів\" на {1}%.#by {1}%", en="Vengeance" },
    [16914] = { "Ураган", "Створює бурхливий шторм у вказаному місці, завдаючи {1} шкоди від природи ворогам щосекунди та збільшуючи інтервал між атаками на {2}%. Триває {3} с. Друїд має підтримувати закляття.#causing {1}#enemies by {2}%#Lasts {3} sec", "{1} шкоди щосекунди та збільшення інтервалу між атаками на {2}%.#{1} damage#by {2}", en="Hurricane" },
    [16916] = { "Сила чемпіона", "Зцілює вам від {1} до {2} здоров'я та збільшує силу на {3} протягом {4} секунд.#self for {1} to {2} and#Strength by {3} for {4} sec", "Силу збільшено на {1}.#by {1}", en="Strength of the Champion" },
    [16918] = { "Покращене опутуюче коріння", "Надає {1}% ймовірності уникнути затримки вимови закляття \"Опутуюче коріння\" при отриманні шкоди.#a {1}% chance", en="Improved Entangling Roots" },
    [16921] = { "Ланцюгова блискавка", "Завдає {1} ворогам від {2} до {3} шкоди від природи.#up to {1} targets for {2} to {3} Nature", en="Chain Lightning" },
