    [16927] = { "Охолодження", "Сповільнює рух цілі на {1}%, а швидкість атаки - на {2}% протягом {3} секунд.#movement slowed by {1}%#attacks by {2}% for {3} sec", "Рух сповільнено на {1}%, а швидкість атаки зменшено на {2}%.#slowed by {1}% and#increased by {2}%", en="Chilled" },
    [16928] = { "Розбиття броні", "Зменшує броню цілі на {1}. Ефект накопичується до {2} разів.#armor by {1}#up to {2} times", "Броню зменшено на {1}.#by {1}", en="Armor Shatter" },
    [16929] = { "Товста шкура", "Збільшує броню, отриману від предметів, на {1}%.#items by {1}%", en="Thick Hide" },
    [16934] = { "Лютість", "Зменшує витрати люті або енергії на здібності \"Терзання\", \"Розмах\", \"Дряпання\" та \"Роздирання\" на {1}.#by {1}", en="Ferocity" },
    [16939] = { "Помста предків", "Збільшує шанс критичного удару учасників групи на {1}%. Триває {2} секунд.#crit increased by {1}%#Lasts for {2} sec", "Шанс критичного удару збільшено на {1}%.#by {1}%", en="Ancestor's Vengeance" },
    [16940] = { "Жорстокий струс", "Збільшує тривалість приголомшення ваших здібностей \"Стусан\" та \"Наскок\" на {1} с.#by {1} sec", en="Brutal Impact" },
    [16942] = { "Загострені кігті", "Збільшує ймовірність критичного удару у подобі кота, ведмедя чи жахливого ведмедя на {1}%.#by {1}%", en="Sharpened Claws" },
    [16947] = { "Звіриний інстинкт", "Збільшує загрозу у ведмежій подобі та подобі жахливого ведмедя на {1}% та зменшує ймовірність того, що вороги помітять вас під час використання здібності \"Зачаїтися\".#Bear Form by {1}%", en="Feral Instinct" },
    [16958] = { "Первісна лють", "З ймовірністю {1}% ви отримуєте {2} люті коли завдаєте критичного удару у ведмежій подобі чи подобі жахливого ведмедя.#{1}% chance#additional {2} Rage", en="Primal Fury" },
    [16968] = { "Покращене шматування", "Знижує витрати енергії здібності \"Шматування\" на {1}.#by {1}", en="Improved Shred" },
    [16972] = { "Удари хижака", "Збільшує силу атаки ближнього бою у подобі кота, ведмедя та жахливого ведмедя на {1}% від вашого рівня.#by {1}%", en="Predatory Strikes" },
    [16982] = { "Сфера вогню", "Надає шанс завдати ворогу [{1}#for {1} Fire][від {1} до {2}#for {1} to {2} Fire] шкоди вогнем при ударі.", en="Orb of Fire" },
    [16998] = { "Дика лють", "Збільшує шкоду здібностей \"Дряпання\", \"Роздирання\", \"Терзання\" та \"Розмах\" на {1}%.#by {1}%", en="Savage Fury" },
    [17003] = { "Серце дикої природи", "Збільшує ваш інтелект на {1}%. Крім того, у подобі ведмедя або жахливого ведмедя ваша витривалість збільшується на {2}%, а у котячій подобі ваша сила збільшується на {3}%.#Intellect by {1}%#Stamina is increased by {2}%#Strength is increased by {3}%", en="Heart of the Wild" },
    [17007] = { "Вожак зграї", "Коли ви перебуваєте у подобі кота, ведмедя чи жахливого ведмедя, \"Вожак зграї\" збільшує ймовірність критичного удару ближнього і дальнього бою всіх учасників групи в межах {1} м на {2}%.#within {1} y#by {2}%", en="Leader of the Pack" },
    [17013] = { "Спритність Аґамаґґана", "Збільшує спритність на {1}.#by {1}", "Збільшує спритність на {1}.#by {1}", en="Agamaggan's Agility" },
    [17038] = { "Огневиця Зимокрайових", "Збільшує силу атаки ближнього бою на {1} та збільшує розмір протягом {2} хв.#by {1} and#for {2} min", "Збільшує розмір, а також силу атаки ближнього бою на {1}.#by {1}", en="Winterfall Firewater" },
    [17039] = { "Майстер кування мечів", "Дозволяє виготовляти особливі мечі, які недоступні звичайним зброярам-ремісникам.", en="Master Swordsmith" },
    [17040] = { "Майстер кування молотів", "Дозволяє виготовляти особливі молоти, які недоступні звичайним зброярам-ремісникам.", en="Master Hammersmith" },
    [17041] = { "Майстер кування сокир", "Дозволяє виготовляти особливі сокири, які недоступні звичайним зброярам-ремісникам.", en="Master Axesmith" },
