    [17055] = { "Покращений знак дикої природи", "Підсилює ефекти ваших заклять \"Знак дикої природи\" та \"Дар дикої природи\" на {1}%.#by {1}%", en="Improved Mark of the Wild" },
    [17056] = { "Шаленість", "Надає вам {1}% ймовірності отримати {2} люті, коли ви набуваєте ведмежої подоби чи подоби жахливого ведмедя, або {3} енергії, коли ви набуваєте котячої подоби.#you {1}% chance#gain {2} Rage#or {3} Energy", en="Furor" },
    [17063] = { "Природне зосередження", "Надає {1}% ймовірності уникнути затримки вимови заклять \"Цілющий дотик\", \"Розростання\" та \"Спокій\" при отриманні шкоди.#{1}% chance", en="Nature's Focus" },
