    [17140] = { "Священний вогонь", "Ворога охоплює полум'я, що обпалює його та завдає додаткової шкоди від вогню кожні {1} с протягом {2} с.#every {1} sec#over {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Holy Fire" },
    [17141] = { "Священний вогонь", "Ворога охоплює полум'я, що обпалює його та завдає додаткової шкоди від вогню кожні {1} с протягом {2} с.#every {1} sec#over {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Holy Fire" },
    [17142] = { "Священний вогонь", "Ворога охоплює полум'я, що обпалює його та завдає додаткової шкоди від вогню кожні {1} с протягом {2} с.#every {1} sec#over {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Holy Fire" },
    [17145] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [17146] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [17148] = { "Мізкоруб", "Ранить ціль, завдаючи [{1}#for {1} damage][від {1} до {2}#for {1} to {2} damage] шкоди та знижуючи її інтелект на {1} протягом {2} с.#by {1} for {2} sec", "Інтелект знижено.", en="Brain Hacker" },
    [17150] = { "Арканічна міць", ref=15288, en="Arcane Might" },
