    [17274] = { "Вогняна брила", "Завдає ворогу шкоди від вогню та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Pyroblast" },
    [17275] = { "Серце луски", "Збільшує опір вогню на {1} та завдає {2} шкоди вогнем кожному, хто атакує вас в ближньому бою протягом {3} хв.#Resistance by {1} and deals {2} Fire#attack for {3} min", "Опір вогню збільшено. Завдає {1} шкоди вогнем нападникам.#causes {1} Fire", en="Heart of the Scale" },
    [17277] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [17281] = { "Удар лицаря", "Завдає ворогу {1} шкоди та збільшує отриману ним шкоду від святості на {2} за кожен \"Удар лицаря\". Ефект може накопичуватись до {3} разів. Триває {4} с.#Inflicts {1} damage#takes by {2} per#applied up to {3} times#Lasts {4} sec", "Отриману шкоду святістю збільшено.", en="Crusader Strike" },
    [17283] = { "Запальничка Димня", "Завдає [{1}#Deals {1} Fire][від {1} до {2}#Deals {1} to {2} Fire] шкоди вогнем всім цілям в конусі перед вами.", en="Smokey's Lighter" },
    [17286] = { "Молот лицаря", ref=6524, en="Crusader's Hammer" },
