    [17292] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [17293] = { "Пекучі вітри", "Приголомшує ворога та завдає {1} шкоди від вогню протягом {2} с.#inflicts {1} Fire#over {2} sec", "Приголомшено.\n{1} шкоди від вогню протягом {2} с.#{1} Fire#over {2} sec", en="Burning Winds" },
    [17294] = { "Полум'яне дихання", "Завдає {1} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} Fire", en="Flame Breath" },
    [17307] = { "Нокаут", "Завдає ворогові звичайної шкоди плюс {1}, відкидаючи його та приголомшуючи на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Knockout" },
    [17308] = { "Приголомшення", "Приголомшує ціль на {1} с.#silly for {1} sec", "Приголомшено.", en="Stun" },
    [17311] = { "Муки розуму", "Вражає розум цілі енергією тіні, завдаючи {1} шкоди від тіні протягом {2} с та сповільнюючи її рух на {3}%.#causing {1} Shadow#over {2} sec#speed by {3}%", "Швидкість руху зменшено на {1}%.#by {1}%", en="Mind Flay" },
    [17312] = { "Муки розуму", "Вражає розум цілі енергією тіні, завдаючи {1} шкоди від тіні протягом {2} с та сповільнюючи її рух на {3}%.#causing {1} Shadow#over {2} sec#speed by {3}%", "Швидкість руху зменшено на {1}%.#by {1}%", en="Mind Flay" },
