    [17314] = { "Муки розуму", "Вражає розум цілі енергією тіні, завдаючи {1} шкоди від тіні протягом {2} с та сповільнюючи її рух на {3}%.#causing {1} Shadow#over {2} sec#speed by {3}%", "Швидкість руху зменшено на {1}%.#by {1}%", en="Mind Flay" },
    [17315] = { "Пробиття броні", "Пробиває обладунок цілі, знижуючи її броню на {1}. Ефект накопичується до {2} разів/#lowering it by {1}#applied up to {2} times", "Броню зменшено на {1}.#decreased by {1}", en="Puncture Armor" },
    [17322] = { "Досяжність тіні", "Збільшує дальність дії ваших бойових заклять тіні на {1}%.#by {1}%", en="Shadow Reach" },
    [17329] = { "Схоплення природи", "Під час дії закляття кожен раз, коли ворог завдає удару заклиначеві, з ймовірністю {1}% його вразить закляття \"Опутуюче коріння\" (Ранг {2}). Можна використовувати тільки просто неба. {3} заряд. Триває {4} с.#{1}% chance#(Rank {2})#{3} charge#Lasts {4} sec", "При отриманні шкоди в ближньому бою може обплутати ворога.", en="Nature's Grasp" },
    [17331] = { "Ікло кришталевого павука", "Сповільнює вимову заклять ціллю та збільшує інтервал між атаками ближнього і дальнього бою на {1}% на {2} с.#attacks by {1}% for {2} sec", "Швидкість атак та вимови заклять зменшено.", en="Fang of the Crystal Spider" },
