    [17500] = { "Дубина Малоуна", "Приголомшує ціль на {1} c та збільшує вашу силу на {2} протягом {3} с.#silly for {1} sec#Strength by {2} for {3} sec", "Приголомшено.", en="Malown's Slam" },
    [17503] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [17504] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [17506] = { "Душелом", "Ворожа ціль втрачає {1} здоров'я та мани кожні {2} с протягом {3} с.#loses {1} health#every {2} sec for {3} sec", "Втрачає {1} здоров'я та мани кожні {2} с.#Drains {1} health#every {2} sec", en="Soul Breaker" },
    [17509] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [17510] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди протягом {2} секунд.#causing {1} damage over {2} sec", "{1} шкоди від тіні кожні {2} с.#Inflicts {1} Shadow#every {2} sec", en="Corruption" },
    [17511] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
