    [17544] = { "Крижаний захист", "Поглинає від {1} до {2} шкоди від криги. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від криги.#Absorbs {1} to {2}", en="Frost Protection" },
    [17545] = { "Священний захист", "Поглинає від {1} до {2} шкоди від святості. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від святості.#Absorbs {1} to {2}", en="Holy Protection" },
    [17546] = { "Природний захист", "Поглинає від {1} до {2} шкоди від природи. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від природи.#Absorbs {1} to {2}", en="Nature Protection" },
    [17547] = { "Смертельний удар", "Завдає {1}% шкоди від зброї та ранить ціль, зменшуючи ефективність будь-якого зцілення на {2}% протягом {3} с.#Inflicts {1}% weapon#healing by {2}% for {3} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Mortal Strike" },
    [17548] = { "Захист від тіні", "Поглинає від {1} до {2} шкоди від тіні. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від тіні.#Absorbs {1} to {2}", en="Shadow Protection" },
    [17549] = { "Арканічний захист", "Поглинає від {1} до {2} шкоди від аркани. Триває {3} год.#Absorbs {1} to {2}#Lasts {3} h", "Поглинає від {1} до {2} шкоди від аркани.#Absorbs {1} to {2}", en="Arcane Protection" },
    [17559] = { "Трансмутація: Повітря у вогонь", "Трасмутація повітря у вогонь.", en="Transmute: Air to Fire" },
