    [17745] = { "Хвороботворний плювок", "Плює у ворога отрутою, завдаючи шкоди від природи та зменшуючи його витривалість на {1} с.#Stamina for {1} sec", "Витривалість зменшено.", en="Diseased Spit" },
    [17750] = { "Страждання", "Провокує всіх ворогів у межах {1} м, збільшуючи ймовірність того, що вони атакуватимуть пустотника. Дієвіше за \"Страждання\" (Ранг {2}).#within {1} y#(Rank {2})", en="Suffering" },
    [17751] = { "Страждання", "Провокує всіх ворогів у межах {1} м, збільшуючи ймовірність того, що вони атакуватимуть пустотника. Дієвіше за \"Страждання\" (Ранг {2}).#within {1} y#(Rank {2})", en="Suffering" },
    [17752] = { "Страждання", "Провокує всіх ворогів у межах {1} м, збільшуючи ймовірність того, що вони атакуватимуть пустотника. Дієвіше за \"Страждання\" (Ранг {2}).#within {1} y#(Rank {2})", en="Suffering" },
