    [18092] = { "Крижаний вибух", "Завдає цілі [{1}#for {1} Frost][від {1} до {2}#for {1} to {2} Frost] шкоди від криги.", en="Frost Blast" },
    [18094] = { "Сутінки", "З ймовірністю {1}% ви набудете ефекту \"Тінетрансу\", коли ваші закляття \"Пошесть\" та \"Висмоктування життя\" завдають шкоди. \"Тінетранс\" зменшує час вимови наступного закляття \"Тіньова стріла\" на {2}%.#a {1}% chance#by {2}%", en="Nightfall" },
    [18097] = { "Зелена башта", "З ймовірністю {1}% при отриманні удару в бою вас захистить шипастий щит, що завдає {2} шкоди від природи нападникам та збільшує опір природі на {3} протягом {4} секунд.#a {1}% chance of raising#inflicts {2} Nature damage#Nature resistance by {3} for {4} sec", en="The Green Tower" },
    [18099] = { "Спалах холоду", "Вражає навколишніх ворогів, завдаючи шкоди від криги, відкидаючи їх та зменшуючи швидкість руху на {1} с.#up to {1} sec", "Швидкість руху зменшено.", en="Chill Nova" },
    [18101] = { "Охолодження", nil, "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Chilled" },
    [18103] = { "Різкий удар", "Різко б'є ворога, приголомшуючи його на {1} с.#for {1} sec", "Приголомшено.", en="Backhand" },
    [18104] = { "Гнів", "Завдає цілі [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Wrath" },
    [18105] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [18106] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [18107] = { "Рана", "Ранить ціль, завдаючи [{1}#for {1} damage][від {1} до {2}#for {1} to {2} damage] шкоди.", en="Wound" },
    [18108] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [18111] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [18112] = { "Вогняна стріла", "Завдає цілі {1} шкоди вогнем.#for {1} Fire", en="Firebolt" },
    [18118] = { "Наслідок", nil, "Рух сповільнено на {1}%.#by {1}%", en="Aftermath" },
    [18119] = { "Наслідок", "Ваші закляттям спеціалізації \"Руйнація\" з імовірнісю {1}% паморочать ціль на {2} с.#a {1}% chance#for {2} sec", en="Aftermath" },
    [18124] = { "Благословенний сонцеплід", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі. Також збільшує силу на {3} протягом {4} хв.#Restores {1} health over {2} sec#Strength by {3} for {4} min", ref=433, en="Blessed Sunfruit" },
    [18125] = { "Благословенний сонцеплід", "Збільшує силу на {1} протягом {2} хв.#by {1} for {2} min", "Силу збільшено на {1}.#by {1}", en="Blessed Sunfruit" },
    [18126] = { "Покращена вогняна стріла", "Зменшує час вимови закляття \"Вогняна стріла\" вашого біса на {1} с.#by {1} sec", en="Improved Firebolt" },
    [18127] = { "Покращена вогняна стріла", "Зменшує час вимови закляття \"Вогняна стріла\" вашого біса на {1} с.#by {1} sec", en="Improved Firebolt" },
    [18128] = { "Покращений батіг болю", "Зменшує час відновлення закляття \"Батіг болю\" вашого сукуба та інкуба на {1} с.#by {1} sec", en="Improved Lash of Pain" },
    [18129] = { "Покращений батіг болю", "Зменшує час відновлення закляття \"Батіг болю\" вашого сукуба та інкуба на {1} с.#by {1} sec", en="Improved Lash of Pain" },
    [18130] = { "Розгромлення", "Збільшує ймовірність завдання критичного удару закляттями спеціалізації \"Руйнація\" на {1}%.#by {1}%", en="Devastation" },
    [18135] = { "Напруження", "З ймовірністю {1}% ви уникнете затримки вимови заклять \"Вогняний дощ\", \"Пекельний вогонь\" або \"Випалення душі\" при отриманні шкоди.#a {1}% chance", en="Intensity" },
    [18137] = { "Тінестраж", "Жерця оточують тіні. Коли закляття або атака ближнього чи дальнього бою влучає у заклинача, нападнику буде завдано {1} шкоди від тіні. Ця шкода не спричиняє загрози та може бути завдана нападникам лише раз на кілька секунд. Ефект має {2} заряди та триває {3} хв.#struck for {1}#{2} charges#Lasts {3} min", "Завдасть {1} шкоди від тіні нападнику при отриманні удару. Ця шкода не спричиняє загрози. {2} заряди.#Causes {1}#{2} charges", en="Shadowguard" },
    [18138] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [18140] = { "Благословенний сік сонцеплоду", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття. Також збільшує дух на {3} протягом {4} хв.#Restores {1} mana over {2} sec#Spirit by {3} for {4} min", ref=430, en="Blessed Sunfruit Juice" },
    [18141] = { "Благословенний сік сонцеплоду", "Збільшує дух на {1} протягом {2} хв.#by {1} for {2} min", "Дух збільшено на {1}.#by {1}", en="Blessed Sunfruit Juice" },
    [18144] = { "Наліт", "Завдає звичайної шкоди плюс {1} ворогам в конусі перед заклиначем, приголомшуючи їх на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Swoop" },
    [18146] = { "Морозний дотик", en="Chilling Touch" },
    [18149] = { "Летюча зараза", "Заражає ворога на {1} хв, завдаючи {2} шкоди від природи всім його союзникам неподалік кожні {3} с.#enemy for {1} min#inflict {2} Nature#every {3} sec", "Завдає {1} шкоди від природи навколишнім союзниками кожні {2} с.#Inflicting {1} Nature#every {2} sec", en="Volatile Infection" },
    [18151] = { "Їдкий каталізатор", "Зменшує опір природі ворога на {1} протягом {2} хв.#by {1} for {2} min", "Опір природі зменшено на {1}.#reduced by {1}", en="Noxious Catalyst" },
    [18153] = { "Комбобулятор кодо", "Активувати поруч з древнім, старим або вмираючим кодо, щоб він пішов за вами (по одному за раз).", en="Kodo Kombobulator" },
    [18165] = { "Священний вогонь", "Ворога охоплює полум'я, що обпалює його та завдає додаткової шкоди від вогню кожні {1} с протягом {2} с.#every {1} sec#over {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Holy Fire" },
    [18173] = { "Палаючий адреналін", nil, "Шкоду збільшено на {1}%.\nЗакляття вимовляються миттєво.\nМаксимальний запас здоров'я зменшується на {2}% щосекунди.\nЗавдасть від {3} до {4} шкоди навколишнім союзникам при смерті.#increased by {1}%#by {2}% every#Deals {3} to {4} damage", en="Burning Adrenaline" },
    [18174] = { "Пригнічення", "Знижує ймовірність опору вашим закляттям спеціалізації \"Химородь\" на {1}%.#by {1}%", en="Suppression" },
    [18179] = { "Покращене прокляття слабкості", "Посилює ефект вашого \"Прокляття слабкості\" на {1}%.#by {1}%", en="Improved Curse of Weakness" },
    [18180] = { "Покращене прокляття слабкості", "Посилює ефект вашого \"Прокляття слабкості\" на {1}%.#by {1}%", en="Improved Curse of Weakness" },
    [18181] = { "Покращене прокляття слабкості", "Посилює ефект вашого \"Прокляття слабкості\" на {1}%.#by {1}%", en="Improved Curse of Weakness" },
    [18182] = { "Покращений витік життя", "Збільшує обсяг мани, отриманої від закляття \"Витік життя\", на {1}%.#by {1}%", en="Improved Life Tap" },
