    [18992] = { "Бірюзовий кодо", "Викликає та відпускає верхового бірюзового кодо. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Teal Kodo" },
    [19028] = { "Зв'язок душ", "При застосуванні {1}% від всієї отриманої вами шкоди буде натомість перенаправлено на вашого біса, пустотника, сукуба, інкуба або скверногончу. Окрім того, демон і його володар завдаватимуть на {2}% більше шкоди. Триває допоки демон активний.[ Не можна використовувати, поки активна \"Метаморфоза\".#Cannot be used while Metamorphosis]#{1}% of all damage#{2}% more damage", en="Soul Link" },
    [19128] = { "Збиття з ніг", "Завдає від {1} до {2} шкоди ворогу та його союзникам неподалік, приголомшуючи їх на {3} с. Вражає до {4} цілей.#Inflicts {1} to {2} damage#for {3} sec#up to {4} targets", "Приголомшено.", en="Knockdown" },
    [19133] = { "Крижаний шок", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frost Shock" },
    [19134] = { "Жахаючий клич", "Кричить на ворога, змушуючи його тремтіти від страху протягом {1} с та змушує всіх інших навколишніх ворогів втікати від страху.#for {1} sec", "Нажахано.", en="Intimidating Shout" },
    [19136] = { "Заряд бурі", "Завдає ворогу {1} шкоди та приголомшує його на {2} с.#Inflicts {1} damage#for {2} sec", "Приголомшено.", en="Stormbolt" },
    [19137] = { "Сповільнення", "Збільшує інтервал між атаками навколишніх ворогів на {1}% та зменшує їх швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slow" },
