    [19837] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
    [19838] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
    [19850] = { "Благословення мудрості", "Благословляє дружню ціль, відновлюючи їй {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Blessing of Wisdom" },
