    [19975] = { "Опутуюче коріння", "Приковує ціль на місці та завдає {1} шкоди від природи протягом {2} с. Подальша завдана шкода може перервати дію ефекту. Можна використовувати лише просто неба.#causes {1}#over {2} sec", "Приковано. Завдає {1} шкоди від природи кожні {2} с.#Causes {1}#every {2} sec", en="Entangling Roots" },
    [19977] = { "Благословення світла", "Благословляє дружню ціль, підсилюючи ефект \"Священного світла\" на ній на {1}, а \"Зблиску світла\" - на {2}. Триває {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#to {1} and the effect Flash of Light spells used on the target by up to {2}#Lasts {3} min", "Отримує {1} додаткового зцілення від \"Священного світла\" та {2} від \"Зблиску світла\".#Receives up to {1}#and up to {2}", en="Blessing of Light" },
    [19978] = { "Благословення світла", "Благословляє дружню ціль, підсилюючи ефект \"Священного світла\" на ній на {1}, а \"Зблиску світла\" - на {2}. Триває {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#to {1} and the effect Flash of Light spells used on the target by up to {2}#Lasts {3} min", "Отримує {1} додаткового зцілення від \"Священного світла\" та {2} від \"Зблиску світла\".#Receives up to {1}#and up to {2}", en="Blessing of Light" },
    [19979] = { "Благословення світла", "Благословляє дружню ціль, підсилюючи ефект \"Священного світла\" на ній на {1}, а \"Зблиску світла\" - на {2}. Триває {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#to {1} and the effect Flash of Light spells used on the target by up to {2}#Lasts {3} min", "Отримує {1} додаткового зцілення від \"Священного світла\" та {2} від \"Зблиску світла\".#Receives up to {1}#and up to {2}", en="Blessing of Light" },
    [19983] = { "Розсічення", "Завдає звичайної шкоди плюс {1} ворогу та його союзникам неподалік, вражаючи до {2} цілей.#plus {1} to#up to {2} target", en="Cleave" },
    [20005] = { "Охолодження", "Зменшує швидкість руху цілі на {1}% та збільшує інтервал між атаками на {2}% протягом {3} с.#slowed by {1}%#increased by {2}% for {3} sec", "Швидкість руху зменшено на {1}%, а інтервал між атаками збільшено на {2}%.#slowed by {1}%#increased by {2}%", en="Chilled" },
    [20007] = { "Свята сила", "Зцілює від {1} до {2} здоров'я та збільшує силу на {3} протягом {4} с.#for {1} to {2} and#by {3} for {4} sec", "Силу збільшено на {1}.#by {1}", en="Holy Strength" },
    [20019] = { "Всепоглинаюче полум'я", "Підпалює ворога, завдаючи {1} шкоди вогнем протягом {2} с і викликаючи у нього паніку. Поки ефект діє на ціль, полум'я періодично обпалює її союзників неподалік, завдаючи їм {3} шкоди.#inflicting {1} Fire damage over {2} sec#allies for {3} damage", "Ви горите!", en="Engulfing Flames" },
    [20021] = { "Всепоглинаюче полум'я", en="Engulfing Flames" },
    [20042] = { "Покращене благословення могутности", "Збільшує бонус до сили атаки ближнього бою від вашого \"Благословення могутності\" на {1}%.#by {1}%", en="Improved Blessing of Might" },
    [20043] = { "Аспект первісної природи", "Мисливець і учасники групи в межах {1} м переймають аспект первісної природи, збільшуючи опір природі на {2}. Одночасно може бути активним лише один аспект.#within {1} y#resistance by {2}", "Опір природі збільшено на {1}.#by {1}", en="Aspect of the Wild" },
    [20045] = { "Покращене благословення могутности", "Збільшує бонус до сили атаки ближнього бою від вашого \"Благословення могутності\" на {1}%.#by {1}%", en="Improved Blessing of Might" },
    [20046] = { "Покращене благословення могутности", "Збільшує бонус до сили атаки ближнього бою від вашого \"Благословення могутності\" на {1}%.#by {1}%", en="Improved Blessing of Might" },
    [20047] = { "Покращене благословення могутности", "Збільшує бонус до сили атаки ближнього бою від вашого \"Благословення могутності\" на {1}%.#by {1}%", en="Improved Blessing of Might" },
    [20048] = { "Покращене благословення могутности", "Збільшує бонус до сили атаки ближнього бою від вашого \"Благословення могутності\" на {1}%.#by {1}%", en="Improved Blessing of Might" },
    [20049] = { "Помста", "Збільшує вашу фізичну шкоду та шкоду святістю на {1}% протягом {2} с після того, як ви завдали критичного удару зброєю, закляттям або здібністю.[ Також зменшує загрозу від вашої фізичної шкоди та шкоди святістю на {1}%, поки \"Праведна лють\" неактивна.#threat you generate by {1}% while Righteous Fury]#a {1}% bonus to#deal for {2} sec after", en="Vengeance" },
    [20050] = { "Помста", nil, "Фізичну шкоду та шкоду святістю збільшено на {1}%.#by {1}%", en="Vengeance" },
    [20060] = { "Відбиття", "Збільшує вашу ймовірність парирування на {1}%.#by {1}%", en="Deflection" },
    [20066] = { "Розкаяння", "Вводить ворожу ціль у стан медитації, роблячи її недієздатною на {1} с. Будь-яка шкода пробудить ціль. Діє лише на гуманоїдів.#for up to {1} sec", "Недієздатність.", en="Repentance" },
    [20091] = { "Покращена аура розплати", "Збільшує шкоду від вашої \"Аури розплати\" на {1}%.#by {1}%", en="Improved Retribution Aura" },
    [20092] = { "Покращена аура розплати", "Збільшує шкоду від вашої \"Аури розплати\" на {1}%.#by {1}%", en="Improved Retribution Aura" },
    [20096] = { "Передчуття", "Збільшує вашу навичку захисту на {1}.#by {1}", en="Anticipation" },
    [20101] = { "Благодать", "Зменшує витрати мани закляття \"Присуд\" та печаток на {1}%.#by {1}%", en="Benediction" },
    [20111] = { "Спеціалізація на дворучній зброї", "Збільшує шкоду дворучної зброї ближнього бою на {1}%.#weapons by {1}%", en="Two-Handed Weapon Specialization" },
    [20116] = { "Освячення", "Освячує землю під паладином, завдаючи {1} шкоди святістю протягом {2} с усім ворогам в зоні дії.#doing {1} Holy damage over {2} sec", "{1} шкоди щосекунди.#{1} damage", en="Consecration" },
    [20117] = { "Переконання", "Збільшує вашу ймовірність завдання критичного удару зброєю ближнього бою на {1}%.#by {1}%", en="Conviction" },
    [20127] = { "Твердиня", "Збільшує ймовірність блокування атак щитом на {1}% після отримання критичного удару. Триває {2} с або {3} блоків.#shield by {1}#Lasts {2} sec or {3} block", en="Redoubt" },
    [20128] = { "Твердиня", nil, "Ймовірність блокування збільшено на {1}%. Триває до {2} блоків.#by {1}%#of {2}  blocks", en="Redoubt" },
    [20138] = { "Покращена аура відданості", "Збільшує додаткову броню від вашої \"Аури відданості\" на {1}%.#by {1}%", en="Improved Devotion Aura" },
    [20143] = { "Міць", "Збільшує броню від предметів на {1}%.#items by {1}%", en="Toughness" },
    [20148] = { "Спеціалізація на щитах", "Збільшує обсяг шкоди, що поглинає ваш щит, на {1}%.#by {1}%", en="Shield Specialization" },
    [20149] = { "Спеціалізація на щитах", "Збільшує обсяг шкоди, що поглинає ваш щит, на {1}%.#by {1}%", en="Shield Specialization" },
    [20150] = { "Спеціалізація на щитах", "Збільшує обсяг шкоди, що поглинає ваш щит, на {1}%.#by {1}%", en="Shield Specialization" },
    [20154] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.#for {1} sec#additional {2} to {3}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20162] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [20164] = { "Печатка правосуддя", "Наповнює паладина духом правосуддя на {1} с, надаючи кожній атаці ближнього бою ймовірність приголомшити ціль на {2} с. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, не дозволяючи йому втекти. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#justice for {1} sec#stun for {2} sec#enemy for {3} sec", "Атаки ближнього бою можуть приголомшити ціль на {1} с.#for {1} sec", en="Seal of Justice" },
    [20165] = { "Печатка світла", "Наповнює паладина божественним світлом на {1} с, надаючи кожній атаці ближнього бою ймовірність зцілити паладину {2} здоров'я. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам ближнього бою проти засудженої цілі ймовірність зцілити нападнику {4} здоров'я. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#light for {1} sec#heal the Paladin for {2}#enemy for {3} sec#attacker for {4}", "Атаки ближнього бою можуть відновити {1} здоров'я.#for {1}", en="Seal of Light" },
    [20166] = { "Печатка мудрості", "Наповнює паладина божественною мудрістю на {1} с, надаючи кожній атаці ближнього бою ймовірність відновити паладину {2} мани. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам та закляттям проти засудженої цілі ймовірність відновити нападнику {4} мани. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#wisdom for {1} sec#restore {2} of the Paladin#enemy for {3} sec#restore {4} mana to the attacker", "Атаки ближнього бою можуть відновити {1} мани.#restore {1} mana", en="Seal of Wisdom" },
    [20170] = { "Приголомшення", nil, "Приголомшено.", en="Stun" },
    [20174] = { "Прихильність хранителя", "Зменшує час відновлення \"Благословення захисту\" на {1} с і збільшує тривалість вашого \"Благословення свободи\" на {2} с.#Protection by {1}#Freedom by {2}", en="Guardian's Favor" },
    [20177] = { "Воздаяння", "Надає вам {1}% ймовірності провести додаткову атаку після отримання критичного удару.#{1}% chance", en="Reckoning" },
    [20184] = { "Присуд правосуддя", nil, "Не може втекти.", en="Judgement of Justice" },
    [20185] = { "Присуд світла", nil, "Атаки ближнього бою проти цієї цілі можуть відновити нападнику {1} здоров'я.#for {1}", en="Judgement of Light" },
    [20186] = { "Присуд мудрості", nil, "Атаки та закляття проти цієї цілі можуть відновити нападнику {1} мани.#restoring {1}", en="Judgement of Wisdom" },
    [20188] = { "Присуд лицаря", nil, "Збільшує отриману шкоду святістю на {1}.#by up to {1}", en="Judgement of the Crusader" },
    [20189] = { "Точність", "Збільшує вашу ймовірність завдання удару зброєю ближнього бою на {1}%.#by {1}%", en="Precision" },
    [20190] = { "Аспект первісної природи", "Мисливець і учасники групи в межах {1} м переймають аспект первісної природи, збільшуючи опір природі на {2}. Одночасно може бути активним лише один аспект.#within {1} y#resistance by {2}", "Опір природі збільшено на {1}.#by {1}", en="Aspect of the Wild" },
    [20194] = { "Покращене благословення спасіння", "Збільшує тривалість вашого \"Благословення спасіння\" на {1} хв.#by {1} min", en="Improved Blessing of Salvation" },
    [20195] = { "Покращене благословення спасіння", "Збільшує тривалість вашого \"Благословення спасіння\" на {1} хв.#by {1} min", en="Improved Blessing of Salvation" },
    [20196] = { "Спеціалізація на одноручній зброї", "Збільшує шкоду одноручної зброї ближнього бою на {1}%.#weapons by {1}%", en="One-Handed Weapon Specialization" },
    [20203] = { "Вогненний спалах", "Завдає шкоди від вогню навколишнім ворогам.", en="Fire Nova" },
    [20205] = { "Духовна зосередженість", "Надає закляттям \"Зблиск світла\" та \"Священне світло\" {1}% імовірності уникнути затримки вимови, спричиненої шкодою.#{1}% chance", en="Spiritual Focus" },
    [20210] = { "Сяйво", "Після критичного ефекту \"Зблиску світла\", \"Священного світла\" або \"Священного шоку\" ви з ймовірністю {1}% відновите ману в обсязі базової вартості закляття.#a {1}% chance", en="Illumination" },
    [20216] = { "Божественна прихильність", "При активації надає вашому наступному закляттю \"Зблиск світла\", \"Священне світло\" або \"Священний шок\" збільшену на {1}% ймовірність критичного ефекту.#spell a {1}", "Імовірність критичного ефекту наступного закляття \"Зблиск світла\", \"Священне світло\" або \"Священний шок\" збільшено на {1}%.#by {1}%", en="Divine Favor" },
    [20217] = { "Благословення королів", "Благословляє дружню ціль, збільшуючи всі характеристики на {1}% протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1}% for {2} min", "Збільшує характеристики на {1}%.#by {1}%", en="Blessing of Kings" },
    [20218] = { "Аура святості", "Збільшує шкоду святістю учасників групи в межах {1} м на {2}%. Гравці можуть мати лише одну ауру від кожного паладина одночасно.#within {1} yards by {2}", "Збільшує шкоду святістю на {1}%.#by {1}%", en="Sanctity Aura" },
    [20219] = { "Гномська інженерія", "Дозволяє інженеру створювати фантастичні, але ненадійні гномські пристрої.", en="Gnomish Engineer" },
    [20222] = { "Гоблінська інженерія", "Дозволяє інженеру створювати смертоносні гоблінські пристрої.", en="Goblin Engineer" },
    [20229] = { "Вибухова хвиля", "Завдає від {1} до {2} шкоди вогнем навколишнім ворогам та сповільнює їх рух на {3}% протягом {4} с.#Inflicts {1} to {2} Fire#speed by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Blast Wave" },
    [20230] = { "Відплата", "Миттєво контратакує будь-якого ворога, що завдає вам удару в ближньому бою протягом {1} с. Атаки ближнього бою зі спини неможливо контратакувати. Ця здібність спричинить не більше {2} контратак.#for {1} sec#{2} attacks", "Контратакує всі атаки ближнього бою.", en="Retaliation" },
    [20237] = { "Цілюще світло", "Збільшує обсяг зцілення вашими закляттями \"Священне світло\" та \"Зблиск світла\" на {1}%.#by {1}%", en="Healing Light" },
    [20243] = { "Спустошення", "Розколює броню цілі, накладаючи ефект \"Розколу броні\". Окрім того, завдає {1}% шкоди зброї плюс {2} за кожен ефект \"Розколу броні\" на цілі. Ефект \"Розколу броні\" накопичується до {3} разів.#causes {1}% of#plus {2} for#up to {3} times", "Броню зменшено на {1}.#by {1}", en="Devastate" },
    [20244] = { "Покращене благословення мудрості", "Підсилює ефект вашого \"Благословення мудрості\" на {1}%.#by {1}%", en="Improved Blessing of Wisdom" },
    [20245] = { "Покращене благословення мудрості", "Підсилює ефект вашого \"Благословення мудрості\" на {1}%.#by {1}%", en="Improved Blessing of Wisdom" },
    [20252] = { "Перехоплення", "Ривок у ворога, що завдає {1} шкоди та приголомшує його на {2} с.#causing {1} damage#for {2} sec", en="Intercept" },
    [20253] = { "Приголомшення від перехоплення", nil, "Приголомшено.", en="Intercept Stun" },
    [20254] = { "Покращена аура зосередженості", "Підсилює ефект вашої \"Аури зосередженості\" на {1}% та надає всім учасникам групи під впливом аури {2}% імовірності протистояти ефектам знемовлення та переривання.#Concentration Aura by an additional {1}%#the aura an additional {2}", en="Improved Concentration Aura" },
    [20257] = { "Божественний інтелект", "Збільшує ваш загальний інтелект на {1}%.#by {1}%", en="Divine Intellect" },
    [20262] = { "Божественна сила", "Збільшує вашу силу на {1}%.#Strength by {1}%", en="Divine Strength" },
    [20267] = { "Присуд світла", en="Judgement of Light" },
    [20268] = { "Присуд мудрості", en="Judgement of Wisdom" },
    [20271] = { "Присуд", "Вивільнює енергію печатки на ворога. Ефект присуду залежить від використаної печатки.", en="Judgement" },
    [20276] = { "Збиття з ніг", "Завдає від {1} до {2} шкоди ворогу та його союзникам неподалік, приголомшуючи їх на {3} с. Вражає до {4} цілей.#Inflicts {1} to {2} damage#for {3} sec#up to {4} targets", "Приголомшено.", en="Knockdown" },
    [20277] = { "Кулак Раґнароса", ref=6524, en="Fist of Ragnaros" },
    [20287] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20288] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20289] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20290] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20291] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20292] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20293] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові від {4} до {5} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4} to {5}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [20294] = { "Жертовний вогонь", "Завдає від {1} до {2} шкоди вогнем ворогу та обпалює його, завдаючи додатково від {3} до {4} шкоди кожні {5} с протягом {6} с.#Inflicts {1} to {2} Fire#additional {3} to {4} damage#every {5} sec#for {6} sec", "Отримання від {1} до {2} шкоди від вогню кожні {3} с.#{1} to {2} Fire#every {3} sec", en="Immolate" },
    [20297] = { "Крижана стріла", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frostbolt" },
    [20300] = { "Присуд лицаря", nil, "Збільшує отриману шкоду святістю на {1}.#by up to {1}", en="Judgement of the Crusader" },
    [20301] = { "Присуд лицаря", nil, "Збільшує отриману шкоду святістю на {1}.#by up to {1}", en="Judgement of the Crusader" },
    [20302] = { "Присуд лицаря", nil, "Збільшує отриману шкоду святістю на {1}.#by up to {1}", en="Judgement of the Crusader" },
    [20303] = { "Присуд лицаря", nil, "Збільшує отриману шкоду святістю на {1}.#by up to {1}", en="Judgement of the Crusader" },
    [20305] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [20306] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [20307] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [20308] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [20335] = { "Покращена печатка лицаря", "Збільшує силу атаки ближнього бою від вашої \"Печатки лицаря\" та шкоду святістю від вашого \"Присуду лицаря\" на {1}%.#by {1}%", en="Improved Seal of the Crusader" },
    [20336] = { "Покращена печатка лицаря", "Збільшує силу атаки ближнього бою від вашої \"Печатки лицаря\" та шкоду святістю від вашого \"Присуду лицаря\" на {1}%.#by {1}%", en="Improved Seal of the Crusader" },
    [20337] = { "Покращена печатка лицаря", "Збільшує силу атаки ближнього бою від вашої \"Печатки лицаря\" та шкоду святістю від вашого \"Присуду лицаря\" на {1}%.#by {1}%", en="Improved Seal of the Crusader" },
    [20344] = { "Присуд світла", nil, "Атаки ближнього бою проти цієї цілі можуть відновити нападнику {1} здоров'я.#for {1}", en="Judgement of Light" },
    [20345] = { "Присуд світла", nil, "Атаки ближнього бою проти цієї цілі можуть відновити нападнику {1} здоров'я.#for {1}", en="Judgement of Light" },
    [20346] = { "Присуд світла", nil, "Атаки ближнього бою проти цієї цілі можуть відновити нападнику {1} здоров'я.#for {1}", en="Judgement of Light" },
    [20347] = { "Печатка світла", "Наповнює паладина божественним світлом на {1} с, надаючи кожній атаці ближнього бою ймовірність зцілити паладину {2} здоров'я. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам ближнього бою проти засудженої цілі ймовірність зцілити нападнику {4} здоров'я. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#light for {1} sec#heal the Paladin for {2}#enemy for {3} sec#attacker for {4}", "Атаки ближнього бою можуть відновити {1} здоров'я.#for {1}", en="Seal of Light" },
    [20348] = { "Печатка світла", "Наповнює паладина божественним світлом на {1} с, надаючи кожній атаці ближнього бою ймовірність зцілити паладину {2} здоров'я. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам ближнього бою проти засудженої цілі ймовірність зцілити нападнику {4} здоров'я. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#light for {1} sec#heal the Paladin for {2}#enemy for {3} sec#attacker for {4}", "Атаки ближнього бою можуть відновити {1} здоров'я.#for {1}", en="Seal of Light" },
    [20349] = { "Печатка світла", "Наповнює паладина божественним світлом на {1} с, надаючи кожній атаці ближнього бою ймовірність зцілити паладину {2} здоров'я. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам ближнього бою проти засудженої цілі ймовірність зцілити нападнику {4} здоров'я. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#light for {1} sec#heal the Paladin for {2}#enemy for {3} sec#attacker for {4}", "Атаки ближнього бою можуть відновити {1} здоров'я.#for {1}", en="Seal of Light" },
    [20354] = { "Присуд мудрості", nil, "Атаки та закляття проти цієї цілі можуть відновити нападнику {1} мани.#restoring {1}", en="Judgement of Wisdom" },
    [20355] = { "Присуд мудрості", nil, "Атаки та закляття проти цієї цілі можуть відновити нападнику {1} мани.#restoring {1}", en="Judgement of Wisdom" },
    [20356] = { "Печатка мудрості", "Наповнює паладина божественною мудрістю на {1} с, надаючи кожній атаці ближнього бою ймовірність відновити паладину {2} мани. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам та закляттям проти засудженої цілі ймовірність відновити нападнику {4} мани. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#wisdom for {1} sec#restore {2} of the Paladin#enemy for {3} sec#restore {4} mana to the attacker", "Атаки ближнього бою можуть відновити {1} мани.#restore {1} mana", en="Seal of Wisdom" },
    [20357] = { "Печатка мудрості", "Наповнює паладина божественною мудрістю на {1} с, надаючи кожній атаці ближнього бою ймовірність відновити паладину {2} мани. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {3} с, надаючи атакам та закляттям проти засудженої цілі ймовірність відновити нападнику {4} мани. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#wisdom for {1} sec#restore {2} of the Paladin#enemy for {3} sec#restore {4} mana to the attacker", "Атаки ближнього бою можуть відновити {1} мани.#restore {1} mana", en="Seal of Wisdom" },
    [20359] = { "Затяжний присуд", "Збільшує тривалість ваших \"Присуду світла\" та \"Присуду мудрості\" на {1} с.#by {1} sec", en="Lasting Judgement" },
    [20360] = { "Затяжний присуд", "Збільшує тривалість ваших \"Присуду світла\" та \"Присуду мудрості\" на {1} с.#by {1} sec", en="Lasting Judgement" },
    [20361] = { "Затяжний присуд", "Збільшує тривалість ваших \"Присуду світла\" та \"Присуду мудрості\" на {1} с.#by {1} sec", en="Lasting Judgement" },
    [20375] = { "Печатка наказу", "Надає паладинові ймовірність завдати додаткової шкоди святістю в обсязі {1}% від звичайної шкоди зброєю. Лише одна печатка може бути задіяна на паладинові одночасно. Триває {2} с.\n\nВивільнення енергії цієї печатки засудить ворога, миттєво завдаючи від {3} до {4} шкоди святістю або від {5} до {6}, якщо ціль приголомшена або недієздатна.#equal to {1}#Lasts {2} sec#causing {3} to {4} Holy damage, {5} to {6}", "Атаки ближнього бою можуть завдати додаткової шкоди святістю.", en="Seal of Command" },
    [20425] = { "Присуд наказу", en="Judgement of Command" },
    [20467] = { "Присуд наказу", en="Judgement of Command" },
    [20468] = { "Покращена праведна лють", "Збільшує загрозу від вашого закляття \"Праведна лють\" на {1}%.#by {1}%", en="Improved Righteous Fury" },
    [20473] = { "Священний шок", "Вражає ціль священною енергією, завдаючи від {1} до {2} шкоди святістю ворогові або зцілюючи від {3} до {4} здоров'я союзникові.#{1} to {2} Holy damage#{3} to {4} healing", en="Holy Shock" },
    [20475] = { "Жива бомба", "Кидає у ворога бомбу. Через {1} с бомба вибухне, завдаючи {2} шкоди від вогню цілі та її союзникам, що знаходяться неподалік.#After {1} sec#inflicting {2} Fire", "Завдасть {1} шкоди навколишнім союзникам через {2} с.#{1} Fire#after {2} sec", en="Living Bomb" },
    [20484] = { "Переродження", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я і {2} мани.#{1} health and {2} mana", en="Rebirth" },
    [20487] = { "Покращений молот правосуддя", "Зменшує час відновлення вашого закляття \"Молот правосуддя\" на {1} с.#by {1} sec", en="Improved Hammer of Justice" },
    [20500] = { "Покращена лють берсерка", "При активації здібність \"Лють берсерка\" додає {1} люті.#generate {1} rage", en="Improved Berserker Rage" },
    [20502] = { "Покращена страта", "Зменшує витрати люті здібності \"Страта\" на {1}.#ability by {1}", en="Improved Execute" },
    [20504] = { "Покращене перехоплення", "Зменшує час відновлення здібності \"Перехоплення\" на {1} с.#ability by {1} sec", en="Improved Intercept" },
    [20511] = { "Жахаючий клич", nil, "Тремтить від страху.", en="Intimidating Shout" },
    [20542] = { "Статичний провідник", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с та збільшує отриману ними шкоду від природи на {3} протягом {4} с.#Inflicts {1} Nature#every {2} sec#by {3} for {4} sec", "Отримання {1} шкоди від природи кожні {2} с.\nОтриману шкоду від природи збільшено на {3}.#{1} Nature#every {2} sec#increased by {3}", en="Static Conduit" },
    [20549] = { "Бойовий тупіт", "Приголомшує до {1} ворогів в межах {2} м на {3} с.#{1} enemies within {2} yds for {3} sec", "Приголомшено.", en="War Stomp" },
    [20550] = { "Витримка", "Запас здоров'я збільшено на {1}%.#increased by {1}%", en="Endurance" },
    [20552] = { "Культивація", "Навичку травництва збільшено на {1}.#increased by {1}", en="Cultivation" },
    [20554] = { "Берсерк", "Збільшує швидкість вимови заклять і атаки на величину від {1}% до {2}%. При повному запасі здоров'я швидкість збільшується на {3}%, а з наявністю важких ран під час активації \"Берсерка\" - на {4}%. Триває {5} с.#speed by {1}% to {2}%#{3}% with a greater effect up to {4}#Lasts {5} sec", en="Berserking" },
    [20555] = { "Регенерація", "Швидкість регенерації здоров'я збільшено на {1}%. Регенерація здоров'я продовжується в бою зі швидкістю {2}% від звичайної.#increased by {1}%#{2}% of total", en="Regeneration" },
    [20557] = { "Знищення звірів", "Шкоду проти звірів збільшено на {1}%.#increased by {1}", en="Beast Slaying" },
    [20559] = { "Глумливий удар", "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", "Спровоковано.", en="Mocking Blow" },
    [20560] = { "Глумливий удар", "Глумлива атака, що завдає {1} шкоди, спричиняє помірний рівень загрози та змушує ціль атакувати вас протягом {2} с.#causes {1} damage#for {2} sec", "Спровоковано.", en="Mocking Blow" },
    [20564] = { "Первородний вогонь", nil, "{1} шкоди від вогню протягом {2} с.#{1} Fire#over {2} sec", en="Elemental Fire" },
    [20569] = { "Розсічення", "Розмашиста атака, що завдає шкоди зброєю плюс {1} по цілі та по найближчому до неї ворогу.#damage plus {1} to", en="Cleave" },
    [20572] = { "Кривава шаленість", "Збільшує базову силу атаки ближнього бою на {1}% протягом {2} c та зменшує отримане зцілення на {3}% протягом {4} с.#power by {1}% for {2} sec#you by {3}% for {4} sec", en="Blood Fury" },
    [20573] = { "Стійкість", "Збільшує ймовірність протистояти ефектам приголомшення на {1}%.#additional {1}%", en="Hardiness" },
    [20574] = { "Спеціалізація на сокирах", "Навички володіння сокирами та дворучними сокирами збільшено на {1}.#increased by {1}", en="Axe Specialization" },
    [20577] = { "Канібалізм", "При активації відновлює {1}% здоров'я кожні {2} с протягом {3} с. Діє лише на трупах гуманоїдів та невмерлих в межах {4} м. Будь-який рух, дія або отримання шкоди перериває процес.#regenerates {1}% of#every {2} sec for {3} sec#within {4} y", en="Cannibalize" },
    [20578] = { "Канібалізм", nil, "Відновлення {1}% здоров'я кожні {2} с.#Regenerate {1}%#every {2} sec", en="Cannibalize" },
    [20580] = { "Злиття з тінями", "Активуйте щоб злитися з тінями, зменшуючи ймовірність того, що вороги помітять вас. Діє до скасування або руху. Нічних ельфів-пройдисвітів та друїдів з цією здібністю важче виявити в непомітності.", "Злиття з тінями.", en="Shadowmeld" },
    [20582] = { "Прудкість", "Ймовірність ухилення збільшено на {1}%.#increased by {1}%", en="Quickness" },
    [20584] = { "Привид", nil, "Прямуйте до вашого тіла або поговоріть зі зцілювачем духу щоб повернутися до життя.", en="Ghost" },
    [20585] = { "Дух світлика", "Перетворює вас на світлика після смерті, збільшуючи швидкість руху на {1}%.#speed by {1}%", en="Wisp Spirit" },
    [20586] = { "Вітроріз", "Завдає шкоди від природи кожні {1} с протягом {2} с.#Nature damage every {1} sec for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Windreaper" },
    [20587] = { "Бездонна кружка Джона Лахмітника", "Збільшує витривалість на {1} і зменшує отриману фізичну шкоду на {2} протягом {3} хв. Натомість зменшує силу та спритність на {4} та збільшує отриману магічну шкоду на {5}.#Increases Stamina by {1}#reduces physical damage taken by {2} for {3} min#Agility by {4} and increases magical damage taken by up to {5}", "Потужне пійло.", en="Ragged John's Neverending Cup" },
    [20589] = { "Майстер втечі", "Вивільнитися від будь-яких ефектів сповільнення руху та знерухомлення.", en="Escape Artist" },
    [20591] = { "Неосяжний розум", "Інтелект збільшено на {1}%.#increased by {1}%", en="Expansive Mind" },
    [20593] = { "Спеціалізація на інженерії", "Навичку інженерії збільшено на {1}.#increased by {1}", en="Engineering Specialization" },
    [20594] = { "Кам'яна форма", "Надає невразливість до ефектів кровотечі, отрути та хвороб. Крім того, збільшує броню на {1}%. Триває {2} с.#increased by {1}#Lasts {2} sec", "Невразливість до ефектів кровотечі, отрути та хвороб. Броня збільшена на {1}%.#increased by {1}%", en="Stoneform" },
    [20597] = { "Спеціалізація на мечах", "Навички володіння мечами та дворучними мечами збільшено на {1}.#increased by {1}", en="Sword Specialization" },
    [20598] = { "Дух людей", "Дух збільшено на {1}%.#increased by {1}%", en="The Human Spirit" },
    [20600] = { "Сприйняття", "Значно підсилює здатність виявлення непомітності на {1} с.#for {1} sec", "Здатність виявлення непомітності значно підсилена.", en="Perception" },
    [20602] = { "Вогненний спалах", "Завдає шкоди від вогню навколишнім ворогам.", en="Fire Nova" },
    [20604] = { "Підкорення розуму", "Бере під контроль ворога-гуманоїда до {1} рівня на {2} с.#level {1} for {2} sec", "Причаровано.", en="Dominate Mind" },
    [20608] = { "Реінкарнація", "Дозволяє вам після смерті повернутися до життя з {1}% здоров'я та мани.#with {1}%", en="Reincarnation" },
    [20609] = { "Дух пращурів", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Ancestral Spirit" },
    [20610] = { "Дух пращурів", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я та {2} мани. Не можна використовувати в бою.#{1} health and {2} mana", en="Ancestral Spirit" },
    [20614] = { "Приголомшення від перехоплення", nil, "Приголомшено.", en="Intercept Stun" },
    [20615] = { "Приголомшення від перехоплення", nil, "Приголомшено.", en="Intercept Stun" },
    [20616] = { "Перехоплення", "Ривок у ворога, що завдає {1} шкоди та приголомшує його на {2} с.#causing {1} damage#for {2} sec", en="Intercept" },
    [20617] = { "Перехоплення", "Ривок у ворога, що завдає {1} шкоди та приголомшує його на {2} с.#causing {1} damage#for {2} sec", en="Intercept" },
    [20629] = { "Плювок їдкої отрути", "Плює у ворога отрутою, завдаючи шкоди, зменшуючи броню та завдаючи додаткової шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Броню зменшено.\nОтримання шкоди від природи кожні {1} с.#every {1} sec", en="Corrosive Venom Spit" },
    [20631] = { "Мішечок з медикаментами хутропузів", "Відновлює {1} здоров'я щосекунди протягом {2} с.#Restores {1} health#for {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Furbolg Medicine Pouch" },
    [20654] = { "Опутуюче коріння", "Обплутує навколишніх ворогів корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи їх на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [20656] = { "Чарівний вогонь", "Зменшує броню ворога на {1} протягом {2} хв. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} min", "Броню зменшено на {1}.\nНе може отримати ефект непомітності чи невидимості.#by {1}", en="Faerie Fire" },
    [20658] = { "Страта", "Спроба добити пораненого ворога, завдаючи {1} шкоди і додатково {2} шкоди за кожну надлишкову одиницю люті. Можна використати лише проти ворогів, що мають не більше {3}% здоров'я.#causing {1} damage#into {2} additional#have {3}% or less", en="Execute" },
    [20660] = { "Страта", "Спроба добити пораненого ворога, завдаючи {1} шкоди і додатково {2} шкоди за кожну надлишкову одиницю люті. Можна використати лише проти ворогів, що мають не більше {3}% здоров'я.#causing {1} damage#into {2} additional#have {3}% or less", en="Execute" },
    [20661] = { "Страта", "Спроба добити пораненого ворога, завдаючи {1} шкоди і додатково {2} шкоди за кожну надлишкову одиницю люті. Можна використати лише проти ворогів, що мають не більше {3}% здоров'я.#causing {1} damage#into {2} additional#have {3}% or less", en="Execute" },
    [20662] = { "Страта", "Спроба добити пораненого ворога, завдаючи {1} шкоди і додатково {2} шкоди за кожну надлишкову одиницю люті. Можна використати лише проти ворогів, що мають не більше {3}% здоров'я.#causing {1} damage#into {2} additional#have {3}% or less", en="Execute" },
    [20663] = { "Сон", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [20667] = { "Подих їдкої кислоти", "Подих хмарою їдкої кислоти у ворогів, що перебувають у конусі перед заклиначем, зменшуючи їхню броню і завдаючи шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Броню зменшено.\nОтримання шкоди від природи кожні {1} с.#every {1} sec", en="Corrosive Acid Breath" },
    [20669] = { "Сон", "Змушує ворогів неподалік спати протягом {1} с. Будь-яка шкода розбудить ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [20683] = { "Правосуддя верховного лорда", ref=6524, en="Highlord's Justice" },
    [20699] = { "Опутуюче коріння", "Обплутує навколишніх ворогів корінням, завдаючи від {1} до {2} шкоди від природи кожні {3} с та знерухомлюючи їх на {4} с.#inflicting {1} to {2} Nature#every {3} sec#up to {4} sec", "Знерухомлено.\nЗавдає від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Entangling Roots" },
    [20707] = { "Воскресіння каменем душі", "Зберігає душу дружньої цілі. Якщо ціль помирає, поки її душа збережена, вона зможе повернутись до життя з {1} здоров'я та {2} мани.#{1} health and {2} mana", "Душу збережено.", en="Soulstone Resurrection" },
    [20709] = { "Арканітовий ключ-відмичка", "Дозволяє відкривати складні замки. Одноразовий.", en="Arcanite Skeleton Key" },
    [20711] = { "Дух спокути", "Після смерті жрець перетворюється на духа спокути на {1} с. Дух не може рухатися, атакувати та бути ціллю будь-яких атак, заклять чи ефектів. Перебуваючи в такому стані, жрець може вимовляти будь-які цілющі закляття без витрат мани. Після закінчення дії ефекту жрець остаточно вмирає.#for {1} sec", en="Spirit of Redemption" },
    [20712] = { "Полум'яне дихання", "Завдає від {1} до {2} шкоди вогнем ворогам у конусі перед заклиначем.#Inflicts {1} to {2} Fire", en="Flame Breath" },
    [20714] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [20719] = { "Котяча грація", "Зменшує шкоду від падіння.", en="Feline Grace" },
    [20729] = { "Благословення жертовності", "Благословляє учасника групи, передаючи {1} отриманої за удар шкоди до заклинача. Триває {2} с. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#transfering {1} damage taken#Lasts {2} sec", "Передає {1} отриманої за удар шкоди до паладина.#{1} damage taken", en="Blessing of Sacrifice" },
    [20736] = { "Відволікаючий постріл", "Відволікає ціль, спричиняє загрозу.", en="Distracting Shot" },
    [20739] = { "Переродження", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я і {2} мани.#{1} health and {2} mana", en="Rebirth" },
    [20740] = { "Підкорення розуму", "Бере під контроль ворога-гуманоїда до {1} рівня на {2} с.#level {1} for {2} sec", "Причаровано.", en="Dominate Mind" },
    [20742] = { "Переродження", "Повертає дух до тіла, відроджуючи ціль з {1} здоров'я і {2} мани.#{1} health and {2} mana", en="Rebirth" },
