    [20753] = { "Деморалізуючий рев", "Зменшує силу атаки ближнього бою навколишніх ворогів на {1} протягом {2} с.#enemies by {1} for {2} sec", "Силу атаки ближнього бою зменшено на {1}.#by {1}", en="Demoralizing Roar" },
    [20755] = { "Створення каменя душі", "Створює камінь душі, який можна використати для зберігання душі цілі. Якщо ціль помирає, поки її душа збережена, вона зможе повернутись до життя з {1} здоров'я та {2} мани.\n\nНачакловані предмети зникнуть, якщо вийти з гри більше, ніж на {3} хв.#{1} health and {2} mana#than {3} min", en="Create Soulstone" },
    [20762] = { "Воскресіння каменем душі", "Зберігає душу дружньої цілі. Якщо ціль помирає, поки її душа збережена, вона зможе повернутись до життя з {1} здоров'я та {2} мани.#{1} health and {2} mana", "Душу збережено.", en="Soulstone Resurrection" },
    [20763] = { "Воскресіння каменем душі", "Зберігає душу дружньої цілі. Якщо ціль помирає, поки її душа збережена, вона зможе повернутись до життя з {1} здоров'я та {2} мани.#{1} health and {2} mana", "Душу збережено.", en="Soulstone Resurrection" },
