    [20967] = { "Присуд наказу", en="Judgement of Command" },
    [20968] = { "Присуд наказу", en="Judgement of Command" },
    [20969] = { "Живість", ref=18764, en="Vitality" },
    [20989] = { "Сон", "Змушує ворожу ціль спати протягом {1} с. Будь-яка шкода розбудить ціль. Одночасно можна змусити спати лише одну ціль.#up to {1} sec", "Спить.", en="Sleep" },
    [21007] = { "Прокляття слабкості", "Зменшує завдану навколишніми ворогами фізичну шкоду на {1} протягом {2} хв. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1} for {2} min", "Завдану фізичну шкоду зменшено на {1}.#by {1}", en="Curse of Weakness" },
    [21013] = { "Сила атаки дальнього бою {1}#Attack Power Ranged {1}", "Збільшує силу атаки дальнього бою на {1}.#+{1} ranged Attack Power", en="Attack Power Ranged 60" },
    [21030] = { "Крижаний шок", "Завдає ворогу шкоди кригою та зменшує його швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Frost Shock" },
    [21047] = { "Плювок їдкої кислоти", "Завдає ворогу шкоди від природи і зменшує його броню протягом {1} с.#for {1} sec", "Броню зменшено.", en="Corrosive Acid Spit" },
    [21055] = { "Дроблення броні", "Б'є по броні ворога, зменшуючи її на {1} за кожен ефект \"Дроблення броні\". Може накопичуватись до {2} разів. Триває {3} с.#it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Crush Armor" },
    [21056] = { "Знак Каззака", nil, "Висмоктує {1} мани кожні {2} с.\nВибухає, якщо не може висмоктати ману.#Drains {1} mana every {2} sec", en="Mark of Kazzak" },
    [21060] = { "Засліплення", "Засліплює ціль, змушуючи її блукати протягом {1} с. Будь-яка шкода перериває дію ефекту.#for up to {1} sec", "Дезорієнтовано.", en="Blind" },
    [21063] = { "Викривлене відображення", nil, "При отриманні шкоди зцілює нападнику {1} здоров'я.#for {1}", en="Twisted Reflection" },
    [21067] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Bolt" },
    [21068] = { "Пошесть", "Оскверняє навколишніх ворогів, завдаючи шкоди від тіні кожні {1} c протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Corruption" },
    [21069] = { "Слиз личинки", ref=17197, en="Larva Goo" },
    [21072] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [21081] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [21082] = { "Печатка лицаря", "Наповнює паладина духом лицаря на {1} с, надаючи {2} сили атаки ближнього бою. Паладин також атакує на {3}% швидше, але завдає менше шкоди з кожною атакою. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки засудить ворога на {4} с, збільшуючи отриману ним шкоду святістю на {5}. Ваші атаки ближнього бою оновлюватимуть тривалість ефекту. Одночасно може бути активним лише один присуд від кожного паладина.#crusader for {1} sec#granting {2} melee attack power#{3}% faster#enemy for {4} sec#damage taken by up to {5}", "Силу атаки ближнього бою збільшено на {1}. Атаки ближнього бою швидші на {2}%, але завдають менше шкоди.#increased by {1}#{2}% faster", en="Seal of the Crusader" },
    [21084] = { "Печатка праведності", "Наповнює паладина святим духом на {1} с, надаючи кожній атаці ближнього бою від {2} до {3} додаткової шкоди святістю. Повільніша зброя завдає більше шкоди святістю за удар. Лише одна печатка може бути задіяна на паладинові одночасно.\n\nВивільнення енергії цієї печатки завдасть ворогові {4} шкоди святістю.#for {1} sec#additional {2} to {3}#cause {4}", "Атаки ближнього бою завдають від {1} до {2} додаткової шкоди святістю.#additional {1} to {2}", en="Seal of Righteousness" },
    [21098] = { "Охолодження", "Вражає навколишніх ворогів льодом, завдаючи від {1} до {2} шкоди, збільшуючи інтервал між атаками на {3}% та зменшуючи швидкість руху на {4}%.#dealing {1} to {2} damage#attacks by {3}%#speed by {4}%", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Chill" },
    [21099] = { "Крижаний подих", "Завдає шкоди від криги ворогам у конусі перед заклиначем, викрадаючи у них ману і зменшуючи швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Frost Breath" },
    [21109] = { "Живість", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", "Відновлює {1} здоров'я кожні {2} с.#Restores {1} health per {2} sec", en="Vitality" },
    [21129] = { "Аура битви", en="Aura of Battle" },
    [21140] = { "Смертельна рана", "Завдає смертельної рани на [{1}#for {1} damage][{1}-{2}#for {1} to {2} damage] шкоди.", en="Fatal Wound" },
    [21141] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає {1} шкоди тінню і додатково {2} шкоди кожні {3} с протягом {4} с.#causing {1} Shadow#dealing {2} damage every {3} sec for {4} sec", "{1} шкоди від тіні кожні {2} с.#Deals {1} Shadow#every {2} sec", en="Shadow Bolt" },
    [21142] = { "Обпалення", "Завдає {1} шкоди від вогню всім, хто атакує вас у ближньому бою.#Deals {1} Fire", en="Immolation" },
    [21149] = { "Ґоґель-моґель", "Відновлює {1} здоров'я протягом {2} секунд. Потрібно залишатися в сидячому положенні під час їжі. Через {3} секунд ви насититесь і ваші витривалість та дух збільшаться на {4} протягом {5} хв. А ще він трішки п'янить...#Restores {1} health over {2} sec#at least {3} sec#gain {4} Stamina and Spirit for {5} min", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Egg Nog" },
    [21151] = { "Кровожерливий потрошитель", "Випускає у ворога тіньову стрілу, що завдає {1} шкоди від тіні та зменшує всі характеристика на {2} протягом {3} с..#causing {1} Shadow damage and lowering all stats by {2} for {3} sec", en="Gutgore Ripper" },
    [21152] = { "Землетряс", "Збиває з ніг усіх ворогів неподалік на {1} с.#enemies for {1} sec", "Приголомшено.", en="Earthshaker" },
    [21153] = { "Лезо Косторуба", "Ваші атаки ігнорують {1} броні протягом {2} с. Цей ефект накопичується до {3} разів.#ignore {1} of your#armor for {2} sec#stacks up to {3} times", "Ігнорує {1} ворожої броні.#Ignore {1} of", en="Bonereaver's Edge" },
    [21159] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [21162] = { "Вогняна куля", "Кидає вогняну кулю, яка завдає від {1} до {2} шкоди від вогню і додатково {3} шкоди від вогню протягом {4} с.#causes {1} to {2} Fire#additional {3} damage over {4} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire#every {2} sec", en="Fireball" },
    [21163] = { "Полірована броня", nil, "Броню збільшено на {1}%.#by {1}%", en="Polished Armor" },
    [21165] = { "Прискорення", "Збільшує вашу швидкість атаки на {1}% протягом {2} с.#speed by {1}% for {2} sec", "Швидкість атаки збільшено.", en="Haste" },
    [21168] = { "Живість", ref=18764, en="Vitality" },
    [21170] = { "Висмоктування життя", "Викрадає від {1} до {2} здоров'я у ворожої цілі.#Steals {1} to {2} life", en="Drain Life" },
    [21174] = { "Аура битви", "Відновлює {1} здоров'я та {2} мани щосекунди, поки ви перебуваєте поруч з лейтенантом.#Restores {1} Health and {2} Mana", "Відновлює {1} здоров'я та {2} мани щосекунди, поки ви перебуваєте поруч з лейтенантом.#Restores {1} Health and {2} Mana", en="Aura of Battle" },
    [21179] = { "Ланцюгова блискавка", "Вражає до {1} ворогів, завдаючи від {2} до {3} шкоди від природи. Кожна ціль після першої отримує зменшену шкоду.#up to {1} targets for {2} to {3} Nature", en="Chain Lightning" },
