    [21670] = { "Чарівний вогонь", "Зменшує броню ворога на {1} протягом {2} хв. Під час дії ефекту ціль не може отримати ефект непомітності чи невидимості.#by {1} for {2} min", "Броню зменшено на {1}.\nНе може отримати ефект непомітності чи невидимості.#by {1}", en="Faerie Fire" },
    [21687] = { "Токсичний залп", "Завдає шкоди від природи ворогові.", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Toxic Volley" },
    [21737] = { "Періодичне відкидування", "Періодично відкидує ворогів", "Періодично відкидує ворогів, зменшуючи їхню загрозу.\nНевразливість до провокації.", en="Periodic Knock Away" },
    [21787] = { "Смертельна отрута", "Завдає ворогу {1} шкоди від природи кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", ref=3583, en="Deadly Poison" },
    [21833] = { "Гоблінська гармата-дракон", "Завдає [{1}#Deals {1} fire][від {1} до {2}#Deals {1} to {2} fire] шкоди вогнем протягом {1} с всім ворогам в конусі перед інженером. Це якщо вона не вибухне...#damage for {1} sec to all", en="Goblin Dragon Gun" },
    [21848] = { "Сніговик", "Перетворитись на щось більш святкове. Для використання потрібна сніжка.", "Ви сніговик!", en="Snowman" },
    [21849] = { "Дар дикої природи", "Надає дар дикої природи групі цілі, збільшуючи броню на {1}, всі характеристики на {2} та всі види опору на {3} протягом {4} год.#armor by {1}#attributes by {2}#resistances by {3} for {4} h", "Збільшує броню на {1}, всі характеристики на {2} та всі види опору на {3}.#armor by {1}#attributes by {2}#resistances by {3}", en="Gift of the Wild" },
    [21850] = { "Дар дикої природи", "Надає дар дикої природи групі цілі, збільшуючи броню на {1}, всі характеристики на {2} та всі види опору на {3} протягом {4} год.#armor by {1}#attributes by {2}#resistances by {3} for {4} h", "Збільшує броню на {1}, всі характеристики на {2} та всі види опору на {3}.#armor by {1}#attributes by {2}#resistances by {3}", en="Gift of the Wild" },
    [21892] = { "Арканічний захист", "Ви отримуєте невразливість до всіх атак і заклять на {1} с.#spells for {1} sec", "Невразливість до всіх атак і заклять.", en="Arcane Protection" },
    [21894] = { "Медитація", "Дозволяє {1}% відновлення мани продовжуватися під час вимови заклять.#Allows {1}% of your", en="Meditation" },
    [21919] = { "Молотник", "Дозволяє виконати додаткову атаку під час наступного удару.", en="Thrash" },
    [21920] = { "Крижана міць", "Збільшує шкоду заклинань криги на {1} протягом {2} хв.#to {1} for {2} min", "Шкоду кригою від заклинань та здібностей збільшено на {1}.#by up to {1}", en="Frost Power" },
    [21931] = { "Чари для зброї - сила Зими", "Накласти на зброю чари, що збільшують шкоду від заклинань криги на {1}.#up to {1}", en="Enchant Weapon - Winter's Might" },
    [21949] = { "Розрив", "Ранить ціль, спричиняючи {1} шкоди від кровотечі протягом {2} с.#for {1} damage over {2} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rend" },
    [21951] = { "Кам'яний кулак", "Відновлює {1} мани.#Restores {1} mana.", en="Fist of Stone" },
    [21952] = { "Отрута", "Отруює ціль, завдаючи {1} шкоди від природи кожні {2} с протягом {3} с.#for {1} Nature damage every {2} sec for {3} sec", "{1} шкоди від природи кожні {2} с.#{1} Nature damage#every {2} sec", en="Poison" },
    [21955] = { "Корінь Бритвохляста", "Відновлює {1} здоров'я та мани протягом {2} с.#Restores {1} health#over {2} sec", "Відновлює {1} здоров'я та мани щосекунди.#Restores {1} health", en="Razorlash Root" },
    [21956] = { "Фізичний захист", "Поглинає від {1} до {2} фізичної шкоди. Триває {3} с.#Absorbs {1} to {2} physical#Lasts {3} sec", "Поглинає від {1} до {2} фізичної шкоди.#Absorbs {1} to {2} physical", en="Physical Protection" },
    [21961] = { "Рана", "Ранить ціль, завдаючи {1} шкоди та зменшуючи броню на {2}.#for {1} damage#armor by {2}", en="Wound" },
    [21969] = { "Знак обраних", "З шансом {1}% при отриманні удару в бою збільшує всі характеристики на {2} протягом {3} хв.#a {1}% chance#stats by {2} for {3} min", en="Mark of the Chosen" },
    [21971] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Bolt" },
    [21978] = { "Огортання тінями", "Шанс при ударі бойовим закляттям завдати цілі {1} шкоди від тіні та відновити {2} мани.#to deal {1} Shadow#restore {2} mana", en="Engulfing Shadows" },
    [21989] = { "В очікуванні воскресіння", en="Waiting to Resurrect" },
    [21992] = { "Громолють", "Вражає ворога блискавкою, що завдає {1} шкоди від природи, а потім стрибає на інших ворогів, що знаходяться поруч. Кожен стрибок зменшує опір силам природи жертви на {2}. Вражає до {3} цілей. Ваша основна ціль також поглинається циклоном, що зменшує швидкість її атаки на {4}% протягом {5} с.#dealing {1} Nature#resistance by {2}.#Affects {3} targets#speed by {4}% for {5} sec", "Опір природі зменшено на {1}.#reduced by {1}", en="Thunderfury" },
    [22067] = { "Відбиття", "Заклинач з ймовірністю {1}% відбиватиме бойові закляття протягом {2}.#caster {1}%#for {2} sec", "З ймовірністю {1}% відбиває закляття.#{1}% chance", en="Reflection" },
    [22088] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [22127] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [22188] = { "Збільшення навички володіння арбалетами", "Збільшує навичку володіння арбалетами на {1}.#Crossbows +{1}", en="Increased Crossbow" },
    [22206] = { "Місячний вогонь", "Обпалює ворога, завдаючи шкоди арканою та додатково шкоди протягом {1} с.#over {1} sec", "Отримання шкоди від аркани кожні {1} с.#every {1} sec", en="Moonfire" },
    [22247] = { "Аура пригнічення", nil, "Швидкість руху зменшено на {1}%.\nІнтервал між атаками збільшено на {2}%.\nВимову заклять сповільнено на {3}%.#Movement speed reduced by {1}%#increased by {2}%#Casting speed reduced by {3}%", en="Suppression Aura" },
    [22274] = { "Велика поліморфія", "Перетворює ворога на вівцю, змушуючи його блукати до {1} с. Вівця не здатна атакувати або вимовляти закляття, але дуже швидко відновлює здоров'я. Одночасно лише одна ціль може бути під ефектом \"Поліморфії\". Діє лише на звірів, драконів, велетнів, гуманоїдів і звіряток.#up to {1} sec", "Не може атакувати та вимовляти закляття.\nШвидкість регенерації здоров'я збільшено.", en="Greater Polymorph" },
