    [22335] = { "Пляшка отрути", "Кидає у ворога пляшку з отрутою, що завдає {1} шкоди від природи кожні {2} с протягом {3} с.#inflicting {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Bottle of Poison" },
    [22356] = { "Сповільнення", "Збільшує інтервал між атаками навколишніх ворогів на {1}% та зменшує їх швидкість руху на {2}% протягом {3} с.#attacks by {1}%#movement by {2}% for {3} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.#increased by {1}%#reduced by {2}%", en="Slow" },
    [22371] = { "Прокляття безсилля", "Зменшує магічну шкоду цілі на {1} протягом {2} хв.#by {1} for {2} min", "Магічну шкоду зменшено на {1}.#by {1}", en="Curse of Impotence" },
    [22412] = { "Смертоносна отрута", nil, "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Virulent Poison" },
    [22415] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [22420] = { "Занурення", "Зменшує витривалість навколишніх ворогів на {1} протягом {2} хв.#by {1} for {2} min", "Витривалість зменшено на {1}.#by {1}", en="Submersion" },
    [22423] = { "Вогняний шок", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Flame Shock" },
    [22424] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [22425] = { "Залп вогняних куль", "Завдає шкоди від вогню навколишнім ворогам.", en="Fireball Volley" },
    [22426] = { "Дроблення броні", "Б'є по броні ворога, зменшуючи її на {1} за кожен ефект \"Дроблення броні\". Може накопичуватись до {2} разів. Триває {3} с.#it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Crush Armor" },
    [22428] = { "Оскаженіння", nil, "Швидкість атаки збільшено на {1}%.#by {1}%", en="Frenzy" },
    [22430] = { "Витончена луска Оніксії", "Перетворює луску Оніксії на витончену луску Оніксії.", en="Refined Scale of Onyxia" },
    [22433] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [22438] = { "Знак детонації", nil, "Завдає від {1} до {2} шкоди собі та навколишнім союзникам при отриманні удару в ближньому бою.#Deals {1} to {2} damage", en="Mark of Detonation" },
    [22439] = { "Знак детонації", en="Mark of Detonation" },
    [22441] = { "Нестримне полум'я", en="Growing Flames" },
    [22442] = { "Нестримне полум'я", nil, "Завдає {1} шкоди кожні {2} c.#Deals {1} damage every {2} sec", en="Growing Flames" },
