    [22666] = { "Знемовлення", "Знемовлює ворога, унеможливлюючи вимову заклять протягом {1} с.#for {1} sec", "Не може вимовляти закляття.", en="Silence" },
    [22667] = { "Темний наказ", nil, "Причаровано!", en="Shadow Command" },
    [22678] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for {1} sec", "Втікає зі страху.", en="Fear" },
    [22682] = { "Тіньове полум'я", nil, "Від {1} до {2} шкоди щосекунди.#{1} to {2} damage", en="Shadow Flame" },
    [22686] = { "Дике ревіння", nil, "Втікає зі страху.", en="Bellowing Roar" },
    [22687] = { "Завіса тіні", "Зменшує ефективність зцілення цілі на {1}% протягом {2} с.#by {1}% for {2} sec", "Ефективність зцілення зменшено на {1}%.#reduced by {1}%", en="Veil of Shadow" },
    [22689] = { "Нівечення", "Завдає {1} шкоди ворогу кожні {2} с та зменшує швидкість його руху на {3}% протягом {4} с.#Inflicts {1} damage#every {2} sec#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.\nЗавдає {2} фізичної шкоди кожні {3} с.#reduced by {1}%#{2} Physical#every {3} sec", en="Mangle" },
    [22691] = { "Роззброєння", "Роззброює ворога, змушуючи його припинити використовувати зброю протягом {1} с.#weapon for {1} sec", "Не тримає в руках зброю.", en="Disarm" },
    [22692] = { "Скам'яніння", "Приголомшує ворога, але збільшує його броню на {1}% протягом {2} с.#by {1}% for {2} sec", "Приголомшено.\nБроню збільшено на {1}%.#by {1}%", en="Petrify" },
    [22703] = { "Ефект Пекла", nil, "Приголомшено.", en="Inferno Effect" },
    [22713] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [22717] = { "Чорний бойовий кінь", "Викликає та відпускає верхового чорного бойового коня. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black War Steed" },
    [22718] = { "Чорний бойовий кодо", "Викликає та відпускає верхового чорного бойового кодо. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black War Kodo" },
    [22719] = { "Чорний бойовий механобіг", "Викликає та відпускає верхового чорного бойового механобіга. Це дуже швидкий засіб пересування.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black Battlestrider" },
    [22720] = { "Чорний бойовий баран", "Викликає та відпускає верхового чорного бойового барана. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black War Ram" },
    [22721] = { "Чорний бойовий раптор", ref=16084, en="Black War Raptor" },
    [22722] = { "Червоний бойовий кінь-скелет", "Викликає та відпускає верхового червоного бойового коня-скелета. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Red Skeletal Warhorse" },
    [22723] = { "Чорний бойовий тигр", "Викликає та відпускає верхового чорного бойового тигра. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black War Tiger" },
    [22724] = { "Чорний бойовий вовк", "Викликає та відпускає верхового чорного бойового вовка. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Black War Wolf" },
    [22725] = { "Збільшення захисту", "Укріплення предмета, який носять на тілі, ногах, руках чи ступнях, що збільшить навичку захисту на {1}. Можна використовувати лише на предметах {2} рівня чи вище.#feet by {1}#level {2} and", en="Defense +3" },
    [22729] = { "Зілля омолодження", "Відновлює [{1}#Restores {1} mana][від {1} до {2}#Restores 90 to 150 mana] мани та здоров'я.", en="Rejuvenation Potion" },
    [22730] = { "Збільшення інтелекту", "Збільшує інтелект на {1} протягом {2} хв.#by {1} for {2} min", "Інтелект збільшено на {1}.#by {1}", en="Increased Intellect" },
    [22731] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [22734] = { "Напій", "Відновлює {1} мани протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1} mana over {2} sec", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Drink" },
    [22738] = { "Зменшення часу відновлення Перехоплення", "Зменшує час відновлення \"Перехоплення\" на {1} с.#Intercept ability by {1} sec", en="Intercept Cooldown Reduction" },
    [22739] = { "Гоблінська гармата-дракон", "Завдає [{1}#Deals {1} fire][від {1} до {2}#Deals {1} to {2} fire] шкоди вогнем протягом {1} с всім ворогам в конусі перед інженером. Це якщо вона не вибухне...#damage for {1} sec to all", en="Goblin Dragon Gun" },
    [22744] = { "Льодяні ланцюги", en="Chains of Ice" },
    [22745] = { "Льодяні ланцюги", en="Chains of Ice" },
    [22746] = { "Конус холоду", "Завдає шкоди від криги ворогам у конусі перед заклиначем та зменшує їх швидкість руху на {1} с.#for {1} sec", "Швидкість руху зменшено.", en="Cone of Cold" },
    [22751] = { "Лють Морозних Вовків", "Поки діє ефект, запас здоров'я збільшується на {1}%.#by {1}%", "Запас здоров'я збільшено на {1}%.#by {1}%", en="Fury of the Frostwolf" },
    [22756] = { "Заточування зброї - критичний удар", "Заточити зброю ближнього бою, щоб збільшити шанс критичного удару на {1}% протягом {2} хв.#weapon by {1}% for {2} min", en="Sharpen Weapon - Critical" },
    [22778] = { "Зменшення витрат Нівечення", "Зменшує витрати люті на здібність \"Нівечення\" на {1}.#reduced by {1}", en="Hamstring Rage Reduction" },
    [22779] = { "Точноціл Бізніка 247x128", "Оснащення лука або вогнепальної зброї прицілом, що збільшує ймовірність завдання удару на {1}%.#to hit by {1}%", en="Biznicks 247x128 Accurascope" },
    [22782] = { "Магівський обладунок", "Збільшує ваш опір усій магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять. Одночасно може бути активним лише один обладунок. Триває {3} хв.#magic by {1} and allows {2}%#Lasts {3} min", "Збільшує опір усім школам магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять.#by {1} and allows {2}%", en="Mage Armor" },
    [22783] = { "Магівський обладунок", "Збільшує ваш опір усій магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять. Одночасно може бути активним лише один обладунок. Триває {3} хв.#magic by {1} and allows {2}%#Lasts {3} min", "Збільшує опір усім школам магії на {1} і дозволяє {2}% вашого відновлення мани продовжуватися під час вимови заклять.#by {1} and allows {2}%", en="Mage Armor" },
    [22789] = { "Зелений ґордоцький грог", "Збільшує витривалість на {1} протягом {2} хвилин і добряче п'янить. Зелений - значить хороший!#Stamina by {1} for {2} min", "Витривалість збільшено на {1}.#by {1}", en="Gordok Green Grog" },
    [22790] = { "Вбивче пійло Кріґа", "Збільшує дух на {1}, але зменшує інтелект на {2} протягом {3} хв. До дна!#Spirit by {1}#Intelligence by {2} for {3} min", "Дух збільшено на {1}, а інтелект зменшено на {2}.#increased by {1} and#decreased by {2}.", en="Kreeg's Stout Beatdown" },
    [22799] = { "Король Ґордоків", "Ви король Ґордоків!  Добре бути королем...", "Ви король Ґордоків!  Добре бути королем...", en="King of the Gordok" },
    [22801] = { "Швидкість примарного вовка", "Збільшує швидкість \"Примарного вовка\" на {1}%.#ability by {1}%", en="Ghost Wolf Speed" },
    [22802] = { "Задушливі спори", nil, "Завдає від {1} до {2} шкоди від природи кожні {3} с.#Deals {1} to {2} nature#every {3} sec", en="Choking Spores" },
    [22807] = { "Глибше водне дихання", "Дозволяє дихати водою протягом {1} год.#for {1} h", "Водне дихання.", en="Greater Water Breathing" },
    [22811] = { "Збільшення навички володіння арбалетами", "Збільшує навичку володіння арбалетами на {1}.#Crossbows +{1}", en="Increased Crossbow" },
    [22812] = { "Дубова шкіра", "Шкіра друїда стає міцною, як кора. Отриману фізичну шкоду зменшено на {1}%. Поки триває захист, ворожі атаки не спричинять затримки вимови заклять, але закляття вимовляються на {2} с довше, а швидкість атаки ближнього бою зменшена на {3}%. Триває {4} с.#reduced by {1}#take {2} sec#slowed by {3}#Lasts {4} sec", "Отриману фізичну шкоду зменшено на {1}%. Поки триває захист, ворожі атаки не спричиняють затримки вимови заклять, але закляття вимовляються на {2} с довше, a швидкість атаки ближнього бою зменшена на {3}%.#reduced by {1}#take {2} sec#slowed by {3}%", en="Barkskin" },
    [22817] = { "Лють Фенґа", "Силу атаки збільшено на {1}.#increased by {1}", "Силу атаки збільшено на {1}.#increased by {1}", en="Fengus' Ferocity" },
    [22818] = { "Сміливість Мол'дара", "Витривалість збільшено на {1}%.#increased by {1}", "Витривалість збільшено на {1}%.#increased by {1}", en="Mol'dar's Moxie" },
    [22820] = { "Кмітливість Сліп'кіка", "Шанс критичного удару заклять збільшено на {1}%.#by {1}%", "Шанс критичного удару заклять збільшено на {1}%.#by {1}%", en="Slip'kik's Savvy" },
    [22827] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Ferocious Bite" },
    [22828] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Ferocious Bite" },
    [22829] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Ferocious Bite" },
    [22833] = { "Плювок пійлом", nil, "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Booze Spit" },
    [22836] = { "Вбивця елементалів", "Збільшує силу атаки на {1} в бою з елементалями.#+{1} Attack Power when fighting Elementals", en="Elemental Slaying 36" },
    [22840] = { "Магічний камінь прудкості", "Додати на поножі або головний убір чари, що збільшують швидкість на {1}%. Не поєднується з іншими чарами на предметі.#Permanently adds {1}% haste to", en="Arcanum of Rapidity" },
    [22842] = { "Шалене відновлення", "Перетворює до {1} люті щосекунди на здоров'я протягом {2} с. Кожна одиниця люті перетворюється на {3} здоров'я.#up to {1} rage#for {2} sec#into {3} health", "Перетворює лють на здоров'я.", en="Frenzied Regeneration" },
    [22843] = { "Магічний камінь зосередження", ref=9342, en="Arcanum of Focus" },
    [22844] = { "Магічний камінь зосередження", "Додати на поножі або головний убір чари, що збільшують шкоду і зцілення заклинань на {1}. Не поєднується з іншими чарами на предметі.#Permanently adds +{1} to your Healing and Damage", en="Arcanum of Focus" },
    [22846] = { "Магічний камінь захисту", "Додати на поножі або головний убір чари, що збільшують ймовірність ухилення на {1}%. Не поєднується з іншими чарами на предметі.#Permanently adds {1}% dodge", en="Arcanum of Protection" },
    [22850] = { "Прихисток", "Збільшує навичку захисту на {1}, а броню - на {2} протягом {3} с.#wielder {1} defense and {2} armor for {3} sec", "Броню збільшено на {1}.\nНавичку захисту збільшено на {2}.#Armor increased by {1}.#Defense increased by {2}.", en="Sanctuary" },
    [22859] = { "Смертельне розсічення", ref=13737, en="Mortal Cleave" },
    [22863] = { "Швидкість", "Збільшує швидкість бігу на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість бігу збільшено на {1}%.#by {1}%", en="Speed" },
    [22884] = { "Психічний крик", "Вивільнює психічний крик, що змушує до {1} навколишніх ворогів тікати геть протягом {2} с.#up to {1} nearby#for {2} sec", "Втікає зі страху.", en="Psychic Scream" },
    [22888] = { "Рвучкий клич драконоборця", "Збільшує шанс критичного удару заклять на {1}%, атак ближнього та дальнього бою на {2}% та збільшує силу атаки на {3}. Триває {4} хв.#spells by {1}%#ranged by {2}%#grants {3} attack#{4} min", "Збільшує шанс критичного удару заклять на {1}%, атак ближнього та дальнього бою на {2}% та збільшує силу атаки на {3}. Триває {4} хв.#spells by {1}%#ranged by {2}%#grants {3} attack#{4} min", en="Rallying Cry of the Dragonslayer" },
    [22911] = { "Ривок", "Ривок у ворога, що завдає звичайної шкоди плюс {1} та приголомшує ціль на {2} с.#plus {1} and#for {2} sec", en="Charge" },
    [22914] = { "Запаморочливий постріл", "Паморочить ціль, зменшуючи її швидкість руху на {1}% протягом {2} с.#by {1}% for {2} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Concussive Shot" },
    [22919] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [22937] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Bolt" },
    [22948] = { "Хмара спор", nil, "Завдає від {1} до {2} шкоди протягом {3} с.#Deals {1} to {2} damage over {3} sec", en="Spore Cloud" },
    [22959] = { "Вразливість до вогню", nil, "Збільшує отриману шкоду від вогню на {1}%.#by {1}%", en="Fire Vulnerability" },
