    [22996] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що збільшує максимальний запас здоров'я всіх дружніх цілей в межах {1} м від нього на {2}%. Триває {3} хв.#within {1} y#by {2}%#Lasts {3} min", en="Battle Standard" },
    [22997] = { "Чума", nil, "Завдає шкоди від природи кожні {1} с.\nПеріодично завдає шкоди від природи навколишнім учасникам групи.#every {1} sec", en="Plague" },
    [22998] = { "Бойовий штандарт", nil, "Збільшує максимальний запас здоров'я на {1}%.#by {1}%", en="Battle Standard" },
    [22999] = { "Дефібриляція", "Кабельний дефібрилятор іноді може повернути до життя мертвого гравця. Не можна використовувати під час бою.", en="Defibrillate" },
    [23000] = { "Динаміт \"Простокид\"", "Завдає [{1}#Inflicts {1} Fire][від {1} до {2}#Inflicts {1} to {2} Fire] шкоди вогнем в радіусі {1} м. (За умови досягнення цілі, можуть накладатись деякі обмеження.)#in a {1} yard", en="Ez-Thro Dynamite" },
    [23004] = { "Виклик тривого-бота", "Викликає на {1} хв тривого-бота, який час від часу випромінює імпульс, що виявляє непомітних або невидимих ворогів неподалік.#for {1} min", en="Summon Alarm-o-Bot" },
    [23005] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що збільшує максимальний запас здоров'я всіх дружніх цілей в межах {1} м від нього на {2}%. Триває {3} хв.#within {1} y#by {2}%#Lasts {3} min", en="Battle Standard" },
    [23006] = { "Бойовий штандарт", nil, "Збільшує максимальний запас здоров'я на {1}%.#by {1}%", en="Battle Standard" },
    [23008] = { "Потужний сифорієвий заряд", "Підриває майже будь-які замки.", en="Powerful Seaforium Charge" },
    [23014] = { "Одержимість", nil, "Одержимість.", en="Possess" },
    [23023] = { "Розпалення", "Підпалює ворога, завдаючи {1} шкоди вогнем протягом {2} с і викликаючи у нього паніку. Поки ефект діє на ціль, полум'я періодично обпалює її союзників неподалік, завдаючи їм {3} шкоди.#inflicting {1} Fire damage over {2} sec#allies for {3} damage", "Ви горите!", en="Conflagration" },
    [23028] = { "Арканічна геніальність", "Сповнює групу цілі геніальністю, збільшуючи інтелект усіх її учасників на {1} протягом {2} год.#by {1} for {2} h", "Збільшує інтелект на {1}.#by {1}", en="Arcane Brilliance" },
    [23033] = { "Бойовий штандарт", nil, "Збільшує максимальний запас здоров'я на {1}%.#by {1}%", en="Battle Standard" },
    [23034] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що має {1} здоров'я та збільшує максимальний запас здоров'я всіх учасників групи в межах {2} м від бойового штандарту на {3}%. Триває {4} хв. Бойовий штандарт можна застосовувати лише на полях битви.#with {1} health#within {2} y#by {3}%#Lasts {4} min", en="Battle Standard" },
    [23035] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що має {1} здоров'я та збільшує максимальний запас здоров'я всіх учасників групи в межах {2} м від бойового штандарту на {3}%. Триває {4} хв. Бойовий штандарт можна застосовувати лише на полях битви.#with {1} health#within {2} y#by {3}%#Lasts {4} min", en="Battle Standard" },
    [23036] = { "Бойовий штандарт", nil, "Збільшує максимальний запас здоров'я на {1}%.#by {1}%", en="Battle Standard" },
    [23037] = { "Поглинання щщита мани", "Збільшує обсяг шкоди, яку може поглинути \"Щит мани\", на {1}.#Mana Shield by {1}", en="Mana Shield Absorb Increase" },
    [23038] = { "Вогняний шок", "Обпалює ворога, завдаючи шкоди вогнем кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Отримання шкоди від вогню кожні {1} с.#every {1} sec", en="Flame Shock" },
    [23039] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [23043] = { "Зменшення затримки вимови вибуху розуму", "З ймовірністю {1}% ви уникнете затримки вимови закляття \"Вибух розуму\" при отриманні шкоди.#a {1}% chance to avoid", en="Mind Blast Cast Pushback Reduction" },
    [23046] = { "Зменшення затримки вимови палючого болю", "З ймовірністю {1}% ви уникнете затримки вимови закляття \"Палючий біль\" при отриманні шкоди.#a {1}% chance to avoid", en="Searing Pain Cast Pushback Reduction" },
    [23049] = { "Збільшення тривалості Спринту", "Збільшує тривалість здібності \"Спринт\" на {1} с.#ability by {1} sec", en="Sprint Duration Increase" },
    [23060] = { "Бойовий клекіт", nil, "Швидкість атаки збільшено на {1}%.#by {1}%", en="Battle Squawk" },
    [23063] = { "Масивний динаміт", ref=1940, en="Dense Dynamite" },
    [23064] = { "Рекомбобуляція", "Розвіює ефекти поліморфії з дружньої цілі. Також відновлює від {1} до {2} здоров'я та мани.#restores {1} to {2} health", en="Recombobulate" },
    [23065] = { "Кидок каменя", "Кинути камінчик в дружнього гравця. Якщо у цілі є вільне місце в сумках - вона піймає його!", en="Throw Rock" },
    [23074] = { "Арканітове драконеня", "Активувати арканітове драконеня, що битиметься за вас протягом {1} хв. Перш ніж його можна буде використати знову, йому потрібно відновитись протягом години.#fight for you for {1} min", en="Arcanite Dragonling" },
    [23075] = { "Мітрилове механічне драконеня", "Активувати мітрилове механічне драконеня, що битиметься за вас протягом {1} хв. Перш ніж його можна буде використати знову, йому потрібно відновитись протягом години.#fight for you for {1} min", en="Mithril Mechanical Dragonling" },
    [23076] = { "Механічне драконеня", "Активувати механічне драконеня, що битиметься за вас протягом {1} хв. Перш ніж його можна буде використати знову, йому потрібно відновитись протягом години.#fight for you for {1} min", en="Mechanical Dragonling" },
    [23097] = { "Відбивання вогню", "Відбиває закляття вогню в заклиначів протягом {1} с.#caster for {1} sec", "Відбиває закляття вогню.", en="Fire Reflector" },
    [23099] = { "Порив", "Збільшує швидкість руху на {1}% протягом {2} с.#by {1}% for {2} sec", "Збільшує швидкість руху на {1}%.#by {1}", en="Dash" },
