    [23537] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}%, а завдану фізичну шкоду на {2}-{3} протягом {4} хв.#speed by {1}%#by {2} to {3} for {4} min", "Фізичну шкоду збільшено на {1}-{2}.\nШвидкість атаки збільшено на {3}%.#by {1} to {2}#by {3}%", en="Enrage" },
    [23538] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що має {1} здоров'я та збільшує шкоду всіх учасників групи в межах {2} м від бойового штандарту на {3}%. Триває {4} хв. Бойовий штандарт можна застосовувати лише в Альтерацькій долині.#with {1} health#within {2} y#by {3}%#Lasts {4} min", en="Battle Standard" },
    [23539] = { "Бойовий штандарт", "Розмістити бойовий штандарт, що має {1} здоров'я та збільшує шкоду всіх учасників групи в межах {2} м від бойового штандарту на {3}%. Триває {4} хв. Бойовий штандарт можна застосовувати лише в Альтерацькій долині.#with {1} health#within {2} y#by {3}%#Lasts {4} min", en="Battle Standard" },
    [23540] = { "Покращений пайок з тіснини Пісні Війни", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Можна використовувати лише в тіснині Пісні Війни.#Restores {1} health and {2} mana over {3} sec", "Відновлює {1} здоров'я та {2} мани щосекунди.#Restores {1} health and {2} mana", en="Warsong Gulch Enriched Ration" },
    [23541] = { "Пайок з тіснини Пісні Війни", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Можна використовувати лише в тіснині Пісні Війни.#Restores {1} health and {2} mana over {3} sec", en="Warsong Gulch Iron Ration" },
