    [23567] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в тіснині Пісні Війни.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [23568] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в тіснині Пісні Війни.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [23569] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в тіснині Пісні Війни.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [23573] = { "Ланцюгова хвиля зцілення", "Ваша \"Хвиля зцілення\" також перестрибує на цілі неподалік, з кожним стрибком зцілюючи на {1}% менше. Максимум до двох стрибків.#jump reduces the effectiveness of the heal by {1}%", en="Chain Healing Wave" },
