    [23989] = { "Готовність", "При активації миттєво завершує відновлення ваших здібностей \"Стримування\", \"Удавання мертвого\" та пасток.", en="Readiness" },
    [23990] = { "Предмет - збільшення швидкості бігу", "Трохи збільшує швидкість бігу.", en="Item - Minor Run Speed" },
    [23991] = { "Поглинання шкоди", "Поглинає [{1}#Absorbs {1} physical][від {1} до {2}#Absorbs {1} to {2} physical] фізичної шкоди. Триває {1} с.#Lasts {1} sec", "Поглинає [{1}#Absorbs {1} physical][від {1} до {2}#Absorbs {1} to {2} physical] фізичної шкоди.", en="Damage Absorb" },
    [23992] = { "Опір вогню", "Збільшує опір вогню на {1}.#by {1}", "Збільшує опір вогню на {1}.#by {1}", en="Fire Resistance" },
    [24002] = { "Заспокійлива отрута", nil, "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.\nПозбавляє {3} люті щосекунди.\nХочеться спати...#increased by {1}%#speed by {2}%#Drains {3} rage", en="Tranquilizing Poison" },
    [24003] = { "Заспокійлива отрута", nil, "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.\nПозбавляє {3} люті щосекунди.\nХочеться спати...#increased by {1}%#speed by {2}%#Drains {3} rage", en="Tranquilizing Poison" },
    [24004] = { "Сон", nil, "Спить.", en="Sleep" },
    [24005] = { "Їжа", "Відновлює {1}% здоров'я щосекунди протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1}% of#for {2} sec", "Відновлює {1}% здоров'я щосекунди.#Restores {1}%", en="Food" },
    [24011] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [24018] = { "Шквал сокир", "Атакує навколишніх ворогів шквалом сокир протягом {1} с.#lasts {1} sec", "Атакує навколишніх ворогів.", en="Axe Flurry" },
    [24019] = { "Шквал сокир", en="Axe Flurry" },
    [24020] = { "Шквал сокир", nil, "Приголомшено.", en="Axe Flurry" },
    [24048] = { "Вихровий оберт", "Завдає навколишнім ворогам звичайної шкоди плюс {1}.#plus {1} to", "Приголомшено.", en="Whirling Trip" },
    [24049] = { "Пронизування", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає від {1} до {2} шкоди кожні {3} с.#{1} to {2} damage#every {3} sec", en="Impale" },
    [24053] = { "Пристріт", "Перетворює ворога на жабу, позбавляючи його можливості атакувати та застосовувати заклинання протягом {1} с.#for {1} sec", "Зурочено.", en="Hex" },
    [24054] = { "Зменшення", "Зменшує силу ворога на {1}, а витривалість - на {2} протягом {3} хв.#Strength by {1}#Stamina by {2} for {3} min", "Силу зменшено на {1}.\nВитривалість зменшено на {2}.#Strength reduced by {1}#Stamina reduced by {2}", en="Shrink" },
    [24063] = { "Хвороботворна хмара", nil, "Завдає від {1} до {2} шкоди щосекунди.#Deals {1} to {2} damage", en="Disease Cloud" },
    [24071] = { "Шквал сокир", en="Axe Flurry" },
    [24090] = { "Крихітне збільшення швидкості руху", "Трохи збільшує швидкість бігу та плавання.", en="Minor Movement Speed" },
    [24097] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [24099] = { "Залп отруйних стріл", ref=21067, en="Poison Bolt Volley" },
    [24110] = { "Огортаюча павутина", ref=15471, en="Enveloping Webs" },
    [24111] = { "Їдка отрута", "Зменшує броню ворога на {1} та завдає від {2} до {3} шкоди від природи кожні {4} с протягом {5} с.#armor by {1} and inflicts {2} to {3} Nature#every {4} sec#for {5} sec", "Від {1} до {2} шкоди від природи кожні {3} с.\nБроню зменшено на {4}.#{1} to {2} Nature#every {3} sec#reduced by {4}", en="Corrosive Poison" },
    [24149] = { "Явлення могутності", "Додати на поножі або головний убір чари, що збільшують витривалість на {1}, навичку захисту на {2} та показник блокування щитом на {3}. Не поєднується з іншими чарами на предметі.#{1} Stamina#{2} Defense#and {3} Shield Block", en="Presence of Might" },
    [24160] = { "Сигіла синкретиста", "Додати на поножі або головний убір чари, що збільшують витривалість на {1}, навичку захисту на {2} та зцілення на {3}. Не поєднується з іншими чарами на предметі.#{1} Stamina#{2} Defense#healing by up to {3}", en="Syncretist's Sigil" },
    [24161] = { "Обійми смерті", "Додати на поножі або головний убір чари, що збільшують силу атаки на {1} та ймовірність ухилення на {2}%. Не поєднується з іншими чарами на предметі.#adds {1} Attack#and {2}% Dodge", en="Death's Embrace" },
    [24162] = { "Поклик сокола", "Додати на поножі або головний убір чари, що збільшують силу атаки дальнього бою на {1}, витривалість на {2} та ймовірність завдання удару на {3}%. Не поєднується з іншими чарами на предметі.#adds {1} Ranged#{2} Stamina#and {3}% Chance to Hit", en="Falcon's Call" },
    [24163] = { "Палкі обійми вуду", "Додати на поножі або головний убір чари, що збільшують шкоду та зцілення від заклинань на {2} та інтелект на {1}. Не поєднується з іншими чарами на предметі.#adds {1} Intellect#damage by up to {2}", en="Vodouisant's Vigilant Embrace" },
    [24164] = { "Явлення прозріння", "Додати на поножі або головний убір чари, що збільшують шкоду та зцілення від заклинань на {1} та ймовірність завдання удару заклинаннями на {2}%. Не поєднується з іншими чарами на предметі.#adds {1} to all#and {2}% chance", en="Presence of Sight" },
    [24165] = { "Чари худу", "Додати на поножі або головний убір чари, що збільшують шкоду та зцілення від заклинань на {2} та витривалість на {1}. Не поєднується з іншими чарами на предметі.#adds {1} Stamina#healing by up to {2} to", en="Hoodoo Hex" },
    [24167] = { "Віщунська аура", "Додати на поножі або головний убір чари, що збільшують витривалість на {1}, відновлення мани на {2} кожні {3} с та зцілення на {4}. Не поєднується з іншими чарами на предметі.#adds {1} Stamina#{2} mana per {3} sec#healing by up to {4}", en="Prophetic Aura" },
    [24168] = { "Ласка аніміста", "Додати на поножі або головний убір чари, що збільшують витривалість на {1}, інтелект на {2} та зцілення на {3}. Не поєднується з іншими чарами на предметі.#adds {1} Stamina#{2} Intellect#healing by up to {3}", en="Animist's Caress" },
    [24178] = { "Воля Гаккара", "Бере під контроль гуманоїда до {1} рівня на {2} с.#level {1} for {2} sec", "Гаккар правитиме світом!", en="Will of Hakkar" },
    [24192] = { "Стрімке розсічення", nil, "Завдає від {1} до {2} шкоди щосекунди.#Deals {1} to {2} damage", en="Speed Slash" },
    [24193] = { "Ривок", "Ривок у ворога, що завдає звичайної шкоди плюс {1} та приголомшує ціль на {2} с.#plus {1} and#for {2} sec", en="Charge" },
    [24198] = { "Руна Світанку", "Збільшує шкоду від магічних заклинань і ефектів в бою з невмерлими на {1}. Також дозволяє отримувати камені Скари для Сріблястого Світанку.#up to {1}", en="Rune of the Dawn" },
    [24210] = { "Знак Арлокк", nil, "Ціль прислужників Арлокк.", en="Mark of Arlokk" },
    [24212] = { "Слово тіні: Біль", "Вимовляє слово темряви, що завдає ворогу шкоди тінню кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від тіні кожні {1} с.#every {1} sec", en="Shadow Word: Pain" },
    [24213] = { "Знищення", "Завдає ворогу звичайної шкоди плюс {1} та приголомшує його на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Ravage" },
    [24236] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [24239] = { "Молот гніву", "Кидає у ворога молот, що завдає від {1} до {2} шкоди святістю. Можна застосовувати лише проти ворогів, у яких не більше {3}% здоров'я.#for {1} to {2}#have {3}", en="Hammer of Wrath" },
    [24241] = { "Рубання кінцівки", "Намагається відрубати кінцівку цілі, завдаючи [{1}#causing {1} damage][від {1} до {2}#causing {1} to {2} damage] шкоди.", en="Decapitate" },
    [24242] = { "Стрімкий раптор Раззаші", ref=16084, en="Swift Razzashi Raptor" },
    [24244] = { "Ріст", nil, "Всі виросли.", en="Grow" },
    [24248] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Copy of Ferocious Bite" },
    [24251] = { "Зуліанський тесак", "Розрізає ворога, завдаючи йому [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Zulian Slice" },
    [24252] = { "Стрімкий зуліанський тигр", "Викликає та відпускає верхового тигра. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Swift Zulian Tiger" },
    [24254] = { "Шипіння змії", "Вражає ціль отрутою, завдаючи [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Serpent's Hiss" },
    [24257] = { "Нищівний удар Жеклік", ref=13486, en="Jeklik's Crushing Blow" },
    [24259] = { "Заборона чар", nil, "Знемовлено.", en="Spell Lock" },
    [24261] = { "Промивка мізків", nil, "Причаровано.", en="Brain Wash" },
    [24268] = { "Мізкостимуляція Мар'лі", ref=19634, en="Mar'li's Brain Boost" },
    [24274] = { "Молот гніву", "Кидає у ворога молот, що завдає від {1} до {2} шкоди святістю. Можна застосовувати лише проти ворогів, у яких не більше {3}% здоров'я.#for {1} to {2}#have {3}", en="Hammer of Wrath" },
    [24275] = { "Молот гніву", "Кидає у ворога молот, що завдає від {1} до {2} шкоди святістю. Можна застосовувати лише проти ворогів, у яких не більше {3}% здоров'я.#for {1} to {2}#have {3}", en="Hammer of Wrath" },
    [24291] = { "Вбивця драконів {1}#Dragon Slaying {1}", "Збільшує силу атаки на {1} в бою з драконами.#+{1} Attack Power when fighting Dragonkin", en="Dragon Slaying 48" },
    [24294] = { "Знищення монстрів", "Збільшує всю шкоду проти звірів, велетнів та драконів на {1}%, а критичну шкоду проти звірів, велетнів та драконів додатково на {2}%.#targets by {1}#additional {2}", en="Monster Slaying" },
    [24295] = { "Знищення монстрів", "Збільшує всю шкоду проти звірів, велетнів та драконів на {1}%, а критичну шкоду проти звірів, велетнів та драконів додатково на {2}%.#targets by {1}#additional {2}", en="Monster Slaying" },
    [24300] = { "Висмоктування життя", "Висмоктує {1} здоров'я з ворога протягом {2} с, передаючи його заклиначу.#Drains {1} health#over {2} sec", "Висмоктування {1} здоров'я протягом {2} с.#{1} health#over {2} sec", en="Drain Life" },
    [24306] = { "Марення Джин'до", nil, "Завдає від {1} до {2} шкоди кожні {3} с.\nВ очах ріже...#Deals {1} to {2} damage every {3} sec", en="Delusions of Jin'do" },
    [24314] = { "Загрозливий погляд", nil, "Повелитель крові Мандокір уважно стежить за вами...", en="Threatening Gaze" },
    [24317] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [24318] = { "Несамовитість", "Збільшує швидкість атаки заклинача на {1}% та збільшує фізичну шкоду на {2} протягом {3} хв.#speed by {1}%#deals by {2} for {3} min", "Фізичну шкоду збільшено на {1}.\nШвидкість атаки збільшено на {2}%.#dealt is increased by {1}#speed increased by {2}%", en="Enrage" },
    [24320] = { "Отруйна кров", en="Poisonous Blood" },
    [24321] = { "Отруйна кров", nil, "Завдає {1} шкоди кожні {2} c.#Deals {1} damage every {2} sec", en="Poisonous Blood" },
    [24322] = { "Висмоктування крові", nil, "Завдає {1} шкоди щосекунди.\nВідновлює Гаккару {2} здоров'я щосекунди.#Deals {1} damage#Hakkar {2} health", en="Blood Siphon" },
    [24323] = { "Висмоктування крові", nil, "Ваша кров отруйна!\nЗавдає Гаккару {1} шкоди щосекунди.#Dealing {1} damage", en="Blood Siphon" },
    [24324] = { "Висмоктування крові", en="Blood Siphon" },
    [24327] = { "Зведення з розуму", "Тимчасово зводить ворожу ціль з розуму, прискорюючи її атаку на {1}% та рух на {2}%, а також змушує її атакувати своїх союзників протягом {3} с.#attacks by {1}%#movement by {2}%#for {3} sec", "Причаровано.\nШвидкість атаки збільшено на {1}%.\nШвидкість руху збільшено на {2}%.#Attack speed increased by {1}%#Movement speed increased by {2}%", en="Cause Insanity" },
    [24331] = { "Розрив", "Рве ціль, завдаючи від {1} до {2} шкоди та додатково {3} шкоди протягом {4} с.#for {1} to {2} damage#additional {3} damage over {4} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [24332] = { "Розрив", "Рве ціль, завдаючи від {1} до {2} шкоди та додатково {3} шкоди протягом {4} с.#for {1} to {2} damage#additional {3} damage over {4} sec", "{1} шкоди від кровотечі кожні {2} с.#for {1} damage every {2} sec", en="Rake" },
    [24333] = { "Знищення", "Завдає ворогу звичайної шкоди плюс {1} та приголомшує його на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="Ravage" },
    [24335] = { "Жало виверни", "Постріл, що жалить ціль та занурює її в сон на {1} с. Будь-яка шкода пробудить ціль. Коли ціль прокинеться, жало завдасть від {2} до {3} шкоди від природи протягом {4} с.#sleep for {1} sec#causes {2} to {3} Nature#over {4} sec", "Спить.", en="Wyvern Sting" },
    [24336] = { "Жало виверни", nil, "Від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Wyvern Sting" },
    [24339] = { "Інфікований укус", "Завдає шкоди від природи ворогу кожні {1} с та збільшує отриману ним фізичну шкоду на {2} хв.#every {1} sec#for {2} min", "Завдає {1} шкоди від природи кожні {2} с.\nОтриману фізичну шкоду збільшено на {3}.#{1} nature#every {2} sec#taken by {3}", en="Infected Bite" },
    [24354] = { "Благословення молитовних намистин", "Збільшує зцілення від заклинань і ефектів на {1} протягом {2} с.#healing done by spells and effects by up to {1} for {2} sec", "Зцілення від заклинань і ефектів збільшено на {1}.#to {1}", en="Prayer Beads Blessing" },
    [24355] = { "Напій", "Відновлює {1}% мани щосекунди протягом {2} с. Потрібно залишатися в сидячому положенні під час пиття.#Restores {1}% of#for {2} sec", "Відновлює {1}% мани щосекунди.#Restores {1}% of your", en="Drink" },
    [24360] = { "Великий сон без сновидінь", ref=15822, en="Greater Dreamless Sleep" },
    [24361] = { "Регенерація", "Відновлює {1} здоров'я кожні {2} с протягом {3} год.#{1} health every {2} sec for {3} h", "Відновлює {1} здоров'я кожні {2} с.#{1} health every {2} sec", en="Regeneration" },
    [24363] = { "Регенерація мани", "Відновлює {1} мани кожні {2} с протягом {3} год.#{1} mana per {2} sec for {3} h", "Відновлення {1} мани кожні {2} с.#{1} mana per {2} sec", en="Mana Regeneration" },
    [24364] = { "Нестримність", "Надає невразливість до приголомшення та ефектів обмеження руху на наступні {1} с. Також знімає вже наявні ефекти.#next {1} sec", "Нестримність.", en="Living Free Action" },
    [24374] = { "Вогняна куля", "Завдає шкоди від вогню ворогу.", en="Fireball" },
    [24375] = { "Бойовий тупіт", "Завдає звичайної шкоди плюс {1} навколишнім ворогам, відкидаючи їх та приголомшуючи на {2} с.#plus {1} to#for {2} sec", "Приголомшено.", en="War Stomp" },
    [24378] = { "Берсерк", nil, "Збільшує завдану шкоду на {1}%, але збільшує отриману шкоду на {2}%.#caused by {1}%#taken by {2}%", en="Berserking" },
    [24379] = { "Відновлення", nil, "Відновлює здоров'я, ману та щастя вихованця.", en="Restoration" },
    [24382] = { "Дух Занзи", "Збільшує дух на {1} та витривалість на {2} протягом {3} год. Одночасно ви можете перебувати під дією лише одного напою Занзи.#Spirit by {1} and Stamina by {2} for {3} hrs", "Дух збільшено на {1}, а витривалість на {2}.#by {1} and Stamina by {2}", en="Spirit of Zanza" },
    [24383] = { "Прудкість Занзи", "Збільшує швидкість бігу на {1}% протягом {2} год. Одночасно ви можете перебувати під дією лише одного напою Занзи.#speed by {1}% for {2} hrs", "Швидкість бігу збільшено на {1}%.#by {1}%", en="Swiftness of Zanza" },
    [24384] = { "Сутнє манго", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health and {2} mana over {3} sec", en="Essence Mango" },
    [24388] = { "Пошкодження мозку", ref=17148, en="Brain Damage" },
    [24389] = { "Хаотичний вогонь", "Відновлює від {1} до {2} мани та збільшує шкоду наступного вогняного закляття на {3}. Ефект триває {4} хв.#Restores {1} to {2} mana#up to {3}#for {4} min", "Шкоду наступного вогняного закляття збільшено на {1}.#up to {1}", en="Chaos Fire" },
    [24392] = { "Крижаний заряд", "\"Крижана стріла\" з ймовірністю {1}% відновить вам {2} мани при використанні.#a {1}% chance to restore {2} mana", en="Frosty Zap" },
    [24394] = { "Залякування", nil, "Приголомшено.", en="Intimidation" },
    [24408] = { "Ривок", "Ривок у ворога, що завдає звичайної шкоди плюс {1} та приголомшує ціль на {2} с.#plus {1} and#for {2} sec", en="Charge" },
    [24409] = { "Польовий пайок низини Араті", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Можна використовувати лише в низині Араті.#Restores {1} health and {2} mana over {3} sec", en="Arathi Basin Field Ration" },
    [24410] = { "Пайок низини Араті", nil, "Відновлює {1} здоров'я та {2} мани щосекунди.#Restores {1} health and {2} mana", ref=24409, en="Arathi Basin Iron Ration" },
    [24411] = { "Покращений пайок низини Араті", ref=24410, en="Arathi Basin Enriched Ration" },
    [24412] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в низині Араті.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [24413] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в низині Араті.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [24414] = { "Перша допомога", "Відновлює {1} здоров'я за {2} с. Можна використовувати лише в низині Араті.#Heals {1} damage over {2} sec", "Відновлення {1} здоров'я кожні {2} с.#Healing {1} damage every {2} sec", en="First Aid" },
    [24415] = { "Сповільнення", "Збільшує інтервал між атаками навколишніх ворогів на {1}%, зменшує їх швидкість руху на {2}% та сповільнює вимову заклять на {3}% протягом {4} с.#attacks by {1}%#movement by {2}%#speed by {3}% for {4} sec", "Інтервал між атаками збільшено на {1}%.\nШвидкість руху зменшено на {2}%.\nВимову заклять сповільнено на {3}%.#increased by {1}%#Movement speed reduced by {2}%#Casting speed reduced by {3}%", en="Slow" },
    [24417] = { "Лиск Занзи", "Збільшує ймовірність відбити ворожі закляття на {1}% протягом {2} год. Гарантовано відбиває перше вороже закляття. Одночасно ви можете перебувати під дією лише одного напою Занзи.#them by {1}% for {2} hrs", "Відбиває ворожі закляття з ймовірністю {1}%.#reflected {1}%", en="Sheen of Zanza" },
    [24420] = { "Печатка спокою Зандаларів", "Накласти на наплічники чари, що збільшують зцілення від заклинань і ефектів на {1}.#up to {1}", en="Zandalar Signet of Serenity" },
    [24421] = { "Печатка моджо Зандаларів", "Накласти на наплічники чари, що збільшують шкоду і зцілення від магічних заклинань і ефектів на {1}.#up to {1}", en="Zandalar Signet of Mojo" },
    [24422] = { "Печатка могутності Зандаларів", "Накласти на наплічники чари, що збільшують силу атаки на {1}.#adds {1} attack", en="Zandalar Signet of Might" },
    [24425] = { "Дух Зандаларів", "Збільшує швидкість руху на {1}% та всі характеристики на {2}% протягом {3} год.#speed by {1}% and all stats by {2}% for {3} h", "Збільшує швидкість руху на {1}% та всі характеристики на {2}% протягом {3} год.#speed by {1}% and all stats by {2}% for {3} h", en="Spirit of Zandalar" },
