    [24694] = { "Сила атаки в подобі звіра", "Збільшує силу атаки на {1} в подобі кота, ведмедя та лютого ведмедя.#+{1} Attack Power in Cat", en="Attack Power - Feral (+574)" },
    [24698] = { "Ошелешення", "Завдає ворогу {1} шкоди та приголомшує його на {2} с. Ви автоматично перестанете атакувати. Ціль має бути повернута до вас. Будь-яка шкода перериває дію ефекту на цілі.#Inflicts {1} damage#for up to {2} sec", "Недієздатність.", en="Gouge" },
    [24705] = { "Закликання Плетеного чоловічка", "Прискорює відновлення здоров'я та мани на {1}% і витривалість на {2}%. Триває {3} год.# regeneration by {1}%#Stamina by {2}%#Lasts {3} hr", "Прискорює відновлення здоров'я та мани на {1}% і витривалість на {2}%. Триває {3} год.# regeneration by {1}%#Stamina by {2}%#Lasts {3} hr", en="Invocation of the Wickerman" },
