    [24800] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [24818] = { "Отруйне дихання", nil, "Завдає від {1} до {2} шкоди кожні {3} с.\nЧас відновлення здібностей збільшено на {4} с.#Deals {1} to {2} damage every {3} sec#by {4} sec", en="Noxious Breath" },
    [24833] = { "Священний камінь сили", "Розбити священний камінь сили, щоб отримати {1} сили атаки і збільшити шкоду від заклинань і ефектів святості на {2} в бою з невмерлими. Триває {3} хв.#granting {1} Attack#by up to {2} when#Lasts {3} min", "Силу атаки збільшено на {1}, а шкоду від заклять і ефектів святості на {2} в бою з невмерлими.#+{1} Attack Power#up to {2} when", en="Holy Mightstone" },
    [24839] = { "Кислотний подих", "Завдає {1} шкоди від природи та додатково від {2} до {3} шкоди кожні {4} с ворогам у конусі перед заклиначем. Триває {5} с.#Inflicts {1} Nature#additional {2} to {3} damage every {4} sec#Lasts {5} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Acid Breath" },
    [24840] = { "Отруйна хмара", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} с.#Inflicts {1} Nature#every {2} sec#for {3} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Poison Cloud" },
    [24844] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [24853] = { "Джерело мани", nil, "Відновлює {1} мани кожні {2} с.#Gain {1} mana every {2} sec", en="Mana Spring" },
    [24858] = { "Подоба місячного совуха", "Надає друїдові подоби місячного совуха, що збільшує вашу броню від предметів на {1}%[, зменшує витрати мани закляття \"Місячний вогонь\" на {1}% та збільшує його шкоду на {2}%, ваші закляття періодичної шкоди можуть завдавати критичної шкоди, шкода ваших заклять збільшується на {3}#costs {1}% less mana and deals {2}% more damage over time, your periodic damage spells can deal critical periodic damage, you gain {3} spell], а ймовірність критичного удару заклять учасників групи в радіусі {2} м збільшується на {3}%. У подобі місячного совуха [можна використовувати лише закляття спеціалізації \"Баланс\"#can only cast Balance spells][не можна використовувати цілющі закляття#cannot cast healing spells].[ Вся загроза від заклять аркани та природи зменшується на {1}% в цій подобі.#threat from Arcane and Nature spells by {1}% while]\n\nЗміна подоби звільняє заклинача від ефектів поліморфії та ефектів обмеження руху.#items is increased by {1}#within {2} yards#chance increased by {3}%", "Невразливість до ефектів поліморфії. Броня від предметів збільшена {1}%.#by {1}", en="Moonkin Form" },
    [24865] = { "Освячена сфера", "Збільшує ймовірність завдання критичного удару закляттями та атаками ближнього бою на {1}%. Триває {2} с.#attacks by {1}%#Lasts {2} sec", "Ймовірність завдання критичного удару закляттями та атаками ближнього бою збільшено на {1}%.#by {1}%", en="Sanctified Orb" },
    [24869] = { "Їжа", "Відновлює {1}% здоров'я щосекунди протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі. Через 10 секунд ви насититесь і ваші витривалість та дух збільшаться на {3} хв#Restores {1}% of#for {2} sec#Spirit for {3} min", "Відновлює {1}% здоров'я щосекунди.#Restores {1}%", en="Food" },
