    [24977] = { "Рій комах", "Ворожу ціль оточують комахи, зменшуючи її ймовірність поцілити на {1}% і завдаючи {2} шкоди від природи протягом {3} с.#hit by {1}#causing {2} Nature damage over {3} sec", "Зменшує ймовірність завдання удару на {1}% та завдає {2} шкоди від природи кожні {3} с.#by {1}% and {2}#every {3} sec", en="Insect Swarm" },
    [24988] = { "Виклик малюка-мурлока", en="Summon Baby Murloc (White)" },
    [24993] = { "Кислотний удар", "Вражає ціль кислотою, завдаючи [{1}#for {1} Nature][від {1} до {2}#for {1} to {2} Nature] шкоди від природи.", en="Acid Blast" },
    [24998] = { "Зцілення віків", "Збільшує зцілення від магічних заклинань і ефектів на {1} протягом {2} с.#to {1} for {2} sec", "Ефективність зцілення збільшено на {1}.#by {1}", en="Healing of the Ages" },
    [25003] = { "Мортира", "Вистрілити з мортири, яка падає за 25 м, завдаючи від {1} до {2} шкоди усім танкам в радіусі 5 м.#dealing {1} to {2}", en="Mortar" },
    [25008] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [25009] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [25010] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [25011] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [25012] = { "Подих блискавки", "Дихає блискавкою, миттєво завдаючи від {1} до {2} шкоди від природи одній цілі.#dealing {1} to {2}", en="Lightning Breath" },
    [25027] = { "Вогнемет", "{1} мани щосекунди.\nЗавдає від {2} до {3} шкоди щосекунди всім танкам перед вами в межах {4} м. Також уповільнює рух на {5}% і завдає {6} шкоди щосекунди протягом {7} с.#{1} mana#Deals {2} to {3}#within {4} y#movement to {5}% and deals {6}#for {7} sec", en="Flamethrower" },
    [25029] = { "Вогнемет", nil, "Завдає {1} шкоди щосекунди. Швидкість руху зменшено на {2}%.#Deals {1}#slowed by {2}", en="Flamethrower" },
    [25037] = { "Світлий ром Ромсі", ref=20875, en="Rumsey Rum Light" },
    [25049] = { "Вибухова хвиля", "Вивільняє полум'яну хвилю, яка завдає шкоди вогнем навколишнім ворогам та зменшує їх швидкість руху на {1} с.#speed for {1} sec", "Швидкість руху зменшено.", en="Blast Wave" },
    [25050] = { "Знак полум'я", "Збільшує отриману ворогом шкоду від вогню на {1} протягом {2} хв.#by {1} for {2} min", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Mark of Flames" },
    [25051] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [25053] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [25057] = { "Впущена зброя", nil, "Не тримає в руках зброю.", en="Dropped Weapon" },
    [25076] = { "Рефлекси кобри", "Швидкість атаки збільшено на {1}%, але зменшено шкоду.#by {1}", en="Cobra Reflexes" },
    [25101] = { "Бойовий клич", nil, "Силу атаки збільшено на {1}.#by {1}", en="Battle Shout" },
    [25112] = { "Виклик пустотника", "Виклик пустотника без витрат мани та уламків душ.", en="Summon Voidwalker" },
    [25114] = { "Збільшення відновлення мани", "Відновлює {1} мани кожні {2} с.#Restores {1} mana per {2} sec", en="Increased Mana Regen" },
    [25115] = { "Збільшення відновлення мани", "Відновлює {1} мани кожні {2} с.#Restores {1} mana per {2} sec", en="Increased Mana Regen" },
    [25117] = { "Слабка чарівна олія", "При нанесенні на зброю збільшує шкоду заклинань на {1}. Триває {2} хв.#spell damage by up to {1}#Lasts for {2} min", en="Minor Wizard Oil" },
    [25118] = { "Слабка олія мани", "При нанесенні на зброю відновлює {1} мани кожні {2} с. Триває {3} хв.#restores {1} mana to the caster every {2} sec#Lasts for {3} min", en="Minor Mana Oil" },
    [25119] = { "Проста чарівна олія", ref=25117, en="Lesser Wizard Oil" },
    [25120] = { "Проста олія мани", ref=25118, en="Lesser Mana Oil" },
    [25121] = { "Чарівна олія", ref=25117, en="Wizard Oil" },
    [25122] = { "Блискуча чарівна олія", "При нанесенні на зброю збільшує шкоду заклинань на {1} та збільшує ймовірність критичного удару заклять на {2}%. Триває {3} хв.#spell damage by up to {1}#Spell Critical chance by {2}%#Lasts for {3} min", en="Brilliant Wizard Oil" },
    [25123] = { "Блискуча олія мани", "При нанесенні на зброю відновлює {1} мани кожні {2} с та збільшує зцілення від заклять на {3}. Триває {4} хв.#restores {1} mana to the caster every {2} sec#increases the effect of healing spells by up to {3}#Lasts for {4} min", en="Brilliant Mana Oil" },
    [25146] = { "Трансмутація: Первородний вогонь", "Трасмутація серця вогню у три первородні вогні.", en="Transmute: Elemental Fire" },
    [25174] = { "Розсікаючий розкол", "Завдає звичайної шкоди плюс {1} ворогу та його найближчим союзникам, вражаючи до {2} цілей. Також зменшує броню на {3}.#plus {1} to#up to {2} target#armor by {3}", "Броню зменшено на {1}.#by {1}", en="Sundering Cleave" },
    [25185] = { "Свербіж", "Викликає у цілі свербіж, який з часом перетворюється на отруту.", "Ваша шкіра свербить", en="Itch" },
    [25187] = { "Каталізатор Вул'Зари", nil, "Швидкість руху зменшено на {1}%.\n{2} шкоди кожні {3} с.\nШкоду від жал Вул'Зари збільшено.#by {1}%#{2} damage every {3} sec", en="Hive'Zara Catalyst" },
    [25188] = { "Бойовий тупіт", "Відкидає навколишніх ворогів.", en="War Stomp" },
    [25189] = { "Огортання вітрами", "Оточує ворога циклоном на {1} с. Якщо ціль отримає шкоду, вона звільниться з полону вітрів.#up to {1} sec", "Приголомшено.", en="Enveloping Winds" },
    [25195] = { "Прокляття мови", "Примушує навколишніх ворогів говорити мовою демонів, сповільнюючи час вимови всіх заклять на {1}% протягом {2} с. Одночасно лише одне прокляття кожного чорнокнижника може бути задіяне на цілі.#by {1}% for {2} sec", "Вимову заклять сповільнено на {1}%.#by {1}%", en="Curse of Tongues" },
    [25198] = { "Отруйна хмара", "Завдає від {1} до {2} шкоди від природи навколишнім ворогам кожні {3} с протягом {4} с.#Inflicts {1} to {2} Nature#every {3} sec#for {4} sec", "Завдає від {1} до {2} шкоди від природи кожні {3} с.#{1} to {2} Nature#every {3} sec", en="Poison Cloud" },
    [25228] = { "Зв'язок душ", nil, "{1}% отриманої володарем шкоди буде перенаправлено на демона. Всю завдану шкоду збільшено на {2}%.#{1}% of damage#increased by {2}%", en="Soul Link" },
    [25247] = { "Далекоглядність", "Дозволяє поглянути в далечінь.", "Дальність зору збільшено, поки ви не почнете рухатись.", en="Longsight" },
    [25286] = { "Героїчний удар", "Сильна атака, що збільшує шкоду ближнього бою на {1} і спричиняє високий рівень загрози.#damage by {1}", en="Heroic Strike" },
    [25288] = { "Помста", "Миттєва контратака, що завдає від {1} до {2} шкоди та значно збільшує рівень загрози. Помста повинна слідувати за блокуванням, ухиленням або парируванням.#for {1} to {2} damage", en="Revenge" },
    [25289] = { "Бойовий клич", "Воїн кричить, збільшуючи силу атаки ближнього бою всіх учасників групи в межах {1} м на {2}. Триває {3} хв.#within {1} yards by {2}#Lasts {3} min", "Збільшує силу атаки ближнього бою на {1}.#power by {1}", en="Battle Shout" },
    [25290] = { "Благословення мудрості", "Благословляє дружню ціль, відновлюючи їй {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Blessing of Wisdom" },
    [25291] = { "Благословення могутності", "Благословляє дружню ціль, збільшуючи силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Blessing of Might" },
    [25292] = { "Священне світло", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Holy Light" },
    [25295] = { "Жало змії", "Жалить ціль, завдаючи {1} шкоди від природи протягом {2} с. Лише один ефект жала від кожного мисливця може бути активним на одній цілі.#{1} Nature damage over {2} sec", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature damage every {2} sec", en="Serpent Sting" },
    [25296] = { "Аспект яструба", "Мисливець переймає аспекти яструба, збільшуючи силу атаки дальнього бою на {1}. Одночасно може бути активним лише один аспект.#by {1}", "Збільшує силу атаки дальнього бою на {1}.#by {1}", en="Aspect of the Hawk" },
    [25297] = { "Цілющий дотик", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Touch" },
    [25298] = { "Зоряний вогонь", "Завдає цілі від {1} до {2} шкоди від аркани.#Causes {1} to {2} Arcane", en="Starfire" },
    [25299] = { "Омолодження", "Зцілює цілі {1} здоров'я протягом {2} с.#for {1} over {2} sec", "Зцілює {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Rejuvenation" },
    [25300] = { "Удар у спину", "Ударити ціль у спину, завдаючи їй {1}% від шкоди зброї та додатково {2} шкоди. Необхідно бути позаду цілі та тримати в правій руці кинджал. Збільшує довжину комбінації на {3} прийом.#causing {1}%#plus {2} to#Awards {3} combo", en="Backstab" },
    [25302] = { "Фінт", "Виконує оманливий випад, що не завдає шкоди та значно зменшує вашу загрозу. Це знизить ймовірність того, що ворог атакуватиме саме вас.", en="Feint" },
    [25304] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [25306] = { "Вогняна куля", "Кидає вогняну кулю, що завдає [{1}#causes {1} Fire][від {1} до {2}#causes {1} to {2} Fire] шкоди від вогню і додатково {1} шкоди від вогню протягом {2} с.#additional {1}#over {2} sec", "{1} шкоди від вогню кожні {2} с.#{1} Fire damage every {2} sec", en="Fireball" },
    [25307] = { "Тіньова стріла", "Випускає у ворога тіньову стрілу, що завдає [{1}#causing {1} Shadow][від {1} до {2}#causing {1} to {2} Shadow] шкоди тінню.", en="Shadow Bolt" },
    [25309] = { "Жертовний вогонь", "Обпалює ворога, завдаючи {1} шкоди вогнем і додатково {2} шкоди вогнем протягом {3} с.#enemy for {1} Fire#additional {2} Fire#over {3} sec", "{1} шкоди вогнем кожні {2} с.#{1} Fire damage every {2} sec", en="Immolate" },
    [25311] = { "Пошесть", "Оскверняє ціль, завдаючи {1} шкоди тінню протягом {2} с.#causing {1} Shadow#over {2} sec", "{1} шкоди тінню кожні {2} с.#{1} Shadow damage every {2} sec", en="Corruption" },
    [25314] = { "Велике зцілення", "Повільне закляття, що зцілює одній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Greater Heal" },
    [25315] = { "Оновлення", "Зцілює цілі {1} здоров'я протягом {2} с.#of {1} damage over {2} sec", "Зцілення {1} здоров'я кожні {2} с.#{1} damage every {2} sec", en="Renew" },
    [25316] = { "Молитва зцілення", "Потужна молитва, що зцілює всім учасникам групи в межах {1} м від {2} до {3} здоров'я.#within {1} yards for {2} to {3}", en="Prayer of Healing" },
    [25345] = { "Арканічні снаряди", "Запускає у ворога арканічні снаряди, що завдають {1} шкоди арканою щосекунди протягом {2} с.#causing {1}#for {2} sec", en="Arcane Missiles" },
    [25347] = { "Смертельна отрута V", ref=2835, en="Deadly Poison V" },
    [25349] = { "Смертельна отрута V", ref=2818, en="Deadly Poison V" },
    [25351] = { "Смертельна отрута V", ref=2823, en="Deadly Poison V" },
    [25357] = { "Хвиля зцілення", "Зцілює дружній цілі від {1} до {2} здоров'я.#for {1} to {2}", en="Healing Wave" },
    [25359] = { "Тотем поваби вітру", "Викликає тотем поваби вітру з {1} здоров'я. Тотем збільшує спритність учасників групи в межах {2} м на {3}. Триває {4} хв.#with {1} health#within {2} yards by {3}#Lasts {4} min", en="Grace of Air Totem" },
    [25360] = { "Поваба вітру", nil, "Збільшує спритність на {1}.#by {1}", en="Grace of Air" },
    [25361] = { "Тотем сили землі", "Викликає тотем сили землі з {1} здоров'я. Тотем збільшує силу учасників групи в межах {2} м на {3}. Триває {4} хв.#with {1} health#within {2} yards by {3}#Lasts {4} min", en="Strength of Earth Totem" },
    [25362] = { "Сила землі", nil, "Збільшує силу на {1}.#by {1}", en="Strength of Earth" },
    [25371] = { "Поглинання", nil, "Вас поглинають!", en="Consume" },
    [25424] = { "Отруйна стріла", "Стріляє у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison Bolt" },
    [25471] = { "Наказ атакувати", nil, "Мітка смерті...", en="Attack Order" },
    [25497] = { "Плювок отрути", "Плює у ворога отрутою, завдаючи шкоди від природи та додаткової шкоди кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Venom Spit" },
    [25516] = { "Аура командування", nil, "Зцілює {1} здоров'я кожні {2} с.\nШвидкість атаки збільшено на {3}%.\nШвидкість вимови заклять збільшено на {4}%.#Heals {1} health every {2} sec#Attack speed increased by {3}%#Casting speed increased by {4}%", en="Aura of Command" },
    [25605] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [25645] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [25646] = { "Смертельна рана", nil, "Ефективність зцілення зменшено на {1}%.#by {1}%", en="Mortal Wound" },
    [25651] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [25654] = { "Удар хвостом", nil, "Приголомшено.", en="Tail Lash" },
    [25655] = { "Впущена зброя", nil, "Не тримає в руках зброю.", en="Dropped Weapon" },
    [25656] = { "Піщана пастка", nil, "Ймовірність завдання удару зменшено на {1}%.\nНе можна вимовляти закляття.#by {1}%", en="Sand Trap" },
    [25660] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
