    [25668] = { "Вогняний ляпас", "Завдає цілі від {1} до {2} шкоди вогнем і збільшує отриману нею шкоду від вогню на {3} протягом {4} секунд.#Inflicts {1} to {2} Fire#by {3} for {4} sec", "Отриману шкоду від вогню збільшено на {1}.#by {1}", en="Flame Buffet" },
    [25669] = { "Рубання кінцівки", "Шанс відрубати кінцівку цілі при атаці в ближньому бою, завдаючи [{1}#causing {1} damage][від {1} до {2}#causing {1} to {2} damage] шкоди.", en="Decapitate" },
    [25675] = { "Північний олень", "Викликає та відпускає верхового північного оленя.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Reindeer" },
