    [25688] = { "Нараін!", "Змінює ваш зовнішній вигляд так, щоб ви були схожі на Нараіна Тихомрія.", "Ви Нараін! Тільки тсс!", en="Narain!" },
    [25690] = { "Їжа для мозку", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Через 10 секунд ви насититесь і будете відновлювати {4} мани кожні 5 секунд протягом {5} хв#Restores {1} health and {2} mana over {3} sec#gain {4} Mana#for {5} min", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Brain Food" },
    [25691] = { "Їжа для мозку", "Відновлює {1} здоров'я та {2} мани протягом {3} с. Потрібно залишатися в сидячому положенні під час їжі. Через 10 секунд ви насититесь і будете відновлювати {4} мани кожні 5 секунд протягом {5} хв#Restores {1} health and {2} mana over {3} sec#gain {4} Mana#for {5} min", "Відновлює {1} мани щосекунди.#Restores {1} mana", en="Brain Food" },
