    [25780] = { "Праведна лють", "Збільшує загрозу ваших атак святістю на {1}%. Триває {2} хв.#by {1}%#Lasts {2} min", "Збільшує загрозу ваших атак святістю на {1}%.#by {1}%", en="Righteous Fury" },
    [25782] = { "Велике благословення могутності", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення могутності\", що збільшує їхню силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Greater Blessing of Might" },
    [25786] = { "Токсичні випари", "Завдає {1} шкоди від природи навколишнім ворогам кожні {2} с протягом {3} хв.#Inflicts {1} Nature#every {2} sec#for {3} min", "Завдає {1} шкоди від природи кожні {2} с.#{1} Nature#every {2} sec", en="Toxic Vapors" },
    [25787] = { "Порив", "Ривок у ворога, що завдає [{1}#inflicting {1} damage][від {1} до {2}#inflicting {1} to {2} damage] шкоди цілі та її союзникам неподалік, а також відкидає їх.", en="Surge" },
    [25804] = { "Чорний ром Ромсі", ref=20875, en="Rumsey Rum Black Label" },
    [25805] = { "Осквернення душі", "Зменшує всі характеристики на {1}.\nЗавдає {2} шкоди від тіні кожні {3} с.#by {1}#{2} Shadow#every {3} sec", "Всі характеристики зменшено на {1}.\nЗавдає від {2} до {3} шкоди від тіні кожні {4} с.#by {1}#{2} to {3} Shadow#every {4} sec", en="Soul Corruption" },
    [25806] = { "Створіння Кошмару", "Бере під контроль гуманоїда до {1} рівня на {2} с.#level {1} for {2} sec", "Причаровано та спрямовано на руйнування.", en="Creature of Nightmare" },
