    [25863] = { "Виклик чорного кіразького бойового танка", "Викликає та відпускає верхового кіразького бойового танка. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Black Qiraji Battle Tank" },
    [25886] = { "Їжа", "Відновлює {1} здоров'я протягом {2} с. Потрібно залишатися в сидячому положенні під час їжі.#Restores {1} health over {2} sec", "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [25888] = { "Їжа", nil, "Відновлює {1} здоров'я щосекунди.#Restores {1} health", en="Food" },
    [25890] = { "Велике благословення світла", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення світла\", що підсилює ефект \"Священного світла\" на них на {1}, а \"Зблиску світла\" - на {2}. Триває {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#to {1} and the effect Flash of Light spells used on the target by up to {2}#Lasts {3} min", "Отримує {1} додаткового зцілення від \"Священного світла\" та {2} від \"Зблиску світла\".#Receives up to {1}#and up to {2}", en="Greater Blessing of Light" },
    [25891] = { "Удар землі", "Збільшує силу атаки ближнього та дального бою на {1}. Ефект триває {2} с.#power by {1}#for {2} sec", "Силу атаки ближнього та дального бою збільшено на {1}.#by {1}", en="Earthstrike" },
    [25894] = { "Велике благословення мудрості", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення мудрості\", що відновлює їм {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Greater Blessing of Wisdom" },
    [25895] = { "Велике благословення спасіння", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення спасіння\", що зменшує їхню загрозу на {1}% протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1}% for {2} min", "Зменшує загрозу на {1}%.#by {1}%", en="Greater Blessing of Salvation" },
    [25898] = { "Велике благословення королів", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення королів\", що збільшує їхні всі характеристики на {1}% протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1}% for {2} min", "Збільшує характеристики на {1}%.#by {1}%", en="Greater Blessing of Kings" },
