    [25909] = { "Затишшя", nil, "Зменшує загрозу на {1}%.#by {1}%", en="Tranquil Air" },
    [25916] = { "Велике благословення могутності", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення могутності\", що збільшує їхню силу атаки ближнього бою на {1} протягом {2} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#by {1} for {2} min", "Збільшує силу атаки ближнього бою на {1}.#by {1}", en="Greater Blessing of Might" },
    [25918] = { "Велике благословення мудрості", "Надає всім учасникам рейду або групи одного класу з ціллю \"Велике благословення мудрості\", що відновлює їм {1} мани кожні {2} с протягом {3} хв. Гравці можуть мати лише одне благословення від кожного паладина одночасно.#{1} mana every {2} seconds for {3} min", "Відновлює {1} мани кожні {2} с.#{1} mana every {2} sec", en="Greater Blessing of Wisdom" },
