    [25945] = { "Присуд правосуддя", en="Judgement of Justice" },
    [25953] = { "Виклик блакитного кіразького бойового танка", "Видає високочастотний звук, що змушує силітида-танка вилізти з нори під храму Ан'Кіражу. Силітид служить тому, хто його викликає, і може використовуватися як верхове створіння у храмі Ан'Кіража. Будь-яка ворожа дія проти вершника змушує танка повернутися під землю.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Blue Qiraji Battle Tank" },
    [25956] = { "Покращений присуд", "Зменшує час відновлення \"Присуду\" на {1} с.#by {1} sec", en="Improved Judgement" },
    [25989] = { "Токсин", nil, "Завдає від {1} до {2} шкоди кожні {3} с.\nСповільнює рух на {4}%.#Deals {1} to {2} damage every {3} sec#by {4}%", en="Toxin" },
    [25991] = { "Залп отруйних стріл", ref=21067, en="Poison Bolt Volley" },
    [25999] = { "Ривок кнура", nil, "Знерухомлено.", en="Boar Charge" },
    [26004] = { "Омела", "Подаруйте друзям святкові вітання!", "Вітання зі святами! Збільшує дух на {1}.#by {1}", en="Mistletoe" },
    [26013] = { "Дезертир", nil, "Ви покинули поле бою до його завершення і маєте зачекати, перш ніж потрапити на ще одне.", en="Deserter" },
    [26022] = { "Гонитва за правосуддям", "Підвищує швидкість руху та швидкість верхової їзди на {1}%. Не поєднується з іншими ефектами збільшення швидкості руху.#speed by {1}%", en="Pursuit of Justice" },
    [26025] = { "Пронизування", "Завдає ворогу фізичної шкоди кожні {1} с протягом {2} с.#for {1} sec#for {2} sec", "Завдає від {1} до {2} шкоди кожні {3} с.#{1} to {2} damage#every {3} sec", en="Impale" },
    [26030] = { "Ягоди вітроцвіту", ref=18229, en="Windblossom Berries" },
    [26038] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [26041] = { "Оскаженіння", nil, "Швидкість атаки збільшено на {1}%.#by {1}%", en="Frenzy" },
    [26042] = { "Психічний крик", "Вивільнює психічний крик, що змушує до {1} навколишніх ворогів тікати геть протягом {2} с.#up to {1} nearby#for {2} sec", "Втікає зі страху.", en="Psychic Scream" },
    [26043] = { "Бойовий клич", "Збільшує силу атаки ближнього бою учасників групи неподалік на {1} протягом {2} с.#by {1} for {2} sec", "Силу атаки ближнього бою збільшено на {1}.#by {1}", en="Battle Shout" },
    [26044] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [26049] = { "Спалення мани", "Вражає навколишніх ворогів антимагічними зарядами, що спалюють ману. За кожну одиницю спаленої мани ціль отримує {1} шкоди.#takes {1} damage", "Втікає зі страху.", en="Mana Burn" },
    [26050] = { "Плювок кислоти", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає від {1} до {2} шкоди від природи кожні {3} с.#Deals {1} to {2} nature#every {3} sec", en="Acid Spit" },
