    [26064] = { "Панцирний щит", "Зменшує шкоду отриману вашим вихованцем на {1}%, але збільшує інтервал між його атаками на {2}%. Триває {3} с.#takes by {1}#attacks by {2}#Lasts {3} sec", "Отриману шкоду зменшено на {1}%, а інтервал між атаками збільшено на {2}%.#reduced by {1}#increased by {2}", en="Shell Shield" },
    [26069] = { "Знемовлення", ref=3589, en="Silence" },
    [26070] = { "Страх", "Вселяє страх у ворога, змушуючи його тікати зі страху протягом {1} с. Одночасно лише одна ціль може бути наляканою.#for up to {1} sec", "Втікає зі страху.", en="Fear" },
    [26071] = { "Опутуюче коріння", "Обплутує ворога корінням, завдаючи шкоди від природи кожні {1} с та знерухомлюючи його на {2} с.#every {1} sec#up to {2} sec", "Знерухомлено.\nЗавдає шкоди від природи кожні {1} с.#every {1} sec", en="Entangling Roots" },
    [26072] = { "Хмара пилу", "Зменшує ймовірність завдання удару навколишніх ворогів на {1}% протягом {2} с.#by {1}% for {2} sec", "Ймовірність завдання удару зменшено на {1}%.#by {1}%", en="Dust Cloud" },
    [26073] = { "Вогненний спалах", "Завдає шкоди від вогню навколишнім ворогам.", en="Fire Nova" },
    [26077] = { "Свербіж", "Викликає у цілі свербіж, який з часом перетворюється на отруту.", "Ваша шкіра свербить", en="Itch" },
    [26078] = { "Каталізатор Векнісса", nil, "Швидкість руху зменшено на {1}%.\n{2} шкоди кожні {3} с.\nШкоду від силітидів Векнісса збільшено.#by {1}%#{2} damage every {3} sec", en="Vekniss Catalyst" },
    [26079] = { "Зведення з розуму", "Тимчасово зводить ворожу ціль з розуму, прискорюючи її атаку на {1}% та рух на {2}%, а також змушує її атакувати своїх союзників протягом {3} с.#attacks by {1}%#movement by {2}%#for {3} sec", "Причаровано.\nШвидкість атаки збільшено на {1}%.\nШвидкість руху збільшено на {2}%.#Attack speed increased by {1}%#Movement speed increased by {2}%", en="Cause Insanity" },
    [26083] = { "Вихор", "Атакує навколишніх ворогів сталевим вихром протягом {1} с, завдаючи звичайної шкоди плюс {2}.#lasts {1} sec#plus {2}", "Атакує навколишніх ворогів, завдаючи звичайної шкоди плюс {1}.#plus {1}", en="Whirlwind" },
    [26090] = { "Громовий тупіт", "Здригає землю громовою силою, завдаючи від {1} до {2} шкоди від природи всім ворогам у межах {3} м.#doing {1} to {2}#within {3} y", en="Thunderstomp" },
    [26099] = { "Бойовий клич", "Збільшує шкоду учасників групи неподалік на {1}%, а швидкісь атаки на {2}% протягом {3} с.#by {1}% and attack speed by {2}% for {3} sec", "Шкоду збільшено на {1}%, швидкість атаки збільшено на {2}%.#increased by {1}%#speed by {2}%", en="Battle Shout" },
    [26102] = { "Струмінь піску", nil, "Приголомшено.", en="Sand Blast" },
    [26108] = { "Проблиск божевілля", "Дезорієнтує ціль, змушуючи її безцільно блукати протягом {1} с.#wander aimlessly for up to {1} sec", "Дезорієнтовано.", en="Glimpse of Madness" },
    [26120] = { "Копія Збільшення шкоди від природи {1}#Increase Nature Dam {1}", ref=7690, en="Copy of Increase Nature Dam 50" },
    [26141] = { "Нівечення", "Завдає ворогу від {1} до {2} шкоди та сповільнює його рух на {3}% протягом {4} с.#plus {1} to {2} to#speed by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Hamstring" },
    [26143] = { "Муки розуму", "Завдає ворогу шкоди від тіні та зменшує його швидкість руху протягом {1} с.#for {1} sec", "Завдає шкоди від тіні протягом {1} с.\nШвидкість руху зменшено.#over {1} sec", en="Mind Flay" },
    [26157] = { "PX-238 Зимовий Дивовольт", nil, "Веселих свят!", en="PX-238 Winter Wondervolt" },
    [26166] = { "Обсидіанове провидіння", "Збільшує шкоду від магічних заклинань і ефектів на {1} та зменшує опір магії цілей ваших заклинань на {2} протягом {3} с.#effects by up to {1}#spell targets by {2} for {3} sec", "Магічну шкоду збільшено на {1}.\nОпір магії цілей ваших заклинань зменшено на {2}.#damage increased by up to {1}#targets reduced by {2}", en="Obsidian Insight" },
    [26168] = { "Хітинові шипи", "З вас проростають шипи, що завдають {1} шкоди від природи нападникам. Триває {2} с.#causing {1} Nature#Lasts {2} sec", "Завдає {1} шкоди від природи нападникам.#Causes {1} Nature", en="Chitinous Spikes" },
    [26175] = { "Збільшення проникності заклять {1}#Spell Penetration {1}", "Зменшує опір магії цілей ваших заклинань на {1}.#spell targets by {1}", en="Increased Spell Penetration 10" },
