    [28778] = { "Дзеркало Лотхіба", "Збільшує опір всім видам магії на {1} протягом {2} с.#of magic by {1} for {2} sec", "Всі опори магії збільшено на {1}.#by {1}", en="Loatheb's Reflection" },
    [28779] = { "Сутність Сапфірона", "Збільшує шкоду і зцілення від магічних заклинань і ефектів на {1} протягом {2} с.#magical spells and effects by up to {1} for {2} sec", "Шкоду та зцілення заклять збільшено на {1}.#up to {1}", en="Essence of Sapphiron" },
    [28780] = { "Око мерця", "Збільшує зцілення наступних {1} заклять на {2} протягом {3} с.#next {1} spells by up to {2} for {3} sec", "Зцілення заклять збільшено на {1}.#up to {1}", en="The Eye of the Dead" },
