    [30866] = { "Зосереджений розум", "Збільшує ймовірність опору ефектам знемовлення та переривання на {1}%.#by an additional {1}%", en="Focused Mind" },
    [30867] = { "Благословення природи", "Збільшує шкоду та зцілення ваших заклять на {1}% від інтелекту.#equal to {1}% of your Intellect", en="Nature's Blessing" },
    [30868] = { "Благословення природи", "Збільшує шкоду та зцілення ваших заклять на {1}% від інтелекту.#equal to {1}% of your Intellect", en="Nature's Blessing" },
    [30869] = { "Благословення природи", "Збільшує шкоду та зцілення ваших заклять на {1}% від інтелекту.#equal to {1}% of your Intellect", en="Nature's Blessing" },
    [30872] = { "Покращене ланцюгове зцілення", "Збільшує ефективність закляття \"Ланцюгове зцілення\" на {1}%.#by {1}%", en="Improved Chain Heal" },
    [30880] = { "Відлуння Лордерона", nil, "Збільшує шкоду ближнього і дальнього бою та заклять в бою з невмерлими на {1}%.#by {1}%", en="Echoes of Lordaeron" },
    [30892] = { "Спритність рук", "Зменшує ймовірність отримання критичної шкоди від атак ближнього та дального бою на {1}%. Також посилює на {2}% ефект зниження загрози від здібності \"Фінт\".#attacks by {1}#ability by {2}", en="Sleight of Hand" },
    [30894] = { "Загострені відчуття", "Посилює вашу здатність виявлення непомітності та зменшує ймовірність завдати вам удару закляттями та атаками дальнього бою на {1}%.#by {1}%", en="Heightened Senses" },
    [30902] = { "Смертоносність", "Збільшує вашу силу атаки на {1}%.#by {1}%", en="Deadliness" },
    [30919] = { "Вправність володіння зброєю", "Збільшує ваші навички володіння мечами, кулачною зброєю та кинджалами на {1}.#by {1}", en="Weapon Expertise" },
    [31016] = { "Потрошіння", "Завершальний рух, що завдає шкоди залежно від довжини комбінації та сили атаки:\n  1 прийом: {1}-{2} шкоди\n  2 прийоми: {3}-{4} шкоди\n  3 прийоми: {5}-{6} шкоди\n  4 прийоми: {7}-{8} шкоди\n  5 прийомів: {9}-{10} шкоди#1 point  : {1}-{2}#2 points: {3}-{4}#3 points: {5}-{6}#4 points: {7}-{8}#5 points: {9}-{10}", en="Eviscerate" },
    [31018] = { "Безжалісний укус", "Завершальний рух, що завдає шкоди в залежності від довжини комбінації та перетворює кожну одиницю енергії на додаткові {1} шкоди. Шкода збільшується від сили атаки.\n  1 прийом: {2}-{3} шкоди\n  2 прийоми: {4}-{5} шкоди\n  3 прийоми: {6}-{7} шкоди\n  4 прийоми: {8}-{9} шкоди\n  5 прийомів: {10}-{11} шкоди#{1} additional#1 point  : {2}-{3}#2 points: {4}-{5}#3 points: {6}-{7}#4 points: {8}-{9}#5 points: {10}-{11}", en="Ferocious Bite" },
    [31700] = { "Виклик чорного кіразького бойового танка", "Викликає та відпускає верхового кіразького бойового танка. Це дуже швидка верхова тварина.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Black Qiraji Battle Tank" },
    [43680] = { "Бездіяльність", "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", en="Idle" },
    [43681] = { "Неактивність", "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", en="Inactive" },
    [219003] = { "Бездіяльність", "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", "Ваші товариші по команді поскаржилися на вас за лінощі! Вступайте в PvP-бій, інакше вам буде зараховано неактивність і ви не зможете отримувати очки честі.", en="Idle" },
    [219004] = { "Неактивність", "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", "Ви не можете отримувати очки честі, поки не вступите в PvP-бій.\nЯкщо ви залишитесь в неактивності, вас виженуть з поля бою.", en="Inactive" },
    [301089] = { "Прапор Орди", "Несе прапор Орди. Принесіть прапор на свою базу, щоб захопити його.", "Несе прапор Орди. Принесіть прапор на свою базу, щоб захопити його.", en="Horde Flag" },
    [301091] = { "Прапор Альянсу", "Несе прапор Альянсу. Принесіть прапор на свою базу, щоб захопити його.", "Несе прапор Альянсу. Принесіть прапор на свою базу, щоб захопити його.", en="Alliance Flag" },
    [348005] = { "Отрута", "Завдає ворогу шкоди від природи кожні {1} с протягом {2} с.#every {1} sec#for {2} sec", "Завдає шкоди від природи кожні {1} с.#every {1} sec", en="Poison" },
    [349981] = { "Заряджений хронозаміщувач благословень", nil, "Благословення призупинено:\n[\n|T136109:24|t Лють Фенґа ({1} хв)#Fengus' Ferocity|r ({1}m)][\n|T136054:24|t Сміливість Мол'дара ({1} хв)#Mol'dar's Moxie|r ({1}m)][\n|T135930:24|t Кмітливість Сліп'кіка ({1} хв)#Slip'kik's Savvy|r ({1}m)][\n|T134153:24|t Рвучкий клич драконоборця ({1} хв)#Rallying Cry of the Dragonslayer|r ({1}m)][\n|T135759:24|t Благословення вождя ({1} хв)#Warchief's Blessing|r ({1}m)][\n|T132107:24|t Дух Зандаларів ({1} хв)#Spirit of Zandalar|r ({1}m)][\n|T135934:24|t Серенада піснеквіта ({1} хв)#Songflower Serenade|r ({1}m)][\n|T134334:24|t Темне пророцтво Вщуна ({1} хв)#Sayge's Dark Fortune|r ({1}m)][\n|T236403:24|t Благословення Чорноводдя ({1} хв)#Boon of Blackfathom|r ({1}m)][\n|T236424:24|t Іскра натхнення ({1} хв)#Spark of Inspiration|r ({1}m)][\n|T236368:24|t Запал дослідника храмів ({1} хв)#Fervor of the Temple Explorer|r ({1}m)][\n|T135763:24|t Міць Штормовію ({1} хв)#Might of Stormwind|r ({1}m)]\n\nПоки благословення призупинені, вони на вас не діють.", en="Supercharged Chronoboon Displacer" },
    [350025] = { "Крижана стріла", "Запускає у ворога крижану стрілу, що завдає від {1} до {2} шкоди кригою та зменшує швидкість руху на {3}% протягом {4} с.#causing {1} to {2}#by {3}% for {4} sec", "Швидкість руху зменшено на {1}%.#by {1}%", en="Frostbolt" },
    [355363] = { "Рвучкий клич драконоборця", "Збільшує шанс критичного удару заклять на {1}%, атак ближнього та дальнього бою на {2}% та збільшує силу атаки на {3}. Триває {4} хв.#spells by {1}%#ranged by {2}%#grants {3} attack#{4} min", "Збільшує шанс критичного удару заклять на {1}%, атак ближнього та дальнього бою на {2}% та збільшує силу атаки на {3}. Триває {4} хв.#spells by {1}%#ranged by {2}%#grants {3} attack#{4} min", en="Rallying Cry of the Dragonslayer" },
    [355365] = { "Дух Зандаларів", "Збільшує швидкість руху на {1}% та всі характеристики на {2}% протягом {3} год.#speed by {1}% and all stats by {2}% for {3} h", "Збільшує швидкість руху на {1}% та всі характеристики на {2}% протягом {3} год.#speed by {1}% and all stats by {2}% for {3} h", en="Spirit of Zandalar" },
    [355366] = { "Благословення вождя", "Збільшує запас здоров'я на {1}, швидкість атак ближнього бою на {2}% та відновлює {3} мани кожні {4} c.#hitpoints by {1}. {2}% haste#{3} mana regen every {4} sec", "Збільшує запас здоров'я на {1}, швидкість атак ближнього бою на {2}% та відновлює {3} мани кожні {4} c.#hitpoints by {1}. {2}% haste#{3} mana regen every {4} sec", en="Warchief's Blessing" },
    [364001] = { "Залізна душа", nil, "Режим хардкору\n[\nНепереможність#Never Known Defeat][\nПереможець Володара Вогню#Survivor of the Firelord][\nПереможець Тіньового Полум'я#Survivor of the Shadow Flame][\nПереможець Старого Бога#Survivor of the Old God][\nПереможець Проклятих#Survivor of the Damned][\nНезломлений самодостатній герой#Unbroken Self-Found Champion]\n", en="Soul of Iron" },
