    [364820] = { "Живий викид", "Завдає від {1} до {2} шкоди від вогню кожні {3} с.#Deals {1} to {2} Fire#every {3} sec", "Завдає від {1} до {2} шкоди від вогню кожні {3} с.#Deals {1} to {2} Fire#every {3} sec", en="Living Fallout" },
    [364838] = { "Пекло", "Завдає {1} шкоди вогнем кожні {2} с.#Deals {1} Fire#every {2} sec", "Завдає {1} шкоди вогнем кожні {2} с.#Deals {1} Fire#every {2} sec", en="Inferno" },
