    [365122] = { "Берсерк", ref=8269, en="Berserk" },
    [365663] = { "Розкол броні", "Розколює броню ворога, зменшуючи її на {1} за кожен ефект \"Розколу броні\". Ефект накопичується до {2} разів. Триває {3} с.#reducing it by {1} per#up to {2} times#Lasts {3} sec", "Броню зменшено.", en="Sunder Armor" },
    [366305] = { "Статична електрика", nil, "Пульсує статичною електрикою, завдаючи гравцям неподалік шкоди від природи при накопиченні {1} ефектів.#at {1} stack", en="Static Electricity" },
    [366909] = { "Рубінове полум'я", ref=364838, en="Ruby Flames" },
