    [367724] = { "Туман сну", nil, "Швидкість руху зменшено на {1}%.\n\nХочеться спати...#by {1}%", en="Dream Fog" },
    [367740] = { "Повзучий холод", nil, "Швидкість руху зменшено на {1}%.#by {1}%", en="Creeping Chill" },
    [367741] = { "Повне заморожування", "Повне заморожування.", "Повне заморожування.", en="Frozen Solid" },
    [367792] = { "Прискорення часу", "Швидкість руху збільшено на {1}%.\nШвидкість ближнього бою, дальнього бою та вимови заклять збільшено на {2}%.#speed increased by {1}%#haste increased by {2}%", "Швидкість руху збільшено на {1}%.\nШвидкість ближнього бою, дальнього бою та вимови заклять збільшено на {2}%.#speed increased by {1}%#Haste increased by {2}%", en="Temporal Acceleration" },
    [367888] = { "Дихання Сну", nil, "Спить.", en="Dream Breath" },
    [367928] = { "Осквернений удар", nil, "Приголомшено.", en="Corrupted Slam" },
    [367987] = { "Палаючий адреналін", nil, "Шкоду збільшено на {1}%.\nШвидкість збільшено на {2}%\nЗавдає шкоди в обсязі {3}% від максимального запасу здоров'я кожні {4} с.\nЗавдає від {5} до {6} шкоди навколишнім союзникам при смерті.#Damage increased by {1}%#Haste increased by {2}%#Deals {3}% of max#every {4} sec#Deals {5} to {6} damage", en="Burning Adrenaline" },
    [368003] = { "Несправна проводка", en="Faulty Wiring" },
    [368315] = { "Муки розуму", "Завдає шкоди від тіні ворогові та зменшує його швидкість руху.", "{1} шкоди від тіні щосекунди.\nШвидкість руху зменшено на {2}%.#{1} Shadow#by {2}%", en="Mind Flay" },
    [368329] = { "Кошмарні зарості", ref=24648, en="Nightmare Brambles" },
    [368515] = { "Тавро тіні", nil, "Отримання додаткової шкоди від \"Тавра тіні\".", en="Brand of Shadow" },
    [368521] = { "Тавро полум'я", nil, "Отримання додаткової шкоди від \"Тавра полум'я\".", en="Brand of Flame" },
    [368615] = { "Пульсуюча блискавка", nil, "Завдає шкоди від природи навколишнім ворогам кожні {1} с протягом {2} с. Окрім того, збільшує швидкість руху, атак та вимови заклять на {3}%.#every {1} sec for {2} sec#by {3}%", en="Pulse Lightning" },
    [368632] = { "Осквернена зброя", nil, "Ціль вашої оскверненої зброї.", en="Corrupted Weapon" },
    [368941] = { "Помах крил", "Завдає {1} шкоди ворогам в конусі перед заклиначем, відкидаючи їх.#Inflicts {1} damage", en="Wing Buffet" },
    [369080] = { "Помах крил", "Завдає {1} шкоди ворогам в конусі перед заклиначем, відкидаючи їх.#Inflicts {1} damage", en="Wing Buffet" },
    [369330] = { "Вогняний дощ", "Викликає вогняний дощ, що обпалює ворогів у зоні ураження, завдаючи від {1} до {2} шкоди вогнем кожні {3} с протягом {4} с.#for {1} to {2} Fire#every {3} sec#for {4} sec", "Отримання від {1} до {2} шкоди від вогню кожні {3} с.#{1} to {2} Fire#every {3} sec", en="Rain of Fire" },
    [370637] = { "Виклик скакуна-скелет", "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Skeletal Steed" },
    [370831] = { "блискавичники Таддіуса", "Прикріпити блискавичники на шию, щоб випадковим чином отримати позитивний або негативний заряд, що збільшує шкоду та зцілення на 1%. \n\nЦей ефект посилюється, якщо ви перебуваєте поруч із союзниками, які мають такий самий заряд, і завдає шкоди від природи союзникам, які мають протилежний заряд.", "Приборкання сили блискавки.", en="Thaddius' Lightning Bolts" },
    [370832] = { "Дар павука", "Проткнути себе іклом, щоб збільшити швидкість руху, швидкість атаки та швидкість вимови заклять на 15% протягом 1 год.", "Швидкість руху, швидкість атаки і швидкість вимови заклять збільшено на {1}%.\n\nВи почуваєтеся тривожно...#by {1}%", en="Gift of the Spider" },
    [371656] = { "Пливун", nil, "Швидкість руху збільшено на {1}%.#by {1}%", en="Quick Sand" },
    [381598] = { "Виклик скакуна-скелет", "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Skeletal Steed" },
    [381599] = { "Виклик скакуна-скелет", "Викликає та відпускає скакуна-скелета. Цей скакун служить тому, хто його викликає, і може використовуватися як верхове створіння у Наксрамасі. Будь-яка ворожа дія проти вершника змушує скакуна втікати.", "Швидкість руху збільшено на {1}%.#by {1}%", en="Summon Skeletal Steed" },
    [422621] = { "Підготовка", "Зменшує витрати ресурсів закляттями та здібностями на {1}%.#by {1}%", "Зменшує витрати ресурсів закляттями та здібностями на {1}%.#by {1}%", en="Preparation" },
}
