    [191280] = { "скупчення грибних спор", use="Ваші бойові здібності можуть викликати спору, що після смерті накладає на гравців неподалік \"Грибоцвіт\". Ефект триває 1 годину.\n\nГрибоцвіт \nЗавдає 150 шкоди від природи щосекунди, натомість збільшуючи ймовірність критичного удару в ближньому та дальньому бою та критичного ефекту заклять на 15%.", en="Fungal Spore Cluster" },
    [191288] = { "руна телепортації: Лігво крижаного змія", use="Переміщає вас до лігва крижаного змія в Наксрамасі.", en="Rune of Teleportation: Frostwyrm's Lair" },
    [191292] = { "ритуальний кинджал", use="Поглинає життєву силу навколишніх ворогів, збільшуючи витривалість на 3 за кожну уражену ціль. Ефект накопичується до 40 разів і триває 1 годину.", en="Ritual Dagger" },
    [191312] = { "захисна філактерія", equip="Захищає від атаки, яка мала б вас убити. Цей ефект також надає вам невразливість до шкоди на 3 секунди і знищує філактерію.", en="Failsafe Phylactery" },
    [191313] = { "маска смерті", use="Прийняти образ мешканця Наксрамаса.", en="Mask of Death" },
    [191414] = { "кістяний артефакт", use="Захоплює душу мертвої цілі, надаючи вам сприятливий ефект. Ефект триває 1 годину.", en="Skeletal Artifact" },
    [191458] = { "знищена філактерія", flavor="Більше не принесе жодної користі.", en="Shattered Phylactery" },
    [191459] = { "руна удачі", use="Посилює Кел'Тузада та його лейтенантів некромантичною енергією, збільшуючи їхній запас здоров'я та шкоду. Посилені вороги принесуть додаткову здобич.\n\nЦей ефект накопичується і триває цілий тиждень.", en="Rune of Fortune" },
    [191477] = { "кістяний конев'яз", use="Встановити кістяний конев'яз.\n\nУчасники групи можуть скористатись ним, щоб отримати скакуна-скелета.", en="Skeletal Hitching Post" },
    [191480] = { "скакун-скелет", use=381599, en="Skeletal Steed" },
    [191481] = { "гербова накидка майстерності", flavor="Свідчення майстерності.", en="Tabard of Mastery" },
    [191550] = { "книга смертекаменів: Маска смерті", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на маску смерті.", en="Book of Deathstones: Mask of Death" },
    [191605] = { "книга смертекаменів: Руна телепортації I", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на руну телепортації.", en="Book of Deathstones: Rune of Teleportation I" },
    [191606] = { "книга смертекаменів: Сфера осквернення", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на сферу осквернення.", en="Book of Deathstones: Orb of Corruption" },
    [191607] = { "книга смертекаменів: Кістяний артефакт", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на кістяний артефакт.", en="Book of Deathstones: Skeletal Artifact" },
    [191608] = { "книга смертекаменів: Жезл некромантії", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на жезл некромантії.", en="Book of Deathstones: Rod of Necromancy" },
    [191609] = { "книга смертекаменів: Скупчення грибних спор", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на скупчення грибних спор.", en="Book of Deathstones: Fungal Spore Cluster" },
    [191610] = { "книга смертекаменів: Ритуальний кинджал", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на ритуальний кинджал.", en="Book of Deathstones: Ritual Dagger" },
    [191611] = { "книга смертекаменів: Захисна філактерія", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на захисну філактерію.", en="Book of Deathstones: Failsafe Phylactery" },
    [191612] = { "книга смертекаменів: Руна телепортації II", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на руну телепортації.", en="Book of Deathstones: Rune of Teleportation II" },
    [191613] = { "книга смертекаменів: Руна удачі", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на руну удачі.", en="Book of Deathstones: Rune of Fortune" },
    [191614] = { "книга смертекаменів: Кістяний конев'яз", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на кістяний конев'яз.", en="Book of Deathstones: Skeletal Hitching Post" },
    [191656] = { "сутність смерті", en="Death's Essence" },
    [191660] = { "блискавичники Таддіуса", use=370831, en="Thaddius' Lightning Bolts" },
    [191661] = { "жахливе павуче ікло", use=370832, en="Monstrous Spider Fang" },
    [191664] = { "книга смертекаменів: Блискавичники Таддіуса", flavor="Фоліант, що детально описує мистецтво перетворення смертекаменів на блискавичники Таддіуса.", en="Book of Deathstones: Thaddius' Lightning Bolts" },
